window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s10-217","number":778,"surah":10,"verses":[80],"references":[{"surah":10,"verses":[80]}],"verseLabel":"يونس: 80","question":"لماذا جاء الانتقال مباشرة من ﴿فلما جاء السحرة﴾ إلى ﴿قال لهم موسى﴾، ولم يذكر القرآن تفاصيل استقبالهم؟","answer":"طوى السياق ما لا يتصل بالمواجهة ليضع القارئ أمام لحظة التحدي مباشرة؛ فالمقصود إبراز ثبات موسى وإفساد السحرة، لا وصف مقدماتهم. وهذا الإيجاز يسرّع إيقاع المشهد ويزيد ترقّب النتيجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص38، تحت «وجه الفصل بالقول»","url":""}]},{"id":"s10-218","number":779,"surah":10,"verses":[81],"references":[{"surah":10,"verses":[81]}],"verseLabel":"يونس: 81","question":"لماذا قال موسى للسحرة: ﴿ما جئتم به السحر﴾، ولم يقل: «هذا سحر»؟","answer":"علّق الحكم بما أحضروه هم، ليكشف أن الباطل داخل في فعلهم وصناعتهم، لا في آية موسى، ثم أتبع ذلك بإبطال عملهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص43، تحت «دلالة الإبطال في الآية»","url":""}]},{"id":"s10-219","number":780,"surah":10,"verses":[81],"references":[{"surah":10,"verses":[81]}],"verseLabel":"يونس: 81","question":"لماذا أكد موسى: ﴿إن الله سيبطله﴾، ولم يقل: «يبطله الله»؟","answer":"جاء التوكيد بـ﴿إن﴾ ليقابل ثقة السحرة بباطلهم ويثبت أن إبطال السحر وعد محقق، لا احتمال فيه. أما السين فتشير إلى وقوع الإبطال في وقت قريب، فاجتمع في العبارة توكيد الوعد وقرب ظهوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص48، تحت «نكتة التوكيد بـ﴿إن﴾»","url":""}]},{"id":"s10-220","number":781,"surah":10,"verses":[82],"references":[{"surah":10,"verses":[82]}],"verseLabel":"يونس: 82","question":"لماذا وصف السحرة بأنهم ﴿المفسدين﴾، ولم يقتصر على وصفهم بالسحرة؟","answer":"لأن خطرهم لم يكن في ممارسة السحر فحسب، بل في توظيفه لتلبيس الباطل على الناس ومقاومة الحق. فلفظ ﴿المفسدين﴾ يكشف أثر فعلهم في المجتمع، ويجعل المواجهة مواجهةَ إفسادٍ وإصلاح، لا مجرد منافسة بين سحرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص53، تحت «دلالة الجمع التام للفظ ﴿المفسدين﴾»","url":""}]},{"id":"s10-221","number":782,"surah":10,"verses":[82],"references":[{"surah":10,"verses":[82]}],"verseLabel":"يونس: 82","question":"ما سر التعبير بقوله تعالى: ﴿ويحق الله الحق﴾، ولم يقل فقط: «وينصر الله الحق»؟","answer":"النصر قد يُفهم على أنه غلبة مؤقتة في موقف، أما إحقاق الحق فأعمق؛ فهو إظهاره وتثبيته وإبطال ما عارضه. لذلك ناسب المقام الذي واجه فيه الوحيُ سحرًا مموّهًا، فتكفّل الله بإظهار حقيقة الحق وإسقاط الباطل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص58، تحت «تعريف لفظ ﴿الحق﴾»","url":""}]},{"id":"s10-222","number":783,"surah":10,"verses":[82],"references":[{"surah":10,"verses":[82]}],"verseLabel":"يونس: 82","question":"لماذا قُدّم ذكر إحقاق الحق على إبطال عمل المفسدين في سياق الآية؟","answer":"لأن المقصود الأعظم إثبات الحق، أما إبطال الباطل فجاء تابعًا له؛ فإذا ظهر الحق انكشف فساد ما سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص63، تحت «دلالة حذف الجار في الآية»","url":""}]},{"id":"s10-223","number":784,"surah":10,"verses":[83],"references":[{"surah":10,"verses":[83]}],"verseLabel":"يونس: 83","question":"ما سر التعبير بقوله تعالى: ﴿فما آمن لموسى إلا ذرية من قومه﴾، مع أن الآيات كانت ظاهرة؟","answer":"أبرز التعبير أن الذين بادروا إلى الإيمان كانوا فئة قليلة أو ناشئة في قوم مستضعفين، لا جمهورًا قادرًا على مواجهة فرعون. فظهور الآية وحده لا يكفي لمن استسلم للخوف؛ ولذلك ذكرت الآية خوفهم من فرعون وملئه عقب ذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص68، تحت «بلاغة الإيجاز بالقصر»","url":""}]},{"id":"s10-224","number":785,"surah":10,"verses":[83],"references":[{"surah":10,"verses":[83]}],"verseLabel":"يونس: 83","question":"ما سر ذكر الله ﴿فرعون وملأهم﴾، ولم يذكر فرعون وحده؟","answer":"لأن الاستبداد لا يقوم بالحاكم وحده؛ فملؤه هم أهل المشورة والتأييد الذين يزينون له الفتنة ويضغطون على الناس. فالجمع يكشف أن مقاومة الإيمان كانت منظومة يتعاون فيها صاحب السلطة وحاشيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص73، تحت «بيان علة عطف ﴿فرعون وملئهم﴾»","url":""}]},{"id":"s10-225","number":786,"surah":10,"verses":[84],"references":[{"surah":10,"verses":[84]}],"verseLabel":"يونس: 84","question":"لماذا بدأ موسى خطابه بقوله: ﴿يا قوم إن كنتم آمنتم بالله فعليه توكلوا﴾؟","answer":"نقلهم من مجرد إعلان الإيمان إلى مقتضاه العملي؛ فالإيمان الذي لا يورث التوكل يبقى دعوى لا تصمد أمام الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص83، تحت «دلالة الفاء في ﴿فعليه توكلوا﴾»","url":""}]},{"id":"s10-226","number":787,"surah":10,"verses":[85],"references":[{"surah":10,"verses":[85]}],"verseLabel":"يونس: 85","question":"لماذا جاء جواب المؤمنين: ﴿على الله توكلنا﴾ بتقديم الجار والمجرور؟","answer":"لتخصيص التوكل بالله وحده، وإظهار أن اعتمادهم لم ينتقل إلى فرعون ولا إلى أسباب القوة الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص88، تحت «معنى الفاء في ﴿فقالوا﴾»","url":""}]},{"id":"s10-227","number":788,"surah":10,"verses":[86],"references":[{"surah":10,"verses":[86]}],"verseLabel":"يونس: 86","question":"لماذا طلب المؤمنون النجاة بقولهم: ﴿ونجنا برحمتك من القوم الكافرين﴾، ولم ينسبوا النجاة إلى توكلهم؟","answer":"لأن التوكل سبب قلبي، أما النجاة الفعلية فمن رحمة الله وحدها. فجاء الدعاء جامعًا بين إعلان الاعتماد عليه وطلب أثر رحمته، وفيه اعتراف بأن قوة الكافرين لا تُدفع إلا بعون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص93، تحت «نكتة جمع ﴿المفسدين﴾»","url":""}]},{"id":"s10-228","number":789,"surah":10,"verses":[87],"references":[{"surah":10,"verses":[87]}],"verseLabel":"يونس: 87","question":"لماذا قال موسى: ﴿واجعلوا بيوتكم قبلة﴾ ثم أتبعها بـ﴿وأقيموا الصلاة﴾؟","answer":"حوّل البيوت إلى مواضع اجتماع على العبادة عند الخوف، ثم جعل الصلاة عماد هذا الاجتماع؛ فالمكان وحده لا يصنع الثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص105، تحت «علة تنوين البيوت وتنكيرها»","url":""}]},{"id":"s10-229","number":790,"surah":10,"verses":[87],"references":[{"surah":10,"verses":[87]}],"verseLabel":"يونس: 87","question":"لماذا جمع الدعاء بين ﴿واجعلوا بيوتكم قبلة﴾ و﴿أقيموا الصلاة﴾؟","answer":"لأن المؤمنين كانوا تحت ضغط يمنعهم من إظهار عبادتهم، فاحتاجوا إلى مكان يجتمعون فيه وإلى عبادة تثبت صلتهم بالله. جمع الأمران بين حماية الجماعة في موضعها، وتقوية قلوبها بصلاتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص108، تحت «توجيه جمع فعلي ﴿أقيموا﴾ و﴿اجعلوا﴾»","url":""}]},{"id":"s10-230","number":791,"surah":10,"verses":[88],"references":[{"surah":10,"verses":[88]}],"verseLabel":"يونس: 88","question":"لماذا دعا موسى على فرعون وملئه بقولـه: ﴿ربنا اطمس على أموالهم واشدد على قلوبهم﴾؟","answer":"لأن المال والسلطان كانا سبب اغترارهم وإضلالهم؛ فجاء الدعاء بإزالة آلة البطر، ثم بسلب قابلية الانتفاع بالآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص113، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-231","number":792,"surah":10,"verses":[89],"references":[{"surah":10,"verses":[89]}],"verseLabel":"يونس: 89","question":"كيف نُسبت إجابة الدعاء إلى موسى وهارون مع أن الآيات تذكر دعاء موسى بوضوح؟","answer":"جاءت التثنية لتشمل دعاء هارون وتأمينه، فالتأمين دعاءٌ من وجه وإن لم يُذكر بلفظه. ونسبة الإجابة إليهما معًا تُظهر وحدة الرسالة وتساند النبيين في مواجهة فرعون، لا أن الدعاء كان صادرًا من موسى وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص114، تحت «دلالة التثنية في ﴿دعوتكما﴾»","url":""}]},{"id":"s10-233","number":794,"surah":10,"verses":[98],"references":[{"surah":10,"verses":[98]}],"verseLabel":"يونس: 98","question":"لماذا استُثني قوم يونس بقولـه: ﴿إلا قوم يونس لما آمنوا﴾ بعد ذكر القرى المكذبة؟","answer":"لأنهم كسروا القاعدة التي عرضتها الآيات: آمنوا قبل نزول العذاب، فانتفعوا بإيمانهم وكُشف عنهم العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص222، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-234","number":795,"surah":10,"verses":[98],"references":[{"surah":10,"verses":[98]}],"verseLabel":"يونس: 98","question":"لماذا جاءت الفاء في ﴿فآمنت فنفعها إيمانها﴾ مرتين؟","answer":"الفاء الأولى تصوّر سرعة الإيمان عند معاينة العذاب، والثانية ترتب نفع الإيمان على حصوله. وفي هذا تمييز بين إيمانٍ جاء في وقت لا ينفع فيه التأخير، وأثرٍ ترتب عليه رفع العذاب؛ بخلاف إيمان من سبقته المهلة ثم أصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص229، تحت «دلالة الفاء في دخولها على ﴿فآمنت﴾»","url":""}]},{"id":"s10-235","number":796,"surah":10,"verses":[99],"references":[{"surah":10,"verses":[99]}],"verseLabel":"يونس: 99","question":"ما سر التعبير بقوله تعالى: ﴿ولو شاء ربك لآمن من في الأرض كلهم جميعًا﴾؟","answer":"ليقرر أن اختلاف الناس واقع بحكمة ومشيئة، وأن وظيفة الرسول البلاغ لا إكراه القلوب على الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص241، تحت «دلالة ﴿لو﴾ غير الجازمة»","url":""}]},{"id":"s10-237","number":798,"surah":10,"verses":[100],"references":[{"surah":10,"verses":[100]}],"verseLabel":"يونس: 100","question":"ما سر وصف الله الرافضين للهدى بقوله: ﴿ويجعل الرجس على الذين لا يعقلون﴾؟","answer":"لأن ترك استعمال العقل في آيات الله يورث صاحبه قذارة معنوية وضلالًا، فجاء الرجس جزاءً مناسبًا لتعطيل آلة الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص257، تحت «دلالة وضع الذين ﴿لا يعقلون﴾ بدل ﴿لا يؤمنون﴾»","url":""}]},{"id":"s10-238","number":799,"surah":10,"verses":[101],"references":[{"surah":10,"verses":[101]}],"verseLabel":"يونس: 101","question":"ما سر التعبير بقوله تعالى: ﴿انظروا ماذا في السماوات والأرض﴾، ولم يقل: «اعلموا»؟","answer":"النظر أبلغ في مقام الاستدلال؛ لأنه يوجه الإنسان إلى المعاينة والتأمل في دلائل القدرة المنتشرة أمامه. أما العلم المجرد فقد يحصل من خبر، فجاء الأمر بالنظر ليوقظ الحس والعقل معًا، ويجعل آيات الكون طريقًا إلى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص261، تحت «وجوب النظر في آيات القدرة»","url":""}]},{"id":"s10-240","number":801,"surah":10,"verses":[103],"references":[{"surah":10,"verses":[103]}],"verseLabel":"يونس: 103","question":"لماذا جاءت نجاة الرسل والمؤمنين في قوله: ﴿ثم ننجي رسلنا والذين آمنوا﴾ بعد ذكر أيام المكذبين؟","answer":"لئلا ينصرف الوعيد إلى أن العذاب يعمّ الجميع؛ فبعد ذكر مصير المكذبين أعقب بقاعدة الرحمة والعدل: إنجاء الرسل ومن آمن. ولفظ ﴿ثم﴾ يرسم تعاقب المشهد: يمهل المكذبون، ثم يقع الجزاء، ثم تظهر نجاة أهل الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص285، تحت «دلالة العطف بالفاء»","url":""}]},{"id":"s10-241","number":802,"surah":10,"verses":[104],"references":[{"surah":10,"verses":[104]}],"verseLabel":"يونس: 104","question":"لماذا جاء النداء العام: ﴿يا أيها الناس﴾ عند الحديث عن الشك في الدين؟","answer":"لأن الشك في أصل الدين ليس شأن جماعة بعينها، بل خطر يمكن أن يعرض للإنسان من حيث هو إنسان. فجاء النداء عامًا ليوقظ الجميع، ثم أقام البرهان على أن العبادة لا تكون إلا لمن يملك الضر والنفع والحياة والموت.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص297، تحت «دلالة ﴿في﴾ في قوله ﴿إن كنتم في شك﴾»","url":""}]},{"id":"s10-243","number":804,"surah":10,"verses":[107],"references":[{"surah":10,"verses":[107]}],"verseLabel":"يونس: 107","question":"ما سر التعبير بقوله تعالى: ﴿فلا كاشف له إلا هو﴾، فحصر كشف الضر بعد ذكر المس؟","answer":"لأن من يملك إيقاع الضر وحده يملك كشفه وحده، فالحصر يقطع كل تعلق بغير الله عند الشدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص329، تحت «معنى ﴿فلا كاشف له﴾»","url":""}]},{"id":"s10-244","number":805,"surah":10,"verses":[108],"references":[{"surah":10,"verses":[108]}],"verseLabel":"يونس: 108","question":"لماذا قابلت الآية بين ﴿فمن اهتدى﴾ و﴿من ضل﴾، ثم جعلت أثر كل منهما على صاحبه؟","answer":"لترسّخ مبدأ المسؤولية الفردية: الهداية نفعها لصاحبها، والضلال لا يتعدى ضرره إلى غيره. وجاءت المقابلة في تركيب متوازٍ حتى يرى القارئ أن الطريقين متقابلان، لكن نتيجة كل واحد منهما راجعة إلى سالكه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص339، تحت «نكتة الفصل في ﴿فمن يهتدي فإنما يهتدي لنفسه﴾»","url":""}]},{"id":"s10-245","number":806,"surah":10,"verses":[109],"references":[{"surah":10,"verses":[109]}],"verseLabel":"يونس: 109","question":"لماذا جمع ختام السورة بين ﴿واتبع ما يوحى إليك﴾ و﴿واصبر﴾؟","answer":"لأن اتباع الوحي يحدد الطريق، والصبر يعين على الثبات فيه. فليس المطلوب معرفة الحق فقط، بل احتمال أذى المكذبين ومواصلة الدعوة دون استعجال؛ ولذلك جمع الختام بين مصدر الهداية وأداة الاستمرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص359، تحت «دلالة الأمر في ﴿واتبع﴾ و﴿واصبر﴾»","url":""}]},{"id":"s10-246","number":807,"surah":10,"verses":[91],"references":[{"surah":10,"verses":[91]}],"verseLabel":"يونس: 91","question":"لماذا قال فرعون عند الغرق: ﴿آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل﴾، فذكر بني إسرائيل؟","answer":"كان إيمانه متأخرًا تابعًا لإيمان من عاداهم، فجاء ذكرهم كاشفًا أنه لم يصدر عن بصيرة واختيار، بل عن معاينة الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص169، تحت «نكتة الإيجاز عن المسند إسنادًا للإنجاء بالبدن»","url":""}]},{"id":"s10-247","number":808,"surah":10,"verses":[92],"references":[{"surah":10,"verses":[92]}],"verseLabel":"يونس: 92","question":"ما سر التعبير بقوله تعالى لفرعون: ﴿فاليوم ننجيك ببدنك﴾، مع أن المقام مقام هلاك؟","answer":"النجاة هنا ليست نجاة تكريم، بل إبقاء للجسد ظاهرًا ليكون آية لمن بعده. فاختيار ﴿ببدنك﴾ يخرج المعنى من إنقاذ الروح إلى إظهار الجسد، ويجعل هلاك الطاغية نفسه وسيلة لعبرة الأجيال.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص174، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-248","number":809,"surah":10,"verses":[93],"references":[{"surah":10,"verses":[93]}],"verseLabel":"يونس: 93","question":"ما سر وصف الله مكان بني إسرائيل بقوله: ﴿مبوأ صدق﴾، ولم يكتف بذكر أنه مكان إقامة؟","answer":"لفظ ﴿مبوأ﴾ يدل على المكان المهيأ المستقر، وإضافته إلى ﴿صدق﴾ تمنح الإقامة معنى الأمن والتمكين وصحة الوعد، لا مجرد النزول في أرض. فالتعبير يربط النعمة بالمصداقية الإلهية التي تحققت بعد الاستضعاف.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص179، تحت «التعبير عن فعل الرزق ماضيًا ومطلقًا»","url":""}]},{"id":"s10-249","number":810,"surah":10,"verses":[94],"references":[{"surah":10,"verses":[94]}],"verseLabel":"يونس: 94","question":"لماذا جاء الخطاب للنبي: ﴿فإن كنت في شك مما أنزلنا إليك﴾ مع أنه ليس شاكًّا؟","answer":"هو خطاب على سبيل الفرض والمحاجة، ليقطع طريق الشك عند المخاطبين ويقرر أن ما أنزل إليه ثابت تؤيده كتب أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص189، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-250","number":811,"surah":10,"verses":[95],"references":[{"surah":10,"verses":[95]}],"verseLabel":"يونس: 95","question":"لماذا جاء النهي: ﴿ولا تكونن من الذين كذبوا بآيات الله﴾ بصيغة التحذير الشديد؟","answer":"لأن النهي لا يواجه فعلًا عابرًا، بل يحذر من الانضمام إلى صفٍّ عُرف بالتكذيب بعد قيام الحجة. فالتعبير بـ﴿من الذين﴾ يجعل الخطر في الانتساب إلى جماعتهم ومنهجهم، لا في مجرد وقوع خطأ فردي.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص199، تحت «سرّ التوكيد باللام في ﴿لقد جاءتكم الحق﴾»","url":""}]},{"id":"s10-251","number":812,"surah":10,"verses":[96],"references":[{"surah":10,"verses":[96]}],"verseLabel":"يونس: 96","question":"ما سر التعبير بقوله تعالى: ﴿إن الذين حقت عليهم كلمة ربك لا يؤمنون﴾؟","answer":"بيّن أن الإصرار المتراكم على التكذيب بلغ بهم حدًّا يستحقون معه كلمة العذاب، فلا تنفعهم الآيات بعد اختيارهم العناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص209، تحت «وجه إضافة الآيات إلى الله»","url":""}]},{"id":"s10-252","number":813,"surah":10,"verses":[97],"references":[{"surah":10,"verses":[97]}],"verseLabel":"يونس: 97","question":"ما سر التعبير في قوله تعالى: ﴿ولو جاءتهم كل آية لا يؤمنون﴾، ولم تقل: «ولو جاءتهم آية»؟","answer":"المبالغة في ﴿كل آية﴾ تقطع الوهم بأن المشكلة نقص في الأدلة؛ فلو اجتمعت لهم الآيات كلها لبقي العناد مانعًا من الإيمان. وهكذا تنقل الآية سبب الانحراف من ضعف البرهان إلى فساد القابلية له.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص214، تحت «إيثار لفظ ﴿كل﴾»","url":""}]},{"id":"s10-253","number":814,"surah":10,"verses":[105],"references":[{"surah":10,"verses":[105]}],"verseLabel":"يونس: 105","question":"ما سر التعبير بقوله تعالى: ﴿فأقم وجهك للدين حنيفًا﴾، ولم يقل: «أقم نفسك»؟","answer":"تصوير التوجه بالوجه يجعل الإقبال على الدين إقبالًا كاملًا ظاهرًا وباطنًا، كأن صاحبه صرف وجهه كله عن طرق الشرك إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص313، تحت «بلاغة الكناية في ﴿فأقم وجهك للدين حنيفًا﴾»","url":""}]},{"id":"s10-254","number":815,"surah":10,"verses":[76],"references":[{"surah":10,"verses":[76]}],"verseLabel":"يونس: 76","question":"لماذا اجتمع التوكيد بـ﴿إن﴾ واللام في قولهم: ﴿إن هذا لسحر مبين﴾؟","answer":"اجتماع التوكيدين يكشف شدة تمسكهم بالاتهام، لا قوة حجتهم؛ فقد بادروا إلى إحاطة قولهم بأدوات الجزم قبل إقامة دليل. وكأن العبارة تصف عنادًا يحاول أن يعوّض ضعف البرهان بصيغة قاطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص11، تحت «دلالة التدرج في الآية»","url":""}]},{"id":"s10-255","number":816,"surah":10,"verses":[77],"references":[{"surah":10,"verses":[77]}],"verseLabel":"يونس: 77","question":"لماذا ختم موسى كلامه بقوله: ﴿ولا يفلح الساحرون﴾؟","answer":"حوّل الإنكار من مجرد ردّ دعواهم إلى تقرير عاقبة طريقهم؛ فالسحر قد يخدع العين، لكنه لا يحقق فلاحًا ولا بقاءً.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص12، تحت «النفي في قوله ﴿ولا يفلح الساحرون﴾»","url":""}]},{"id":"s10-256","number":817,"surah":10,"verses":[78],"references":[{"surah":10,"verses":[78]}],"verseLabel":"يونس: 78","question":"لماذا اختاروا الفعل ﴿تلفتنا﴾ في اعتراضهم على موسى، ولم يقولوا: «تضلنا»؟","answer":"لفظ ﴿تلفتنا﴾ يصور دعوى أنهم يُنتزعون عن طريق آبائهم ويُصرفون عن نظامهم العام، فهو أوسع من مجرد إضلال فرد. وبذلك يظهر أن اعتراضهم كان دفاعًا عن نفوذ اجتماعي وموروث، لا بحثًا عن الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص24، تحت «الغرض من الاستفهام في ﴿أجئتنا﴾»","url":""}]},{"id":"s10-257","number":818,"surah":10,"verses":[79],"references":[{"surah":10,"verses":[79]}],"verseLabel":"يونس: 79","question":"لماذا نسب القرآن جمع السحرة إلى فرعون بقوله: ﴿ائتوني بكل ساحر﴾؟","answer":"لأن الحشد كان بأمره وتدبيره، فإسناد الفعل إليه يكشف أنه صاحب المشروع في مقاومة الحق، والآخرون أدوات تنفيذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص30، تحت «إسناد إتيان السحرة إلى فرعون»","url":""}]},{"id":"s10-258","number":819,"surah":10,"verses":[80],"references":[{"surah":10,"verses":[80]}],"verseLabel":"يونس: 80","question":"لماذا قال موسى للسحرة: ﴿ألقوا ما أنتم ملقون﴾، ولم يسمِّ ما معهم سحرًا؟","answer":"تجاهل موسى تسمية باطلهم سحرًا في مقام التحدي؛ فترك لهم أن يصفوا عملهم بأنفسهم، ثم وعد بإبطال ما سيظهر. وفي العبارة ثقة بأن الحقيقة لا تحتاج إلى أن يمنح الباطل اسمًا يرفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص39، تحت «دلالة فعل الأمر ﴿ألقوا﴾»","url":""}]},{"id":"s10-259","number":820,"surah":10,"verses":[81],"references":[{"surah":10,"verses":[81]}],"verseLabel":"يونس: 81","question":"ما الفرق في المشهد بين ﴿ما جئتم به﴾ و﴿ما يأفكون﴾؟","answer":"الأول يواجه مادة السحر التي أحضروها، والثاني يكشف أثرها الكاذب في قلب الحقائق؛ فبطلان الصنعة يتبعه بطلان التلبيس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص46، تحت «دلالة أداة النفي في الآية»","url":""}]},{"id":"s10-260","number":821,"surah":10,"verses":[82],"references":[{"surah":10,"verses":[82]}],"verseLabel":"يونس: 82","question":"ما سر التعبير بقوله تعالى: ﴿ويحق الله الحق بكلماته﴾؟","answer":"الجمع في ﴿كلماته﴾ يشمل وعود الله وأحكامه وحججه التي ينصر بها الحق، فلا يختصر الإحقاق في وسيلة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص60، تحت «إيثار الجمع في ﴿كلماته﴾»","url":""}]},{"id":"s10-261","number":822,"surah":10,"verses":[83],"references":[{"surah":10,"verses":[83]}],"verseLabel":"يونس: 83","question":"لماذا عبّر القرآن عن المؤمنين بأنهم ﴿ذرية﴾، ولم يقل: «رجال» أو «قوم»؟","answer":"لفظ ﴿ذرية﴾ يلفت إلى حداثة سنهم أو ضعف جماعتهم، ويجعل إيمانهم أشد دلالة على أثر الحجة في النفوس. كما يوحي بأنهم كانوا من أبناء القوم وامتدادهم، ومع ذلك خالفوا بيئة الخوف والاتباع.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص70، تحت «دلالة لفظ ﴿ذرية﴾»","url":""}]},{"id":"s10-262","number":823,"surah":10,"verses":[84],"references":[{"surah":10,"verses":[84]}],"verseLabel":"يونس: 84","question":"لماذا قال المؤمنون: ﴿ربنا لا تجعلنا فتنة للقوم الظالمين﴾؟","answer":"طلبوا ألا يكون ضعفهم أو هزيمتهم سببًا لاغترار الظالمين بباطلهم أو صدّهم عن الإيمان، فدعاؤهم يجمع حماية الدين وحماية أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص81، تحت «معنى الفتنة في دعاء المؤمنين»","url":""}]},{"id":"s10-263","number":824,"surah":10,"verses":[85],"references":[{"surah":10,"verses":[85]}],"verseLabel":"يونس: 85","question":"لماذا قُدّم الجار والمجرور في ﴿على الله توكلنا﴾؟","answer":"التقديم يفيد قصر التوكل عليه سبحانه، كأنهم يقولون: عليه وحده اعتمدنا، لا على قوة ولا ملجأ آخر. وهذا أنسب لمقام التهديد؛ فحين تضيق الأسباب الظاهرة يعلن المؤمنون وجهة اعتمادهم قبل طلب النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص88، تحت «معنى الفاء في ﴿فقالوا﴾»","url":""}]},{"id":"s10-264","number":825,"surah":10,"verses":[86],"references":[{"surah":10,"verses":[86]}],"verseLabel":"يونس: 86","question":"لماذا وصف المؤمنون أنفسهم بأنهم ﴿قومًا مؤمنين﴾ في دعائهم بالنجاة؟","answer":"ليس الوصف لمجرد الإخبار، بل هو إظهار لحالهم التي يستحقون بها الرحمة، مع اعترافهم بأن الإيمان هو الرابط الذي جمعهم. وجاء منصوبًا في الدعاء كأنهم يقولون: لا تجعلنا أداة فتنة للكافرين ونحن أهل إيمان بك.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص90، تحت «الاقتصار على وصف المؤمنين»","url":""}]},{"id":"s10-265","number":826,"surah":10,"verses":[87],"references":[{"surah":10,"verses":[87]}],"verseLabel":"يونس: 87","question":"لماذا نُكّرت ﴿بيوتًا﴾ في قوله: ﴿واجعلوا بيوتكم قبلة﴾؟","answer":"التنكير يترك اللفظ واسعًا ليشمل أي بيوت يمكن أن تحفظ الجماعة وتجمعها على العبادة، فلا يتوقف الأمر على بناء مخصوص. وفيه تيسير على المؤمنين تحت القهر، إذ تتحول البيوت المتاحة إلى مواضع عبادة وثبات.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص105، تحت «علة تنوين البيوت وتنكيرها»","url":""}]},{"id":"s10-266","number":827,"surah":10,"verses":[88],"references":[{"surah":10,"verses":[88]}],"verseLabel":"يونس: 88","question":"لماذا وصف موسى أموال فرعون بقوله: ﴿أموالهم﴾، ثم قال: ﴿واشدد على قلوبهم﴾؟","answer":"بدأ بما يغترون به في الخارج، ثم انتقل إلى موضع الإصرار في الداخل؛ فالدعاء يتناول وسيلة الطغيان ومصدر العناد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص113، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-267","number":828,"surah":10,"verses":[90],"references":[{"surah":10,"verses":[90]}],"verseLabel":"يونس: 90","question":"لماذا كرر فرعون لفظ الإيمان في قوله: ﴿آمنت أنه لا إله إلا الذي آمنت به بنو إسرائيل﴾؟","answer":"التكرار يكشف أنه لم يأت بإيمان مستقل نابع من يقين، بل اضطر إلى تقليد من كان يحاربهم قبل لحظة الهلاك. فجاءت الإحالة إلى إيمان بني إسرائيل شاهدة على تأخره وعجزه عن إنشاء موقف صادق.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص169، تحت «نكتة الإيجاز عن المسند»","url":""}]},{"id":"s10-268","number":829,"surah":10,"verses":[92],"references":[{"surah":10,"verses":[92]}],"verseLabel":"يونس: 92","question":"لماذا قيل: ﴿ببدنك﴾ بدل «بجسدك»؟","answer":"لفظ البدن أنسب في تصوير الجسد الظاهر الذي يُرى ويُعتبر به، فالمقصود إبقاؤه علامة حسية لمن يأتي بعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص174، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s10-269","number":830,"surah":10,"verses":[93],"references":[{"surah":10,"verses":[93]}],"verseLabel":"يونس: 93","question":"لماذا جمع السياق بين قوله: ﴿مبوأ صدق﴾ وقوله: ﴿ورزقناهم من الطيبات﴾؟","answer":"لأن تمام النعمة يجمع بين صلاح المكان وصلاح العيش؛ فليس التمكين أرضًا آمنة فقط، ولا الرزق متاعًا منفصلًا عن الاستقرار. وبهذا يذكّر السياق بأن الله أكرمهم بأسباب الحياة الكريمة ظاهرًا وباطنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص179، تحت «التعبير عن فعل الرزق»","url":""}]},{"id":"s10-270","number":831,"surah":10,"verses":[94],"references":[{"surah":10,"verses":[94]}],"verseLabel":"يونس: 94","question":"لماذا أحال القرآن المترددين إلى سؤال أهل الكتاب؟","answer":"لأن ذكر صفات النبي والحق المنزل موجود في كتبهم، فجاءت الإحالة إلزامًا لمن يعرف البشارة ثم يجحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص194، تحت «فائدة استحضار الشك في ﴿إن كنت في شك﴾»","url":""}]},{"id":"s10-272","number":833,"surah":10,"verses":[97],"references":[{"surah":10,"verses":[97]}],"verseLabel":"يونس: 97","question":"لماذا ختمت الآية بقوله: ﴿من الخاسرين﴾؟","answer":"لأن التكذيب لا يضيع دليلًا فحسب، بل يوقع صاحبه في خسارة نفسه ومآله؛ فجاء وصف الخسران أوسع من مجرد عدم الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص214، تحت «إيثار لفظ ﴿الخاسرين﴾»","url":""}]},{"id":"s10-273","number":834,"surah":10,"verses":[98],"references":[{"surah":10,"verses":[98]}],"verseLabel":"يونس: 98","question":"ما سر التعبير بقوله تعالى: ﴿ومتعناهم إلى حين﴾، ولم يجعل كشف العذاب نهاية القصة؟","answer":"لأن رفع العذاب لا يعني دوام النعمة ولا سقوط الحساب؛ فقد أُمهلوا بعد كشف الضر إلى أجل معلوم. فجاء ﴿إلى حين﴾ ليحفظ في القصة معنى التهديد، ويبين أن المتاع المؤقت ليس دليل رضا دائم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص235، تحت «دلالة التمتع في السياق»","url":""}]},{"id":"s10-274","number":835,"surah":10,"verses":[99],"references":[{"surah":10,"verses":[99]}],"verseLabel":"يونس: 99","question":"ما سر التعبير بقوله تعالى: ﴿كلهم جميعًا﴾، مع أن لفظ ﴿كلهم﴾ يفيد العموم؟","answer":"جاء ﴿جميعًا﴾ توكيدًا زائدًا يقطع احتمال التخصيص أو اختلاف المصير؛ فالمقصود أن اجتماعهم على الكفر لم يكن إكراهًا من الله ولا نقصًا في البيان. ثم يقرر السياق أن الإيمان لا يُنتزع قسرًا، بل يقوم على اختيار العبد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص248، تحت «التقديم في الآية»","url":""}]},{"id":"s10-275","number":836,"surah":10,"verses":[100],"references":[{"surah":10,"verses":[100]}],"verseLabel":"يونس: 100","question":"لماذا نسب جعل الرجس إلى الله في قوله: ﴿ويجعل الرجس على الذين لا يعقلون﴾؟","answer":"لبيان أن الجزاء يجري بحكمة الله؛ فمن عطّل عقله عن آياته استحق أن يُترك في أثر اختياره من الضلال والرجس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص258، تحت «نكتة التعبير في ﴿يجعل الرجس﴾»","url":""}]},{"id":"s10-276","number":837,"surah":10,"verses":[101],"references":[{"surah":10,"verses":[101]}],"verseLabel":"يونس: 101","question":"ما سر التعبير بقوله تعالى: ﴿وما تغني الآيات والنذر عن قوم لا يؤمنون﴾ بعد الأمر بالنظر في السماوات والأرض؟","answer":"ليبين أن قيمة الدليل لا تتوقف على ظهوره، بل على وجود قلب يتلقاه. فالأمر بالنظر يفتح أبواب التفكر، ثم يحذر من أن الآيات والنذر لا تنفع من اختار الإعراض وأغلق طريق الإيمان على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص266، تحت «بلاغة العطف في الآية»","url":""}]},{"id":"s10-277","number":838,"surah":10,"verses":[102],"references":[{"surah":10,"verses":[102]}],"verseLabel":"يونس: 102","question":"لماذا قيل: ﴿مثل أيام الذين خلوا من قبلهم﴾؟","answer":"جعل أيام المكذبين السابقين نموذجًا متكررًا، ليعلم اللاحقون أن سنن الجزاء لا تتبدل بتبدل الأمم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص285، تحت «دلالة العطف في السياق»","url":""}]},{"id":"s10-279","number":840,"surah":10,"verses":[105],"references":[{"surah":10,"verses":[105]}],"verseLabel":"يونس: 105","question":"لماذا وُصف الدين في قوله: ﴿وأمرت أن أكون من المؤمنين حنيفًا﴾ بلفظ ﴿حنيفًا﴾؟","answer":"الحنيف هو المائل عن الشرك إلى التوحيد، فالوصف لا يكتفي بإثبات الإيمان، بل يبين اتجاهه ومفارقته للباطل. وجاء بعد الأمر بأن يكون من المؤمنين ليجمع بين أصل الاعتقاد وصورته العملية: إقبال على الله وإعراض عما سواه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص313، تحت «بلاغة الكناية في ﴿فأقم وجهك للدين حنيفًا﴾»","url":""}]},{"id":"s10-280","number":841,"surah":10,"verses":[107],"references":[{"surah":10,"verses":[107]}],"verseLabel":"يونس: 107","question":"لماذا كرر السياق لفظ ﴿الضر﴾ في قوله: ﴿وإن يمسسك الله بضر فلا كاشف له إلا هو﴾؟","answer":"التكرار يثبت المعنى في مقام الخوف، ويصور أن الضر مهما تنوعت صوره لا يملك رفعه إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص328، تحت «معنى الفاء في ﴿فلا﴾»","url":""}]},{"id":"s10-281","number":842,"surah":10,"verses":[108],"references":[{"surah":10,"verses":[108]}],"verseLabel":"يونس: 108","question":"ما سر التعبير بقوله تعالى: ﴿فمن اهتدى فإنما يهتدي لنفسه ومن ضل فإنما يضل عليها﴾؟","answer":"قابل بين الهدى والضلال، وجعل نفع الأول وضرر الثاني راجعين إلى صاحبهما، لئلا يتوهم أحد أن اختيار غيره يغنيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص338، تحت «نكتة الفصل في الآية»","url":""}]},{"id":"s10-283","number":844,"surah":10,"verses":[91],"references":[{"surah":10,"verses":[91]}],"verseLabel":"يونس: 91","question":"لماذا ذكّر موسى فرعون بقوله: ﴿وقد عصيت قبل﴾، مع أن فرعون أعلن الإيمان في لحظة الغرق؟","answer":"ليُظهر أن هذا الإقرار لم يأت عن تصديق سابق، بل بعد أن عاين العذاب وانقطعت عنه أسباب الاختيار. فذكر العصيان السابق يردّ دعواه إلى تاريخ طويل من التكذيب والإفساد، ويبين أن الإيمان الاضطراري لا يمحو عناد السنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص169، تحت «نكتة الإيجاز عن المسند إسنادًا للإنجاء بالبدن»","url":""}]},{"id":"s10-284","number":845,"surah":10,"verses":[96],"references":[{"surah":10,"verses":[96]}],"verseLabel":"يونس: 96","question":"ما سر التعبير بقوله تعالى: ﴿إن الذين حقت عليهم كلمة ربك لا يؤمنون﴾ بدل أن يقول: «لا يؤمنون بآيات الله»؟","answer":"علّق عدم الإيمان بكلمة الله السابقة فيهم، ليبين أن العناد المتراكم أفضى إلى استحقاق الحكم، لا أن الآيات ناقصة أو غير واضحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص209، تحت «وجه إضافة الآيات إلى الله»","url":""}]},{"id":"s10-286","number":847,"surah":10,"verses":[106],"references":[{"surah":10,"verses":[106]}],"verseLabel":"يونس: 106","question":"لماذا قيل: ﴿ما لا ينفعك ولا يضرك﴾، فجمع بين النفع والضر؟","answer":"لأن التعلق بالمعبود الباطل يقوم على طلب جلب النفع أو دفع الضر، فنفى عنه الأمرين ليبطل أصل العبادة من جهتي الرجاء والخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص318، تحت «معنى ﴿من دون الله﴾»","url":""}]},{"id":"s10-287","number":848,"surah":10,"verses":[2,108],"references":[{"surah":10,"verses":[2,108]}],"verseLabel":"يونس: 2، 108","question":"ما وجه التناسب بين مطلع السورة ﴿أكان للناس عجبًا أن أوحينا إلى رجل منهم أن أنذر الناس﴾ وخاتمتها ﴿قل يا أيها الناس قد جاءكم الحق من ربكم﴾؟","answer":"يذكر السامرائي سورة يونس في أمثلة تناسب الفاتحة والخاتمة، فقد بدأت بالوحي إلى الرسول لينذر الناس، وخُتمت بخطاب الناس بأن الحق قد جاءهم من ربهم، فالتقى المبدأ والمنتهى في أمر الرسالة ودعوة الناس.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص258.","url":""}]},{"id":"s10-288","number":849,"surah":10,"verses":[50],"references":[{"surah":10,"verses":[50]}],"verseLabel":"يونس: 50","question":"ما سر ترك كاف الخطاب في قوله: ﴿قل أرأيتم إن أتاكم عذابه بياتًا أو نهارًا﴾، وذكرها في الأنعام: ﴿أرأيتكم﴾؟","answer":"زيادة الكاف تأكيد للخطاب وتنبيه زائد في موقف أشد، وقد تقدّم في الأنعام ذكر الصمم والبكم وأخذ السمع والأبصار، وليس ذلك في يونس، بل تقدّمها ﴿أمّن يملك السمع والأبصار﴾ فحصل التنبيه فاكتفى بخطاب واحد. وينقل في ذلك عن «البرهان» وعن ابن الزبير.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص101–102.","url":""}]},{"id":"s10-289","number":850,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما سر تقديم الأرض على السماء في قوله: ﴿وما يعزب عن ربك من مثقال ذرة في الأرض ولا في السماء﴾، وعكسه في سبأ؟","answer":"بدأت الآية بشؤون أهل الأرض وأعمالهم: ﴿وما تكون في شأن وما تتلو منه من قرآن ولا تعملون من عمل﴾، فناسب تقديم الأرض. ويستشهد بما في «الكشاف» من أن حق السماء التقديم، لكن ذكر شهادته على شؤون أهل الأرض لاءمه تقديم الأرض.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص262–263.","url":""}]},{"id":"s10-290","number":851,"surah":10,"verses":[90],"references":[{"surah":10,"verses":[90]}],"verseLabel":"يونس: 90","question":"ما الفرق بين ﴿فأتبعهم فرعون وجنوده﴾ بالواو هنا، و﴿فأتبعهم فرعون بجنوده﴾ بالباء في طه؟","answer":"الواو تدل نصًّا على أن فرعون خرج بنفسه مع جنوده، أما الباء فتحتمل أنه أرسل جنوده ولم يذهب معهم. والسياق في يونس يؤكد علوّ فرعون وإسرافه وتصميمه على البطش، ولذلك ذُكر غرقه هو وإيمانه حين أدركه الغرق.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص142–145.","url":""}]},{"id":"s10-291","number":852,"surah":10,"verses":[90],"references":[{"surah":10,"verses":[90]}],"verseLabel":"يونس: 90","question":"ما دلالة التعبير بـ«العَدْو» في قوله: ﴿بغيًا وعَدْوًا﴾؟","answer":"العَدْو أكثر ما يُستعمل في المشي والحركة والأمور العلاجية، واتباع فرعون لبني إسرائيل مشي وحركة. أما «العداوة» فأمر قلبي، و«العدوان» الظلم والإخلال بالمعاملة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص17.","url":""}]},{"id":"s10-292","number":853,"surah":10,"verses":[101],"references":[{"surah":10,"verses":[101]}],"verseLabel":"يونس: 101","question":"ما دلالة رسم الياء في قوله: ﴿وما تغني الآيات والنذر﴾، وحذفها في القمر: ﴿فما تغنِ النذر﴾؟","answer":"يقرر أن رسم المصحف لا يُقاس عليه، لكنه يرى للاختلاف دلالة محتملة: فقد زاد في يونس «الآيات» على «النذر» فزادت دواعي الإغناء، فزاد في الرسم. ولما نقصت الدواعي في القمر نقص من الرسم.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص85–86.","url":""}]},{"id":"s10-293","number":854,"surah":10,"verses":[107],"references":[{"surah":10,"verses":[107]}],"verseLabel":"يونس: 107","question":"ما سر الختم بـ﴿فلا رادّ لفضله﴾ في قوله: ﴿وإن يردك بخير﴾، وبـ﴿فهو على كل شيء قدير﴾ في الأنعام؟","answer":"آية الأنعام في افتراض مسّ الخير: ﴿وإن يمسسك بخير﴾، وآية يونس في افتراض إرادة الخير. والإرادة من غير الله قد لا تتحقق لحائل يحول دونها، أما إرادته سبحانه فلا رادّ لها. ولما اتفق الافتراضان في مسّ الضر اتفق الجواب: ﴿فلا كاشف له إلا هو﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص56.","url":""}]},{"id":"s10-855","number":855,"surah":10,"verses":[1],"references":[{"surah":10,"verses":[1]}],"verseLabel":"يونس: 1","question":"ما سر افتتاح السورة بـ﴿الر﴾؟","answer":"ينقل السامرائي عن «ملاك التأويل» أن كل سورة افتُتحت بحروف مقطعة يكثر في كلمها الحرف المفتتح به. ففي سورة يونس تكررت الراء في نحو مئتين وعشرين كلمة، وهي أكثر مما في سورة النحل مع أنها أطول منها.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص9.","url":""}]},{"id":"s10-856","number":856,"surah":10,"verses":[10],"references":[{"surah":10,"verses":[10]}],"verseLabel":"يونس: 10","question":"ما دلالة ﴿اللهم﴾ بغير لفظ «الرب» في قوله: ﴿دعواهم فيها سبحانك اللهم﴾؟","answer":"الدعاء في القرآن كثيرًا ما يكون مع لفظ «الرب». أما هذه الآية فليست دعاءً بالمعنى المعروف، إذ ليس فيها طلب شيء ولا مسألة حاجة، بل هي تسبيح أهل الجنة وتنزيههم.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص71–72.","url":""}]},{"id":"s10-857","number":857,"surah":10,"verses":[22],"references":[{"surah":10,"verses":[22]}],"verseLabel":"يونس: 22","question":"ما سر إفراد الريح في موضع الخير في قوله: ﴿وجرين بهم بريح طيبة﴾؟","answer":"الغالب في القرآن أن «الرياح» للخير والرحمة و«الريح» للشر. ولم تأت الريح في الخير إلا في موطن واحد أعقبها فيه بالشر، وهو هذه الآية: ﴿جاءتها ريح عاصف وجاءهم الموج من كل مكان﴾، فكانت خاتمتها غير حميدة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص12–13.","url":""}]},{"id":"s10-858","number":858,"surah":10,"verses":[30],"references":[{"surah":10,"verses":[30]}],"verseLabel":"يونس: 30","question":"ما دلالة التعبير بالردّ في قوله: ﴿ورُدّوا إلى الله مولاهم الحق﴾؟","answer":"يستعمل القرآن «ردّ» في الغالب للأمور الثقيلة المستكرهة، و«رجع» لما هو أخف. وهذه الآية في المشركين وشركائهم حين تبلو كل نفس ما أسلفت، فاستعمل الردّ للكافرين.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص47–49.","url":""}]},{"id":"s10-859","number":859,"surah":10,"verses":[36],"references":[{"surah":10,"verses":[36]}],"verseLabel":"يونس: 36","question":"ما سر الختم بالعلم في قوله: ﴿إن الظن لا يغني من الحق شيئًا إن الله عليم بما يفعلون﴾؟","answer":"لما نفى العلم عنهم بأنهم لا يتبعون إلا الظن، أثبت العلم لنفسه سبحانه، فناسب ذكر العلم في الخاتمة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص136.","url":""}]},{"id":"s10-860","number":860,"surah":10,"verses":[42,43],"references":[{"surah":10,"verses":[42,43]}],"verseLabel":"يونس: 42–43","question":"ما سر الجمع في ﴿ومنهم من يستمعون إليك﴾، والإفراد في ﴿ومنهم من ينظر إليك﴾؟","answer":"المستمعون أكثر من الرائين على وجه العموم، فنحن نستمع إلى أناس كثيرين لا نراهم، فجُمع الفعل مع الاستماع وأُفرد مع النظر، وإن كان «مَن» يحتمل الأمرين. ويذكر معه رأي الكرماني في «البرهان».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص47.","url":""}]},{"id":"s10-861","number":861,"surah":10,"verses":[46],"references":[{"surah":10,"verses":[46]}],"verseLabel":"يونس: 46","question":"ما دلالة وصل «إمّا» في قوله: ﴿وإمّا نُرينّك بعض الذي نعدهم أو نتوفينّك فإلينا مرجعهم﴾، وفصلها في الرعد؟","answer":"يقرر السامرائي أن هذا من رسم المصحف الذي لا يُقاس عليه، ثم يذكر أنه قد يبدو له تعليل: السياق هنا في الآخرة والرجوع إلى الله، فوُصلت إشارة إلى اتصال الأحداث، أما في الرعد فالكلام على الدنيا والحساب في الآخرة ففُصلت.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص83–85.","url":""}]},{"id":"s10-862","number":862,"surah":10,"verses":[55,66],"references":[{"surah":10,"verses":[55,66]}],"verseLabel":"يونس: 55، 66","question":"ما سر التعبير بـ«ما» في ﴿ألا إن لله ما في السماوات والأرض﴾ [55]، وبـ«مَن» في ﴿ألا إن لله مَن في السماوات ومَن في الأرض﴾ [66]؟","answer":"الآية 55 سبقها ذكر الفداء بالمال: ﴿لافتدت به﴾، فجاء بـ«ما» التي لغير العاقل ومنه الأموال. والآية 66 ذُكر فيها الشركاء، فناسب «مَن» التي للعاقل.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص162.","url":""}]},{"id":"s10-863","number":863,"surah":10,"verses":[61],"references":[{"surah":10,"verses":[61]}],"verseLabel":"يونس: 61","question":"ما سر النفي بـ«ما» وذكر ﴿ربك﴾ وزيادة «مِن» في قوله: ﴿وما يعزب عن ربك مِن مثقال ذرة﴾، وفي سبأ: ﴿لا يعزب عنه مثقال ذرة﴾؟","answer":"نفى في يونس بـ«ما» لأن الكلام على الحال، وفي سبأ بـ«لا» لأن الكلام على الساعة وهي استقبال. وذكر الرب صريحًا في يونس لأنه لم يتقدّم ذكره، وأضمره في سبأ لتقدّم ﴿عالم الغيب﴾. وزاد «مِن» في يونس لأن السياق في إحاطة علم الله بكل شيء.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص262.","url":""}]},{"id":"s10-864","number":864,"surah":10,"verses":[72],"references":[{"surah":10,"verses":[72]}],"verseLabel":"يونس: 72","question":"ما سر قول نوح هنا: ﴿فما سألتكم من أجر﴾، وقوله في هود: ﴿لا أسألكم عليه مالًا﴾؟","answer":"وردت كلمة «المال» في هود لأنه وقع بعدها ذكر الخزائن: ﴿ولا أقول لكم عندي خزائن الله﴾، ولفظ المال بالخزائن أليق. أما في يونس وسائر المواضع فجاء «الأجر» إذ ليس في السياق ما يستدعي ذكر المال.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص179.","url":""}]},{"id":"s10-865","number":865,"surah":10,"verses":[74],"references":[{"surah":10,"verses":[74]}],"verseLabel":"يونس: 74","question":"ما سر زيادة ﴿به﴾ في قوله: ﴿فما كانوا ليؤمنوا بما كذبوا به من قبل﴾، وحذفها في الأعراف؟","answer":"الإطلاق هو سياق الأعراف: ﴿ولكن كذّبوا فأخذناهم﴾، والتخصيص هو سياق يونس: ﴿وأغرقنا الذين كذّبوا بآياتنا﴾، فذكر ما كذّبوا به. ولما زاد هنا ﴿به﴾ و﴿بآياتنا﴾ زاد بعدها ذكر هارون مع موسى. ويذكر معه رأي الكرماني في «البرهان».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص94–95.","url":""}]},{"id":"s10-866","number":866,"surah":10,"verses":[74],"references":[{"surah":10,"verses":[74]}],"verseLabel":"يونس: 74","question":"ما سر الختم بـ﴿كذلك نطبع على قلوب المعتدين﴾، وفي الأعراف: ﴿كذلك يطبع الله على قلوب الكافرين﴾؟","answer":"في الأعراف تقدّم ﴿ولو أن أهل القرى آمنوا﴾ فناسب ذكر الكافرين مقابل الإيمان. وفي يونس تقدّم خبر قوم نوح وتحدّيه لهم أن يجمعوا أمرهم ويقضوا إليه، وهذا موضع اعتداء، فناسب ذكر المعتدين.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص59–60.","url":""}]},{"id":"s10-867","number":867,"surah":10,"verses":[75],"references":[{"surah":10,"verses":[75]}],"verseLabel":"يونس: 75","question":"ما سر تأخير ﴿بآياتنا﴾ في قوله: ﴿ثم بعثنا من بعدهم موسى وهارون إلى فرعون وملئه بآياتنا﴾، وتقديمها في الأعراف؟","answer":"ذكر في الأعراف أن موسى أظهر الآيات أمام فرعون وملئه وأمام السحرة، فقدّمها. أما في يونس فلم يذكر أنه أظهر آية أمام فرعون وملئه، بل قال: ﴿فلما جاءهم الحق من عندنا﴾، فأخّرها.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص61.","url":""}]},{"id":"s10-868","number":868,"surah":10,"verses":[78],"references":[{"surah":10,"verses":[78]}],"verseLabel":"يونس: 78","question":"ما دلالة التعبير بـ«الكبرياء» في قول قوم فرعون: ﴿وتكون لكما الكبرياء في الأرض﴾؟","answer":"الكبرياء معناها العظمة والملك، وهي تدل على السعة والشمول فهي أوسع من الكِبر والكُبر، ولذلك اتهموهما بطلب الملك العام في الأرض. وينقل عن الراغب أن الكبرياء لا يستحقها غير الله.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص22.","url":""}]},{"id":"s10-869","number":869,"surah":10,"verses":[93],"references":[{"surah":10,"verses":[93]}],"verseLabel":"يونس: 93","question":"ما سر التعبير بالقضاء في قوله: ﴿إن ربك يقضي بينهم يوم القيامة﴾، وبالحكم في النحل: ﴿وإن ربك ليحكم بينهم﴾؟","answer":"ذكر في يونس أن اختلافهم كان بعد مجيء العلم: ﴿فما اختلفوا حتى جاءهم العلم﴾، وهو أشد مما لم يُذكر فيه ذلك، فعبّر بالقضاء، وهو أشد من الحكم، ونظيره آية الجاثية. وأشدّ منهما الفصل كما في الحج.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص10–13.","url":""}]},{"id":"s10-870","number":870,"surah":10,"verses":[106],"references":[{"surah":10,"verses":[106]}],"verseLabel":"يونس: 106","question":"ما سر ترك اللام في قوله: ﴿فإنك إذًا من الظالمين﴾، وذكرها في البقرة: ﴿إنك إذًا لمن الظالمين﴾؟","answer":"آية البقرة في التحذير من اتباع أهواء أهل الكتاب ﴿من بعد ما جاءك من العلم﴾، والمعصية بعد العلم أشد، فزاد التوكيد باللام وباللام الموطئة للقسم في ﴿لئن﴾. وليس في آية يونس ذكر مجيء العلم، فكان التوكيد فيها أقل.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص84–85.","url":""}]},{"id":"s11-1","number":1,"surah":11,"verses":[1],"references":[{"surah":11,"verses":[1]}],"verseLabel":"هود: 1","question":"ما دلالة الجمع بين إحكام آيات الكتاب وتفصيلها في قوله تعالى: ﴿أحكمت آياته ثم فصلت﴾؟","answer":"لأن الإحكام يدل على كمال نظمه ومنعه من الخلل، والتفصيل يدل على بيان معانيه وأحكامه وتنوع مقاصده؛ فجمع له كمال البناء وكمال البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص381، تحت «جمالية الاستعارة في «أحكمت آياته ثم فصلت»»","url":""}]},{"id":"s11-2","number":2,"surah":11,"verses":[1],"references":[{"surah":11,"verses":[1]}],"verseLabel":"هود: 1","question":"ما سرّ ختم وصف الكتاب بقوله تعالى: ﴿من لدن حكيم خبير﴾؟","answer":"لأن إحكام الآيات يناسب اسم ﴿الحكيم﴾، وتفصيلها على وفق مصالح الخلق يناسب ﴿الخبير﴾؛ فالخاتمة دليل على ما سبقها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص381–382، تحت «علة ختم الآية بهذين الوصفين الجليلين»","url":""}]},{"id":"s11-3","number":3,"surah":11,"verses":[2],"references":[{"surah":11,"verses":[2]}],"verseLabel":"هود: 2","question":"ما سرّ تقديم ﴿ألا تعبدوا إلا الله﴾ على ﴿إنني لكم منه نذير وبشير﴾؟","answer":"بدأ بأصل التكاليف، وهو إفراد الله بالعبادة، ثم ذكر الرسول بصفتي الإنذار والبشارة إيماءً إلى اتباعه وطاعته، ثم جاء الأمر بالاستغفار والتوبة؛ فانتظم الخطاب في التوحيد ثم الإيمان بالرسول ثم العمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص388، تحت «بلاغة تعاقب الجمل الثلاث على هذا الترتيب»","url":""}]},{"id":"s11-5","number":5,"surah":11,"verses":[3],"references":[{"surah":11,"verses":[3]}],"verseLabel":"هود: 3","question":"ما سرّ تقديم الاستغفار على التوبة في قوله تعالى: ﴿استغفروا ربكم ثم توبوا إليه﴾؟","answer":"يتعلق الاستغفار بطلب المغفرة لما مضى، وتتعلق التوبة بإصلاح الحال والعزم على عدم العودة إلى الذنب؛ فناسب سبق الماضي أن يتقدم الاستغفار في الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص395، تحت «نكتة تقديم الأمر بالاستغفار على الأمر بالتوبة»","url":""}]},{"id":"s11-6","number":6,"surah":11,"verses":[3],"references":[{"surah":11,"verses":[3]}],"verseLabel":"هود: 3","question":"ما فائدة وصف المتاع بـ«حسنًا»، وما دلالة «إلى»؟","answer":"قيد المتاع بالحسن لأنه ثمرة الإيمان والطاعة، وقيده بالأجل حتى لا يُفهم الوعد خلودًا في الدنيا؛ فهي نعمة موقوتة تتصل بعدها بالجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص397–398، تحت «فائدة وصف المتاع بـ«حسنًا»؛ دلالة «إلى»»","url":""}]},{"id":"s11-7","number":7,"surah":11,"verses":[3],"references":[{"surah":11,"verses":[3]}],"verseLabel":"هود: 3","question":"ما مدلول الفضلين في «ويؤت كل ذي فضل فضله»؟","answer":"الفضل الأول عمل الإنسان الصالح، والفضل الثاني ما يعطيه الله من الجزاء؛ فالمعنى أن كل صاحب عمل صالح ينال جزاء عمله من فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص400، تحت «مدلول الفضلين في «ويؤت كل ذي فضل فضله»»","url":""}]},{"id":"s11-8","number":8,"surah":11,"verses":[4],"references":[{"surah":11,"verses":[4]}],"verseLabel":"هود: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿إلى الله مرجعكم﴾ بتقديم الجار والمجرور؟","answer":"لقصر المرجع عليه وحده؛ فلا مهرب إلى قوة أخرى، ثم جاء ﴿وهو على كل شيء قدير﴾ لإثبات قدرته على البعث والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص410، 413، تحت «فائدة تقديم شبه الجملة «إلى الله»؛ نكتة تذييل الآية بصفة القدرة»","url":""}]},{"id":"s11-9","number":9,"surah":11,"verses":[5],"references":[{"surah":11,"verses":[5]}],"verseLabel":"هود: 5","question":"ما دلالة تصوير الإعراض والإخفاء بقوله تعالى: ﴿يثنون صدورهم﴾؟","answer":"صوّر شدة إعراضهم ومحاولتهم كتمان ما فيها بمن يطوي صدره وينحنيه؛ وهي هيئة جسدية تكشف انغلاقًا نفسيًا لا يخفى على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص418، تحت «بلاغة الحقيقة والاستعارة في ثني الصدور»","url":""}]},{"id":"s11-10","number":10,"surah":11,"verses":[5],"references":[{"surah":11,"verses":[5]}],"verseLabel":"هود: 5","question":"ما سرّ التعبير عن التستر بقوله تعالى: ﴿يستغشون ثيابهم﴾؟","answer":"يدل اللفظ على إحكام الغطاء والمبالغة في التستر؛ فليس غرضهم مجرد التغطية، بل التستر الكامل الذي يحجبهم عن رؤية الرسول وسماعه، ومع ذلك لا يخفى على الله ما يسرون وما يعلنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص421، تحت «سر التعبير بـ«يستغشون»»","url":""}]},{"id":"s11-11","number":11,"surah":11,"verses":[5],"references":[{"surah":11,"verses":[5]}],"verseLabel":"هود: 5","question":"ما دلالة التعبير عن الأسرار بقوله تعالى: ﴿بذات الصدور﴾؟","answer":"صوّر الأسرار والخواطر كأنها صاحبة للصدور، تلابسها وتساكنها ملازمة الصاحب لصاحبه؛ فالمقصود إحاطة علم الله بما يستكن في القلوب، لا مجرد العلم بظاهر الصدور.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص425، تحت «لطافة الإيجاز بالحذف في «بذات الصدور»؛ بلاغة المجاز في «بذات الصدور»»","url":""}]},{"id":"s11-12","number":12,"surah":11,"verses":[6],"references":[{"surah":11,"verses":[6]}],"verseLabel":"هود: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وما من دابة في الأرض إلا على الله رزقها﴾ بصيغة الاستغراق؟","answer":"أكد النفي بـ«من» ليستغرق كل دابة، صغيرة أو كبيرة؛ فجعل عموم رزقها دليلًا على إحاطة علم الله بجميع أحوالها، ومنها حاجتها وما يصلحها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص430، تحت «بلاغة التعبير بأسلوب النفي الدال على الاستغراق والعموم»","url":""}]},{"id":"s11-13","number":13,"surah":11,"verses":[6],"references":[{"surah":11,"verses":[6]}],"verseLabel":"هود: 6","question":"ما دلالة الجمع بين ﴿مستقرها﴾ و﴿مستودعها﴾ في بيان علم الله بالدابة؟","answer":"يشمل التعبير مواضع استقرار الدابة وإيداعها، ويكني عن إحاطة علم الله بها في كل حال، في سكونها وحركتها؛ فلا يخفى عليه موضعها ولا تحولها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص435–436، تحت «دلالة التعبير بصيغة «مفعل» في لفظي «مستقرها» و«مستودعها»؛ الغرض من التعبير بالكناية»","url":""}]},{"id":"s11-14","number":14,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿وكان عرشه على الماء﴾ في سياق خلق السماوات والأرض؟","answer":"تدل «كان» على سبق وجود العرش والماء لخلق السماوات والأرض. وذكر العرش على الماء يبين عظم قدرة الله على إمساك مخلوقاته؛ فكلها محتاجة إلى قدرته وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص442، تحت «دلالة العطف بالواو في «وكان عرشه على الماء»»","url":""}]},{"id":"s11-15","number":15,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"ما سرّ التعبير بـ﴿أحسن عملًا﴾ في غاية الابتلاء، دون «أكثر عملًا»؟","answer":"للدلالة على أن العبرة بحسن العمل لا بكثرته؛ فاللفظ يحث على إحسان العمل والترقي في مراتبه، ولا يجعل العدد وحده معيارًا للتفاضل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص444، تحت «نكتة التعبير بلفظ «أحسن»»","url":""}]},{"id":"s11-16","number":16,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"ما الغرض من التعبير بالكناية في قول الكافرين عن خبر البعث: ﴿إن هذا إلا سحر مبين﴾؟","answer":"كنوا بوصف خبر البعث بالسحر عن تكذيبهم الرسول وإنكارهم البعث؛ لأن مجرد الإخبار عن أمر مستقبل لا يكون سحرًا في حقيقته، وإنما أرادوا تهويل رفضهم للخبر والطعن في قائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص451، تحت «الغرض من التعبير بالكناية»","url":""}]},{"id":"s11-203","number":203,"surah":11,"verses":[7],"references":[{"surah":11,"verses":[7]}],"verseLabel":"هود: 7","question":"لماذا صيغ رد الكافرين على خبر البعث بطريق القصر: ﴿إن هذا إلا سحر مبين﴾؟","answer":"جاء النفي والاستثناء ليحصروا الخبر في السحر حصرًا مؤكدًا، مبالغةً في إنكاره وقطعًا منهم لكل احتمال يدل على صدقه، ففضحت الصياغة شدة عنادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص452، تحت «سر اصطفاء النفي والاستثناء طريقًا للقصر»","url":""}]},{"id":"s11-17","number":17,"surah":11,"verses":[8],"references":[{"surah":11,"verses":[8]}],"verseLabel":"هود: 8","question":"ما سرّ التعبير بـ«أمة معدودة»، وما النكتة البلاغية في الوصف في «معدودة»؟","answer":"تشير «أمة» إلى أمد مرتبط بانقضاء جيل واجتماع الوقت المحدد للعذاب بعد الإنذار والإعذار. ووصفها بـ«معدودة» يبين أنها محصورة الأيام، قصيرة معلومة عند الله، وإن طالت في نظر الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص458، تحت «سر التعبير بـ«أمة معدودة»؛ نكتة الوصف في «معدودة»»","url":""}]},{"id":"s11-18","number":18,"surah":11,"verses":[8],"references":[{"surah":11,"verses":[8]}],"verseLabel":"هود: 8","question":"ما دلالة التنبيه ونفي الصرف في قوله تعالى: ﴿ألا يوم يأتيهم ليس مصروفًا عنهم﴾؟","answer":"افتتح بـ﴿ألا﴾ للتنبيه، ونفى صرف العذاب لا مجرد تأخره؛ فما اتخذوه مادة للسخرية سيحيط بهم ولا يستطيعون دفعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص461–462، تحت «فائدة التعبير بأداة التنبيه «ألا»؛ نكتة التعبير بلفظ الخبر «مصروفًا»»","url":""}]},{"id":"s11-19","number":19,"surah":11,"verses":[9],"references":[{"surah":11,"verses":[9]}],"verseLabel":"هود: 9","question":"ما سرّ التعبير في قوله تعالى في الرحمة: ﴿أذقنا الإنسان منا رحمة﴾؟","answer":"الإذاقة تدل على أقل قدر من النعمة؛ فإذا كان الإنسان ييأس بزوال لمحة منها ظهر اضطرابه وقلة صبره. وإضافة الرحمة إلى الله تذكر بمصدرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص470–471، تحت «نكتة التعبير بـ«أذقنا»؛ سر القيد بشبه الجملة في «منا»»","url":""}]},{"id":"s11-20","number":20,"surah":11,"verses":[9],"references":[{"surah":11,"verses":[9]}],"verseLabel":"هود: 9","question":"ما دلالة الجمع بين الوصفين ﴿ليئوس كفور﴾؟","answer":"جمع بين شدة اليأس من عودة ما نزع منه، وكفران ما سبق له من النعمة وما بقي منها؛ فالصيغتان تبرزان حرمانه من الصبر والشكر، وفي الجمع بينهما توبيخ شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص474–475، تحت «براعة التعبير بالوصفين «ليئوس كفور»»","url":""}]},{"id":"s11-21","number":21,"surah":11,"verses":[10],"references":[{"surah":11,"verses":[10]}],"verseLabel":"هود: 10","question":"ما سرّ التعبير عند عودة النعمة بقوله: ﴿ليقولن ذهب السيئات عني﴾؟","answer":"لا يرى النعمة فضلًا يستوجب الشكر، بل مجرد انتهاء لما كان يؤلمه؛ ثم يبني على زواله أمنًا مغرورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص485–486، تحت «الغرض من الكناية في «ذهبت السيئات عني»؛ سر مجيء تأكيدين في «إنه لفرح فخور»»","url":""}]},{"id":"s11-22","number":22,"surah":11,"verses":[10],"references":[{"surah":11,"verses":[10]}],"verseLabel":"هود: 10","question":"ما دلالة وصف الإنسان بعد زوال الضر بقوله تعالى: ﴿إنه لفرح فخور﴾؟","answer":"يعلل الوصفان قوله المتباهي ﴿ذهب السيئات عني﴾؛ فقد حمله شدة الفرح بالنعمة والفخر بها على الإعجاب بما ناله، بدل أن يشكر الله عليها، فورد الوصفان في مقام الذم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص486، تحت «شبه كمال الاتصال في الجملة المؤكدة بالأداة «إن»»","url":""}]},{"id":"s11-23","number":23,"surah":11,"verses":[11],"references":[{"surah":11,"verses":[11]}],"verseLabel":"هود: 11","question":"ما سرّ استثناء ﴿الذين صبروا وعملوا الصالحات﴾ من تقلّب الإنسان بين اليأس والفخر؟","answer":"لأن الصبر يضبطه عند الضر، والعمل الصالح يضبطه عند النعمة؛ فبهما ينجو من اليأس والكفر والبطر والفخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص487–488، تحت «الغرض من التعبير بالموصول «الذين» وصلته «صبروا»؛ دلالة العطف في سياق جملتي الصبر والعمل الصالح»","url":""}]},{"id":"s11-24","number":24,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما أثر الاستعارة في قوله تعالى: ﴿وضائق به صدرك﴾؟","answer":"صورت الاستعارة ما يجده النبي من شدة وقع اقتراحات المعاندين كأن الصدر يضيق عن احتمالها، فقرّبت أثر أذاهم في النفس، وجاء السياق تسليةً له وتثبيتًا على البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص494، تحت «الغرض من التعبير بالاستعارة»","url":""}]},{"id":"s11-204","number":204,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما دلالة التعبير باسمي الفاعل ﴿تارك﴾ و﴿ضائق﴾ في قوله تعالى: ﴿فلعلك تارك بعض ما يوحى إليك وضائق به صدرك﴾؟","answer":"استحضرت صيغة اسم الفاعل الحالة التي كاد ضغط المعاندين يوقعها، من غير أن تثبت وقوع ترك الوحي؛ فصورت قرب الضيق وقوته، وجاءت تسليةً وتحذيرًا من أن تصرفه مطالبهم عن البلاغ الكامل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص495، تحت «دلالة التعبير باسم الفاعل «تارك» و«ضائق»»","url":""}]},{"id":"s11-25","number":25,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما دلالة اقتران طلب الكنز بطلب الملك في قولهم: ﴿لولا أنزل عليه كنز أو جاء معه ملك﴾؟","answer":"يكشف الطلبان موازينهم المضطربة؛ فقد عظموا المال وربطوا به السيادة، واستبعدوا اجتماع البشرية والرسالة، فطلبوا ملكًا يؤيد الرسول. وغفلوا عن قدر القرآن وعن دلالة الرسالة التي جاء بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص500–501، تحت «دلالة التعبير بـ«عليه كنز»؛ دلالة العطف في قوله «أو جاء معه ملك»»","url":""}]},{"id":"s11-26","number":26,"surah":11,"verses":[12],"references":[{"surah":11,"verses":[12]}],"verseLabel":"هود: 12","question":"ما سرّ ختم الآية بقوله تعالى: ﴿والله على كل شيء وكيل﴾؟","answer":"فيها تسلية للرسول بأن الله يتولى شؤون الخلق، وتعريض بأن الرسول ليس موكلًا بإجبارهم على الإيمان؛ فعليه الإنذار والبلاغ، ولا ينبغي أن يحمله إعراضهم على ترك الدعوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص503، تحت «بلاغة الجملة التذييلية»","url":""}]},{"id":"s11-27","number":27,"surah":11,"verses":[13],"references":[{"surah":11,"verses":[13]}],"verseLabel":"هود: 13","question":"ما سرّ التحدي بعشر سور في هود، وبسورة واحدة في يونس؟","answer":"في هود قوبلت دعوى الافتراء بقوله ﴿مفتريات﴾، فوسع عليهم في مضمون الكلام المطلوب، وناسب هذه التوسعة طلب عشر سور. أما في يونس فلم يذكر هذا القيد، بل طلب المماثلة مطلقًا، وهي أشق، فناسبها الاكتفاء بسورة واحدة؛ والغاية إظهار عجزهم في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص518، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s11-28","number":28,"surah":11,"verses":[13],"references":[{"surah":11,"verses":[13]}],"verseLabel":"هود: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿مفتريات﴾ مع أن الافتراء باطل؟","answer":"جاراهم في فرضهم: إن كان القرآن مفترى كما تزعمون فاختلقوا أنتم عشر سور تشبهه؛ فحتى مع إسقاط قيد الصدق عجزوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص511–512، تحت «نكتة مجيء «مفتريات»؛ براعة التعبير بوصف «مفتريات»»","url":""}]},{"id":"s11-29","number":29,"surah":11,"verses":[14],"references":[{"surah":11,"verses":[14]}],"verseLabel":"هود: 14","question":"ما دلالة توجيه الخطاب في قوله تعالى: ﴿فإن لم يستجيبوا لكم﴾؟","answer":"يحتمل أن يكون الخطاب للمشركين: فإن لم يجبكم من تستعينون بهم إلى المعارضة، فاعلموا أن القرآن من عند الله. ويحتمل أن يكون للرسول والمؤمنين: فإن لم يستجب الكفار لتحديكم، ظهر عجزهم. وعلى الوجه الثاني تُدخل صيغة الجمع المؤمنين مع الرسول في التحدي ونصرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص522–523، تحت «دلالة الخطاب في «فإن لم يستجيبوا»»","url":""}]},{"id":"s11-30","number":30,"surah":11,"verses":[14],"references":[{"surah":11,"verses":[14]}],"verseLabel":"هود: 14","question":"ما سرّ ختم التحدي بقوله تعالى: ﴿فهل أنتم مسلمون﴾؟","answer":"لأن العجز ليس نهاية مناظرة لغوية فقط، بل حجة تستدعي قرارًا: هل تنقادون بعد أن ثبت أن القرآن من عند الله؟","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص529، تحت «بلاغة الاستفهام في «فهل»»","url":""}]},{"id":"s11-31","number":31,"surah":11,"verses":[15],"references":[{"surah":11,"verses":[15]}],"verseLabel":"هود: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿من كان يريد الحياة الدنيا وزينتها﴾ ولم يكتفِ بالدنيا؟","answer":"فرق بين أصل الحياة وما يلتصق بها من زخارف؛ ليشمل من جعل غايته البقاء واللذة والجاه جميعًا دون نظر إلى الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص534–535، تحت «مناسبة العطف في «وزينتها»؛ فائدة الإضافة في «وزينتها»»","url":""}]},{"id":"s11-32","number":32,"surah":11,"verses":[15],"references":[{"surah":11,"verses":[15]}],"verseLabel":"هود: 15","question":"ما وجه البلاغة في التضمين في «نوف»، وما دلالة «فيها»؟","answer":"قد ينال صاحب العمل الدنيوي ثمرته العاجلة كاملة، لكن وفاء الأجر في الدنيا لا يعني قبول العمل في الآخرة إذا خلا من قصدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص535، 537، تحت «بلاغة التضمين في «نوف»؛ دلالة «فيها»»","url":""}]},{"id":"s11-33","number":33,"surah":11,"verses":[16],"references":[{"surah":11,"verses":[16]}],"verseLabel":"هود: 16","question":"أين تتجلى براعة التعبير بـ«وحبط» و«وباطل»؟","answer":"الحبوط يدل على سقوط ثواب ما صنعوه من أعمال البر حين لم تقترن بالإيمان والنية الصحيحة، أما البطلان فيصف ما لا جهة صلاح له أصلًا؛ ففرّق التعبير بين عمل فقد ثمرته الأخروية وعمل لا طائل تحته.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص545، تحت «براعة التعبير بـ«وحبط» و«وباطل»»","url":""}]},{"id":"s11-34","number":34,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما دلالة التعبير عن المؤمن بأنه ﴿على بينة من ربه﴾؟","answer":"﴿على﴾ تشعر بالتمكن والثبات، والبينة نور واضح من الله؛ فالمؤمن قائم على حجة لا على تقليد أو هوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص550–551، تحت «فائدة حرف الاستعلاء «على»؛ نكتة التعبير «بينة» ودلالته؛ دلالة التعبير «من ربه»»","url":""}]},{"id":"s11-35","number":35,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما دلالة تتابع البينة والشاهد وكتاب موسى في قوله تعالى: ﴿أفمن كان على بينة من ربه ويتلوه شاهد منه ومن قبله كتاب موسى﴾؟","answer":"يبين السياق تعاضد أدلة الإيمان؛ فالبينة أساس، ويتبعها شاهد مؤيد، ويسبق ذلك كتاب موسى شاهدًا على صدق القرآن ونبوة محمد ﷺ. وذكر كتاب موسى يقيم الحجة بكتاب اتفق أهل الكتاب على أنه من عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص551–552، تحت «دلالة الضمير في «ويتلوه»؛ دلالة الواو في «ومن قبله»»","url":""}]},{"id":"s11-36","number":36,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما سرّ وصف كتاب موسى بأنه ﴿إمامًا ورحمة﴾؟","answer":"لأنها كانت كتابًا يُقتدى به في الهداية، ورحمة لمن اتبعها، فشهادتها للوحي الجديد امتداد لسلسلة الكتب لا أمر منقطع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص552–553، تحت «بلاغة الاستعارة في «إمامًا»؛ بلاغة المجاز المرسل في «ورحمة»»","url":""}]},{"id":"s11-37","number":37,"surah":11,"verses":[17],"references":[{"surah":11,"verses":[17]}],"verseLabel":"هود: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿فلا تك في مرية منه﴾ مع يقين النبي؟","answer":"تثبيت له، وتعريض بمن يشك، وتعليم للأمة أن اجتماع البينة والشاهد والكتاب السابق يقطع أسباب الارتياب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص556–557، تحت «براعة التعبير بالخطاب في النهي عن المرية منه»","url":""}]},{"id":"s11-38","number":38,"surah":11,"verses":[18],"references":[{"surah":11,"verses":[18]}],"verseLabel":"هود: 18","question":"ما دلالة الاستفهام في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"الاستفهام إنكاري يفيد التقرير: لا أحد أظلم ممن افترى على الله، وفيه تهويل لجريمته وتعريض بمن نسبوا القرآن إلى غير منزله وزعموا أن الرسول افتراه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص564، تحت «بلاغة الاستفهام بين الإنكار والتقرير»","url":""}]},{"id":"s11-205","number":205,"surah":11,"verses":[18],"references":[{"surah":11,"verses":[18]}],"verseLabel":"هود: 18","question":"ما سرّ التعبير باسم التفضيل ﴿أظلم﴾ في قوله تعالى: ﴿ومن أظلم ممن افترى على الله كذبًا﴾؟","answer":"اختير اسم التفضيل لبيان أن الافتراء على الله قد بلغ الغاية في الظلم؛ إذ يجمع الكذب والتلبيس والصد عن الحق، فلا يتصور ظلم أشد منه في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص565، تحت «بلاغة التعبير باسم التفضيل «أظلم»»","url":""}]},{"id":"s11-39","number":39,"surah":11,"verses":[18],"references":[{"surah":11,"verses":[18]}],"verseLabel":"هود: 18","question":"ما سرّ التعبير بقوله تعالى: ﴿هؤلاء الذين كذبوا على ربهم﴾ أمام الأشهاد؟","answer":"يحدد اسم الإشارة أصحاب الجريمة أمام الحاضرين، ويشهرهم بما كذبوا به على ربهم. ثم جاءت صلة الموصول كأن كذبهم أمر معروف لا يحتاج إلى تفصيل؛ فاجتمع التعيين والتشهير والتوبيخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص568–569، تحت «مناسبة التعبير باسم الإشارة «هؤلاء»؛ فائدة مجيء الموصول مع صلته»","url":""}]},{"id":"s11-41","number":41,"surah":11,"verses":[20],"references":[{"surah":11,"verses":[20]}],"verseLabel":"هود: 20","question":"ما دلالة التعبير بقوله «معجزين»، وما دلالة الحال في قوله «في الأرض»، وما دلالة العطف في «وما كان»؟","answer":"ينفي قدرتهم على الإفلات من سلطان الله في أي مكان، ثم ينفي وجود أولياء ينصرونهم؛ فسد عليهم طريق الهرب وطريق الحماية.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص581، 583، تحت «دلالة التعبير بقوله «معجزين»؛ دلالة الحال في قوله «في الأرض»؛ دلالة العطف في «وما كان»»","url":""}]},{"id":"s11-42","number":42,"surah":11,"verses":[20],"references":[{"surah":11,"verses":[20]}],"verseLabel":"هود: 20","question":"ما سرّ التعليل بجملة «ما كانوا يستطيعون»، وما وجه البلاغة في الكناية في الآية؟","answer":"لأنهم عطلوا أدوات الهداية عمدًا؛ فصار الإعراض المتكرر سببًا لمضاعفة الجزاء، لا عجزًا خَلقيًا عن السمع والبصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص591–592، تحت «سر التعليل بجملة «ما كانوا يستطيعون»؛ بلاغة الكناية في الآية»","url":""}]},{"id":"s11-43","number":43,"surah":11,"verses":[21],"references":[{"surah":11,"verses":[21]}],"verseLabel":"هود: 21","question":"ما دلالة التعبير بالماضي في «ضل»، وما معنى حرف الجر «عنهم» ودلالته، وما سرّ إسناد الضلال إلى الأصنام؟","answer":"يصور غياب نفع المعبودات الباطلة حين يطلبونها، كأنها ضلت طريقها إليهم. وفي إسناد الضلال إلى الأصنام تهكم بهم، وفي ﴿عنهم﴾ تصوير لبعدها عنهم؛ فلا تنفعهم دعاوى الألوهية والشفاعة التي افتروها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص600–602، تحت «دلالة التعبير بالماضي في «ضل»؛ معنى حرف الجر «عنهم» ودلالته؛ سر إسناد الضلال إلى الأصنام»","url":""}]},{"id":"s11-44","number":44,"surah":11,"verses":[22],"references":[{"surah":11,"verses":[22]}],"verseLabel":"هود: 22","question":"ما معنى «لا» في «لا جرم» ودلالتها، وما سرّ التوكيد بضمير الفصل «هم»، وما دلالة التعبير بصيغة التفضيل «الأخسرون»؟","answer":"تفيد ﴿لا جرم﴾ تأكيد الحكم وتحققه، ويؤكد ضمير الفصل اختصاصهم بأقصى الخسران. وجاء ﴿الأخسرون﴾ لأنهم جمعوا خسارة الدنيا والآخرة وخسارة أنفسهم؛ فهي خسارة عظيمة لا تنقطع.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص607، 609–610، تحت «معنى «لا» في «لا جرم» ودلالتها؛ سر التوكيد بضمير الفصل «هم»؛ دلالة التعبير بصيغة التفضيل «الأخسرون»»","url":""}]},{"id":"s11-45","number":45,"surah":11,"verses":[23],"references":[{"surah":11,"verses":[23]}],"verseLabel":"هود: 23","question":"ما سرّ تعدية الإخبات بـ﴿إلى﴾ في قوله تعالى: ﴿وأخبتوا إلى ربهم﴾؟","answer":"لأن الإخبات ليس خشوعًا ساكنًا فقط، بل توجه وطمأنينة وانقياد ينتهي إلى الله؛ فالحرف يرسم جهة القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص617–618، تحت «معنى «إلى» ودلالته في «إلى ربهم»»","url":""}]},{"id":"s11-46","number":46,"surah":11,"verses":[24],"references":[{"surah":11,"verses":[24]}],"verseLabel":"هود: 24","question":"ما دلالة تشبيه الفريقين بالأعمى والأصم، والبصير والسميع؟","answer":"الكافر لا يرى الدليل ولا يسمع داعيه سماع قبول، والمؤمن يجمع الإدراكين؛ فالصورة تحول الفرق المعنوي إلى مشهد محسوس.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص625–626، تحت «الغرض من التشبيه في «مثل الفريقين»»","url":""}]},{"id":"s11-47","number":47,"surah":11,"verses":[24],"references":[{"surah":11,"verses":[24]}],"verseLabel":"هود: 24","question":"ما سرّ ختم المثل بقوله تعالى: ﴿هل يستويان مثلًا أفلا تذكرون﴾؟","answer":"الاستفهام يحمل السامع على إصدار الحكم بنفسه، ثم يوبخه على ترك أبسط تذكر يميز بين النور والعمى.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص628، 630، تحت «الغرض من الاستفهام في «هل يستويان مثلًا»؛ الغرض من الاستفهام في «أفلا تذكرون»»","url":""}]},{"id":"s11-48","number":48,"surah":11,"verses":[25],"references":[{"surah":11,"verses":[25]}],"verseLabel":"هود: 25","question":"ما دلالة تقديم ﴿لكم﴾ ووصف الإنذار بالبيان في قول نوح: ﴿إني لكم نذير مبين﴾؟","answer":"تقديم ﴿لكم﴾ يخصص قومه بهذا الإنذار، وفيه رفق بالنصح وإشفاق في البلاغ. ووصفه بـ﴿مبين﴾ يدل على أنه بيّن موجب العذاب وطريق الخلاص منه بيانًا واضحًا تزول به الشبهة وتقوم به الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص638، تحت «الغرض من تقديم «لكم» على خبر إن؛ الغرض من وصف الخبر بـ«مبين»»","url":""}]},{"id":"s11-49","number":49,"surah":11,"verses":[26],"references":[{"surah":11,"verses":[26]}],"verseLabel":"هود: 26","question":"ما دلالة حصر العبادة بقوله تعالى: ﴿أن لا تعبدوا إلا الله﴾؟","answer":"لأن أصل فسادهم توزيع العبادة بين الله وغيره، فجاء النفي والاستثناء ليهدما كل شريك ويثبتا العبادة له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص643–644، تحت «الغرض من القصر في «لا تعبدوا إلا الله»»","url":""}]},{"id":"s11-50","number":50,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما سرّ إيثار وصف نوح بالبشرية في قول الملأ: ﴿ما نراك إلا بشرًا﴾؟","answer":"وقفوا عند ظاهر البشرية، فتوهموا أن مشاركة الرسول لهم في الخِلقة تمنع اختصاصه بالوحي، وكشف التعبير قصور تصورهم لحقيقة النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص655، تحت «سر إيثار التعبير بالبشرية»","url":""}]},{"id":"s11-206","number":206,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما دلالة قول الملأ لنوح: ﴿بشرًا مثلنا﴾؟","answer":"أرادوا بالمماثلة نفي كل مزية تؤهله للرسالة، وفي قولهم استهانة وادعاء للتفوق يكشفان نظرهم إلى الظاهر دون حقيقة الاصطفاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص656، تحت «دلالة وصف المقصور بـ﴿مثلنا﴾»","url":""}]},{"id":"s11-51","number":51,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما دلالة وصف أتباع نوح بقولهم: ﴿أراذلنا بادي الرأي﴾؟","answer":"احتقروا ضعفهم الاجتماعي وزعموا أنهم آمنوا لأول خاطر بلا تدبر، فاستبدلوا وزن الدليل بميزان الطبقة والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص660–661، تحت «سر العدول في «أراذلنا»؛ دلالة وصف المقصور عليه بـ«بادي الرأي»»","url":""}]},{"id":"s11-52","number":52,"surah":11,"verses":[27],"references":[{"surah":11,"verses":[27]}],"verseLabel":"هود: 27","question":"ما دلالة قول الملأ: ﴿وما نرى لكم علينا من فضل﴾؟","answer":"نفوا عن نوح وأتباعه أي فضل يوجب اتباعهم، ونظروا إلى مقاييس القوة والكثرة والمال. وتؤكد ﴿من﴾ استغراق النفي حتى لأدنى فضل، فتكشف العبارة كبرهم واعتمادهم على المظاهر.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص664–665، تحت «الغرض من تقديم «لكم»؛ دلالة «من» ومعناها في «من فضل»»","url":""}]},{"id":"s11-53","number":53,"surah":11,"verses":[28],"references":[{"surah":11,"verses":[28]}],"verseLabel":"هود: 28","question":"ما سرّ التعبير في قول نوح: ﴿إن كنت على بينة من ربي وآتاني رحمة من عنده فعميت عليكم﴾؟","answer":"قابل ظنهم الظاهر ببصيرته القائمة على البينة، وبيّن أن خفاء الرحمة عنهم ناشئ من إعراضهم لا من ضعفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص677–678، 680، 682، تحت «الغرض من الاستعارة في «على»؛ الغرض من تنكير «رحمة»؛ سر إيثار التعبير بالعمى دون الخفاء؛ معنى حرف الجر «عليكم» ودلالته»","url":""}]},{"id":"s11-54","number":54,"surah":11,"verses":[28],"references":[{"surah":11,"verses":[28]}],"verseLabel":"هود: 28","question":"ما وجه البلاغة في التعبير بلفظ «أنلزمكموها»، وما الغرض البلاغي من الاستفهام في «أنلزمكموها»؟","answer":"الإيمان لا يتحقق بإكراه القلب، والعبارة الطويلة في ﴿أنلزمكموها﴾ تشعر بثقل الإلزام الذي أنكروه؛ ومهمة الرسول البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص683–684، تحت «بلاغة التعبير بلفظ «أنلزمكموها»؛ الغرض من الاستفهام في «أنلزمكموها»»","url":""}]},{"id":"s11-55","number":55,"surah":11,"verses":[29],"references":[{"surah":11,"verses":[29]}],"verseLabel":"هود: 29","question":"ما سرّ تكرار نوح نداء قومه بقوله: ﴿يا قوم﴾؟","answer":"التكرار يستعطفهم ويؤكد بقاء رابطة النصح رغم أذاهم؛ فهو لا يخاطب أعداء غرباء بل قومًا يريد نجاتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص691، تحت «سر إعادة النداء بـ«ويا قوم» وسر عطفه بالواو»","url":""}]},{"id":"s11-56","number":56,"surah":11,"verses":[29],"references":[{"surah":11,"verses":[29]}],"verseLabel":"هود: 29","question":"ما وجه البلاغة في الاحتراس في قوله «إن أجري إلا على الله»، وما الغرض البلاغي من التعبير بأسلوب القصر في السياق؟","answer":"نفى التهمة التي قد تحجبهم عن مضمون الدعوة؛ فاستغناؤه عن مالهم دليل إخلاصه، وحصر أجره في الله يحرره من ضغطهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص693، تحت «بلاغة الاحتراس في قوله «إن أجري إلا على الله»؛ الغرض من التعبير بأسلوب القصر في السياق»","url":""}]},{"id":"s11-57","number":57,"surah":11,"verses":[29],"references":[{"surah":11,"verses":[29]}],"verseLabel":"هود: 29","question":"ما دلالة تعليل رفض طرد المؤمنين بقوله تعالى: ﴿إنهم ملاقو ربهم﴾؟","answer":"يذكر نوح بحق المؤمنين وكرامتهم، وأنهم راجعون إلى ربهم؛ فطردهم ظلم يخاصمونه به عند الله. وفي التعليل ردّ على احتقار الملأ لهم، وإحالة إلى حكم الله بدل الحكم عليهم بالمكانة والمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص695، 697، تحت «لطيفة ارتباط نفي الطرد بجملة «وما نراك اتبعك»؛ موقع جملة «إنهم ملاقو ربهم» مما قبلها ودلالتها»","url":""}]},{"id":"s11-58","number":58,"surah":11,"verses":[30],"references":[{"surah":11,"verses":[30]}],"verseLabel":"هود: 30","question":"ما سرّ الاستفهام في قول نوح: ﴿من ينصرني من الله إن طردتهم﴾؟","answer":"نقل نوح القضية من طلب رضا الزعماء إلى حساب الله: فمن يحميه إن ظلم المؤمنين وطردهم؟ وفي ذلك إنكار لاقتراحهم وكشف لما يجر إليه من معصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص704، تحت «الغرض من الاستفهام في سياق الآية»","url":""}]},{"id":"s11-59","number":59,"surah":11,"verses":[31],"references":[{"surah":11,"verses":[31]}],"verseLabel":"هود: 31","question":"ما دلالة نفي نوح امتلاك خزائن الله وعلم الغيب وكونه ملكًا؟","answer":"صحح تصور النبوة: الرسول بشر يوحى إليه، لا يملك الرزق ولا الغيب ولا يتكلف طبيعة الملك؛ فقيمة دعوته في الوحي لا الخوارق المقترحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص710–712، 714، تحت «دلالة التعبير بالظرف «عندي» مقدمًا في السياق؛ لطيفة في علاقة جملة نفي الملائكية بتأكيد البشرية؛ لطيفة في تكرار الفعل «أقول» ثلاث مرات»","url":""}]},{"id":"s11-60","number":60,"surah":11,"verses":[31],"references":[{"surah":11,"verses":[31]}],"verseLabel":"هود: 31","question":"ما سرّ التعبير في قوله تعالى عن الضعفاء: ﴿الله أعلم بما في أنفسهم﴾؟","answer":"لم يزكِّ باطنهم من عند نفسه، لكنه رفض احتقارهم؛ فحساب السرائر لله، والواجب قبول ظاهر الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص717–718، تحت «دلالة وقوع المسند «أعلم» على صيغة «أفعل»؛ دلالة «ما» الموصولة وسر إيثارها على غيرها»","url":""}]},{"id":"s11-61","number":61,"surah":11,"verses":[32],"references":[{"surah":11,"verses":[32]}],"verseLabel":"هود: 32","question":"ما دلالة قول قوم نوح: ﴿قد جادلتنا فأكثرت جدالنا﴾؟","answer":"حولوا طول البيان والحجة إلى تهمة، ثم طلبوا العذاب استعجالًا؛ وهو انتقال من عجز المناظرة إلى المكابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص724–725، تحت «دلالة التعبير بالماضي «أكثرت» في السياق؛ سر تقييد الفعل «جدالنا» بالمفعول به؛ الغرض من التعبير بفعل الأمر «فأتنا»»","url":""}]},{"id":"s11-62","number":62,"surah":11,"verses":[33],"references":[{"surah":11,"verses":[33]}],"verseLabel":"هود: 33","question":"ما سرّ القصر في قول نوح: ﴿إنما يأتيكم به الله﴾؟","answer":"قصر الإتيان بالعذاب على الله وحده؛ فالرسول منذر لا يملك إنزال العقوبة ولا تحديد وقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص730، تحت «السر في تعبيره بأسلوب القصر»","url":""}]},{"id":"s11-207","number":207,"surah":11,"verses":[33],"references":[{"surah":11,"verses":[33]}],"verseLabel":"هود: 33","question":"ما دلالة تقييد إتيان العذاب بالمشيئة في قوله: ﴿إن شاء﴾؟","answer":"يبين أن وقوع العذاب ووقته تابعان لمشيئة الله وحكمته، لا لاستعجال المكذبين ولا لقدرة الرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص731، تحت «الغرض من ذكر جملة الشرط ﴿إن شاء﴾»","url":""}]},{"id":"s11-63","number":63,"surah":11,"verses":[34],"references":[{"surah":11,"verses":[34]}],"verseLabel":"هود: 34","question":"ما دلالة تعليق نفع نصح نوح بشرط إرادة الله في قوله: ﴿ولا ينفعكم نصحي إن أردت أن أنصح لكم إن كان الله يريد أن يغويكم﴾؟","answer":"يبين أن النصح لا ينفع من أصر على التكذيب حتى استحق الخذلان؛ فانتفاعه بالهداية تابع لحكمة الله مع بقاء مسؤوليته عن اختياره.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص738، تحت «الغرض من التعبير بأسلوب الشرط في سياق الآية الكريمة»","url":""}]},{"id":"s11-208","number":208,"surah":11,"verses":[34],"references":[{"surah":11,"verses":[34]}],"verseLabel":"هود: 34","question":"ما دلالة التصريح باسم الجلالة في قوله: ﴿إن كان الله يريد أن يغويكم﴾؟","answer":"يصرح بأن الأمر كله لله ويستحضر جلاله وقدرته، فلا يملك الرسول هداية من أعرض واستحق الخذلان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص739، تحت «الغرض من التعبير باسم الجلالة ﴿الله﴾»","url":""}]},{"id":"s11-64","number":64,"surah":11,"verses":[35],"references":[{"surah":11,"verses":[35]}],"verseLabel":"هود: 35","question":"ما دلالة ورود ﴿أم يقولون افتراه﴾ في أثناء قصة نوح؟","answer":"على تفسيرها اعتراضًا في القصة، تنتقل الآية إلى مكذبي محمد ﷺ، وتبين أن إخباره بهذه التفاصيل الغيبية دليل على الوحي؛ فاتهامهم له بالافتراء مردود عليهم. وذكر المصدر وجهًا آخر يجعل الكلام من قصة نوح نفسها وردّه على قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص744–745، تحت «الآية الكريمة بين الاعتراض وعدمه»","url":""}]},{"id":"s11-65","number":65,"surah":11,"verses":[36],"references":[{"surah":11,"verses":[36]}],"verseLabel":"هود: 36","question":"ما دلالة القصر في قوله تعالى لنوح: ﴿لن يؤمن من قومك إلا من قد آمن﴾؟","answer":"أعلن انتهاء زمن الاستجابة بعد استنفاد البلاغ، وقصر المؤمنين على من سبق إيمانه؛ فأراح نوحًا من انتظار إيمان جديد ونهاه عن الحزن على اختيار قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص751، تحت «الغرض من التعبير بأسلوب القصر في السياق»","url":""}]},{"id":"s11-66","number":66,"surah":11,"verses":[37],"references":[{"surah":11,"verses":[37]}],"verseLabel":"هود: 37","question":"ما دلالة الجمع بين ﴿بأعيننا﴾ و﴿وحينا﴾ في الأمر بصنع الفلك؟","answer":"يجمع التعبير الحفظ والتعليم؛ فـ﴿بأعيننا﴾ كناية عن الرعاية والحراسة، و﴿وحينا﴾ يدل على أن صنع الفلك جرى بتعليم الله وتوجيهه. وبذلك يطمئن نوح إلى الحماية من أعدائه وإلى معرفة كيفية الصنع.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص758–759، تحت «التعبير بالجار والمجرور «بأعيننا» وما فيه من الكناية؛ دلالة عطف الوحي على الأعين في «ووحينا»»","url":""}]},{"id":"s11-67","number":67,"surah":11,"verses":[37],"references":[{"surah":11,"verses":[37]}],"verseLabel":"هود: 37","question":"ما دلالة النهي في قوله تعالى: ﴿ولا تخاطبني في الذين ظلموا إنهم مغرقون﴾؟","answer":"النهي عن طلب رفع العذاب عنهم أو تخفيفه أو تأخيره؛ فقد صدر الحكم بإغراقهم. وجاءت ﴿إنهم مغرقون﴾ تعليلًا للنهي وإخبارًا بأمر محتوم، فحسمت رجاء الشفاعة في إنجائهم من ذلك العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص759–761، تحت «الغرض من أسلوب النهي في «ولا تخاطبني»؛ موقع جملة «إنهم مغرقون» ودلالته»","url":""}]},{"id":"s11-68","number":68,"surah":11,"verses":[38],"references":[{"surah":11,"verses":[38]}],"verseLabel":"هود: 38","question":"ما سرّ التعبير بالمضارع في قوله تعالى: ﴿ويصنع الفلك﴾؟","answer":"يستحضر مشهد البناء المتجدد أمام الساخرين، وكل مرور للملأ يفتح جولة استهزاء؛ فكأن القارئ يرى الحدث.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص766–767، تحت «سر التعبير بالمضارع «ويصنع»»","url":""}]},{"id":"s11-69","number":69,"surah":11,"verses":[38],"references":[{"surah":11,"verses":[38]}],"verseLabel":"هود: 38","question":"ما سرّ التعبير في قول نوح: ﴿إن تسخروا منا فإنا نسخر منكم﴾؟","answer":"ليس مقابلة سباب، بل وعد بانكشاف موضع السخرية الحقيقي عند حلول العذاب؛ ستتحول سخريتهم القصيرة إلى حسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص777–778، تحت «التعبير بالسخرية بين المشاكلة والمجاز»","url":""}]},{"id":"s11-71","number":71,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]}],"verseLabel":"هود: 40","question":"ما دلالة ﴿فار التنور﴾ علامةً لبدء الطوفان؟","answer":"على تفسير التنور بأنه موقد الخبز، كان خروج الماء منه علامة على بدء الطوفان؛ فإذا فار الماء من موضع يابس محفوظ من الرطوبة، كان فورانه من غيره أشد. فجعل الله هذه العلامة إيذانًا لنوح ومن معه بالاستعداد والركوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص798–799، تحت «لفظ «التنور» بين الحقيقة والمجاز»","url":""}]},{"id":"s11-72","number":72,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]},{"surah":23,"verses":[27]}],"verseLabel":"هود: 40؛ المؤمنون: 27","question":"ما سرّ اختيار لفظ ﴿زوج﴾ في قوله: ﴿من كل زوجين اثنين﴾؟","answer":"يدل لفظ الزوج على اقتران الذكر بالأنثى، وهو الملائم لحفظ الأنواع واستمرار نسلها بعد الطوفان.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص803، تحت «نكتة اختيار لفظ ﴿زوج﴾»","url":""}]},{"id":"s11-209","number":209,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]},{"surah":23,"verses":[27]}],"verseLabel":"هود: 40؛ المؤمنون: 27","question":"ما دلالة الاحتراس بلفظ ﴿اثنين﴾ بعد ﴿زوجين﴾؟","answer":"يزيل احتمال إرادة فرد واحد أو أكثر من اثنين، ويحدد المطلوب بذكر وأنثى من كل نوع لحفظ النسل.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص803، تحت «دلالة الاحتراس في ﴿اثنين﴾»","url":""}]},{"id":"s11-210","number":210,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]},{"surah":23,"verses":[27]}],"verseLabel":"هود: 40؛ المؤمنون: 27","question":"ما دلالة تنكير ﴿زوجين﴾ في قوله تعالى في المؤمنون: ﴿من كل زوجين اثنين﴾؟","answer":"يفيد عدم تعيين فردين بأعيانهما؛ فالمقصود حمل ذكر وأنثى صالحين من كل نوع ليبقى النسل، لا زوجين معلومين مخصوصين.","sources":[{"label":"موسوعة التفسير البلاغي، ج35، ص590، تحت «نكتة تنكير لفظ ﴿زوجين﴾»","url":""}]},{"id":"s11-73","number":73,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]}],"verseLabel":"هود: 40","question":"ما دلالة استثناء ﴿من سبق عليه القول﴾ من أهل نوح؟","answer":"يبين أن القرابة لا تنقض حكم الإيمان والكفر؛ فالنجاة متصلة بالاستجابة لا بالنسب، وقد سبق الحكم على من اختار التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج20، ص804، تحت «دلالة الاستثناء»","url":""}]},{"id":"s11-74","number":74,"surah":11,"verses":[41],"references":[{"surah":11,"verses":[41]}],"verseLabel":"هود: 41","question":"ما سرّ التعبير في قول نوح: ﴿بسم الله مجراها ومرساها﴾؟","answer":"نسب بدء السفينة وسيرها ووقوفها إلى اسم الله، ليعلن أن الأسباب المادية وحدها لا تنجي، وإنما تجري برعايته وتقف بأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص14–16، تحت «الباء في «بسم» بين الحقيقة والمجاز؛ سر تقديم «بسم الله»»","url":""}]},{"id":"s11-75","number":75,"surah":11,"verses":[41],"references":[{"surah":11,"verses":[41]}],"verseLabel":"هود: 41","question":"ما دلالة ذكر المغفرة والرحمة في قوله: ﴿إن ربي لغفور رحيم﴾ وسط مشهد الطوفان؟","answer":"نجاة المؤمنين من الطوفان فضل من الله ورحمة، لا استحقاق يلزمه؛ فختم الكلام بالمغفرة والرحمة يعلل النجاة ويوازن بين إهلاك المكذبين ورعاية المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص20، تحت «دلالة ذكر المغفرة والرحمة»","url":""}]},{"id":"s11-76","number":76,"surah":11,"verses":[42],"references":[{"surah":11,"verses":[42]}],"verseLabel":"هود: 42","question":"ما دلالة تشبيه أمواج الطوفان بالجبال؟","answer":"لبيان علوها وضخامتها وثقل رهبتها؛ فالسفينة لا تسير فوق ماء هادئ بل بين كتل هائلة لا ينجي منها إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص29، تحت «دلالة التشبيه في «في موج كالجبال»»","url":""}]},{"id":"s11-77","number":77,"surah":11,"verses":[42],"references":[{"surah":11,"verses":[42]}],"verseLabel":"هود: 42","question":"لماذا انتقل السياق من قوله: ﴿وقال اركبوا فيها﴾ إلى قوله: ﴿ونادى نوح ابنه﴾؟","answer":"جاء الأمر بالركوب عامًا لمن معه، أما الابن فكان بعيدًا عن موضع السفينة فاحتاج إلى نداء يبلغ البعيد؛ وفي تخصيصه بالنداء تصوير لحرص الأب على نجاته في اللحظة الأخيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص31، تحت «سر التعبير في «وقال اركبوا» و«ونادى نوح ابنه»»","url":""}]},{"id":"s11-211","number":211,"surah":11,"verses":[42],"references":[{"surah":11,"verses":[42]}],"verseLabel":"هود: 42","question":"ما دلالة وصف ابن نوح بأنه ﴿كان في معزل﴾؟","answer":"يصوّر اسم المكان ابتعاده عن أبيه والمؤمنين وعن موضع النجاة، وتوحي عزلته المكانية بعزلته عن جماعة الإيمان التي حملتها السفينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص32، تحت «دلالة استعمال اسم المكان «معزل»»","url":""}]},{"id":"s11-78","number":78,"surah":11,"verses":[43],"references":[{"surah":11,"verses":[43]}],"verseLabel":"هود: 43","question":"ما دلالة قول ابن نوح: ﴿سآوي إلى جبل يعصمني من الماء﴾؟","answer":"يكشف قوله إصراره وغفلته عن حقيقة الموقف؛ فقد توهم أن الالتجاء إلى جبل ينجيه من الماء، وأنكر أن النجاة في الاستجابة لدعوة أبيه. وفي تصوير هذا الوهم تهكم باغتراره بالحماية التي يتخيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص35، تحت «دلالة التهكم في «سآوي إلى جبل يعصمني»»","url":""}]},{"id":"s11-79","number":79,"surah":11,"verses":[43],"references":[{"surah":11,"verses":[43]}],"verseLabel":"هود: 43","question":"ما دلالة التعبير بالفعل «وحال بينهما»، وما دلالة استعمال الفاء في «فكان»؟","answer":"الجملة تقطع الحوار فجأة كما قطع الموج الصلة بينهما؛ فسرعة الأسلوب تجسد مباغتة النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص39–40، تحت «دلالة التعبير بالفعل «وحال بينهما»؛ دلالة استعمال الفاء في «فكان»»","url":""}]},{"id":"s11-80","number":80,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما دلالة توجيه الخطاب إلى الأرض والسماء في قوله تعالى: ﴿يا أرض ابلعي ماءك ويا سماء أقلعي﴾؟","answer":"صوّرهما مأمورتين تستجيبان فورًا لسلطان الله؛ فالمشهد الكوني الهائل ينتهي بكلمتين موجزتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص47، 50، تحت «بلاغة التعبير بالنداء «يا أرض»؛ الغرض من التعبير بالاستعارة المكنية»","url":""}]},{"id":"s11-81","number":81,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما سرّ توجيه الخطاب إلى الأرض بـ﴿ابلعي﴾ وإلى السماء بـ﴿أقلعي﴾؟","answer":"الأرض مأمورة بابتلاع الماء الموجود، والسماء مأمورة بالكف عن إنزاله؛ فاختير لكل جهة الفعل المطابق لدورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص52، 58، تحت «بلاغة الاستعارة في «البلع»؛ غرض الاستعارة التصريحية في «أقلعي»»","url":""}]},{"id":"s11-82","number":82,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما سرّ بناء الفعلين للمفعول في قوله تعالى: ﴿وغيض الماء وقضي الأمر﴾؟","answer":"فاعل هذه الأفعال معلوم؛ فلا يقدر على إنهاء الطوفان وإنفاذ أمره إلا الله. وحذف الفاعل يوجز العبارة ويوجه النظر إلى تحقق النتائج: نقصان الماء وتمام ما وعد به من إهلاك الكافرين وإنجاء المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص62–63، 65، تحت «دلالة بناء الفعل «وغيض» للمفعول؛ نكتة بناء الفعل للمفعول في «وقضي»؛ غرض الكناية في الأفعال المبنية للمفعول»","url":""}]},{"id":"s11-83","number":83,"surah":11,"verses":[44],"references":[{"surah":11,"verses":[44]}],"verseLabel":"هود: 44","question":"ما دلالة ختم مشهد الطوفان بقوله تعالى: ﴿بعدًا للقوم الظالمين﴾؟","answer":"بعد سكون الطبيعة صدر الحكم الأخلاقي: لم يكن الغرق حادثًا طبيعيًا عابرًا، بل إبعادًا مستحقًا بسبب الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص70–72، تحت «فائدة استعمال المصدر «بعدًا»؛ معنى اللام الداخلة على «القوم»؛ سر التعبير بالظالمين دون الكافرين»","url":""}]},{"id":"s11-84","number":84,"surah":11,"verses":[45],"references":[{"surah":11,"verses":[45]}],"verseLabel":"هود: 45","question":"ما سرّ التعبير في قول نوح: ﴿إن ابني من أهلي وإن وعدك الحق﴾؟","answer":"في قوله إظهار لشفقته على ابنه، ورجاء أن يشمله وعد نجاة الأهل، لا اعتراض على حكم الله. وذكر المصدر أن كلامه يتضمن طلب الرحمة والمغفرة لابنه، مع التسليم بأن وعد الله حق وأن الحكم إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص84–85، تحت «دلالة الجملة الخبرية «إن ابني من أهلي»؛ دلالة الجملة الخبرية في «وإن وعدك الحق»»","url":""}]},{"id":"s11-85","number":85,"surah":11,"verses":[46],"references":[{"surah":11,"verses":[46]}],"verseLabel":"هود: 46","question":"ما معنى قوله تعالى عن ابن نوح: ﴿إنه ليس من أهلك﴾؟","answer":"المنفي هو دخوله في الأهل الموعودين بالنجاة، لا نسبه إلى نوح؛ لأن رابطة الإيمان هي المعتبرة في هذا الوعد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص94–95، تحت «معنى نفي الأهلية»","url":""}]},{"id":"s11-212","number":212,"surah":11,"verses":[46],"references":[{"surah":11,"verses":[46]}],"verseLabel":"هود: 46","question":"ما سر الإخبار عن ابن نوح بالمصدر في قوله: ﴿إنه عمل غير صالح﴾؟","answer":"بلغ في ملازمة العمل غير الصالح مبلغًا صُوِّر معه كأنه نفس العمل، مبالغة في بيان فساد طريقه وسبب خروجه من أهل النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص97، تحت «نكتة الإخبار عن الذات بالمصدر»","url":""}]},{"id":"s11-86","number":86,"surah":11,"verses":[46],"references":[{"surah":11,"verses":[46]}],"verseLabel":"هود: 46","question":"ما دلالة قوله تعالى لنوح: ﴿فلا تسألن ما ليس لك به علم﴾؟","answer":"هو تعليم وعتاب برفق، يرشد إلى ألا يُطلب أمر حتى يُعلم وجه صوابه، ويصحح إدخال ابنه في الأهل الموعودين بالنجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص97، تحت «غرض النهي ودلالته»","url":""}]},{"id":"s11-87","number":87,"surah":11,"verses":[47],"references":[{"surah":11,"verses":[47]}],"verseLabel":"هود: 47","question":"ما دلالة استعاذة نوح بقوله: ﴿أعوذ بك أن أسألك ما ليس لي به علم﴾؟","answer":"لم يكتف بترك السؤال، بل لجأ إلى الله أن يعصمه من العودة إلى مثله؛ وفي ذلك كمال سرعة الرجوع وشدة الخوف من تجاوز حد العلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص108، تحت «دلالة ذكر الاستعاذة»","url":""}]},{"id":"s11-213","number":213,"surah":11,"verses":[47],"references":[{"surah":11,"verses":[47]}],"verseLabel":"هود: 47","question":"لماذا قدّم نوح طلب المغفرة على الرحمة في قوله: ﴿وإلا تغفر لي وترحمني أكن من الخاسرين﴾؟","answer":"لأن إزالة أثر الذنب بالمغفرة تسبق نيل الفضل بالرحمة؛ فبدأ بطلب الوقاية من الضرر ثم طلب تمام الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص110، تحت «نكتة تقديم المغفرة على الرحمة»","url":""}]},{"id":"s11-88","number":88,"surah":11,"verses":[48],"references":[{"surah":11,"verses":[48]}],"verseLabel":"هود: 48","question":"ما دلالة الجمع بين السلام والبركات في قوله: ﴿اهبط بسلام منا وبركات عليك﴾؟","answer":"السلام يؤمّن نوحًا ومن معه من مخاوف الطوفان، والبركات تبشرهم بنماء الحياة والخير بعد الخراب؛ فجمع لهم الأمن وامتداد النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص120، تحت «دلالة الجمع بين السلام والبركات»","url":""}]},{"id":"s11-89","number":89,"surah":11,"verses":[48],"references":[{"surah":11,"verses":[48]}],"verseLabel":"هود: 48","question":"لماذا ذُكرت أمم تتمتع ثم يمسها العذاب بعد بشارة نوح بالسلام والبركات؟","answer":"احتُرس بذلك من توهم شمول السلام والبركات لكل الذرية؛ فمنهم مؤمنون ينالون البركة، ومنهم أمم تتمتع زمنًا ثم تستحق العذاب بكفرها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص123، تحت «بلاغة الاحتراس في التكرار اللفظي»","url":""}]},{"id":"s11-90","number":90,"surah":11,"verses":[49],"references":[{"surah":11,"verses":[49]}],"verseLabel":"هود: 49","question":"لماذا سُمّيت قصة نوح من ﴿أنباء الغيب﴾؟","answer":"لأن النبأ خبر عظيم ذو شأن؛ فالتعبير ينبه إلى عظمة ما أوحي من خبر نوح ووجوب الاعتبار به، لا تلقيه حكاية مجردة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص131، تحت «نكتة التعبير بلفظ النبأ»","url":""}]},{"id":"s11-214","number":214,"surah":11,"verses":[49],"references":[{"surah":11,"verses":[49]}],"verseLabel":"هود: 49","question":"ما دلالة قوله بعد قصة نوح: ﴿ما كنت تعلمها أنت ولا قومك من قبل هذا﴾؟","answer":"ينفي أن تكون هذه التفاصيل مكتسبة من معرفة سابقة عند النبي ﷺ أو قومه، فيكون الإخبار بها حجة على أنها وحي من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص133، تحت «دلالة نفي العلم»","url":""}]},{"id":"s11-91","number":91,"surah":11,"verses":[49],"references":[{"surah":11,"verses":[49]}],"verseLabel":"هود: 49","question":"ما دلالة ختم قصة نوح بقوله تعالى: ﴿فاصبر إن العاقبة للمتقين﴾؟","answer":"ينقل القصة من حكاية الماضي إلى تثبيت الرسول ﷺ: كما طال ابتلاء نوح ثم نجا، فاصبر؛ فالعاقبة لأهل التقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص137، تحت «غرض الأمر ونكتته»","url":""}]},{"id":"s11-92","number":92,"surah":11,"verses":[50],"references":[{"surah":11,"verses":[50]}],"verseLabel":"هود: 50","question":"ما سرّ التعبير في قوله تعالى في إرسال هود إلى عاد: ﴿أخاهم هودًا﴾؟","answer":"أخوّته لهم في النسب والقوم تجعل نصحه أقرب، وتنفي أن يكون غريبًا عن مصالحهم؛ أما مفاصلته فكانت في العقيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص144، تحت «دلالة التعبير بـ«أخاهم»»","url":""}]},{"id":"s11-93","number":93,"surah":11,"verses":[50],"references":[{"surah":11,"verses":[50]}],"verseLabel":"هود: 50","question":"ما دلالة حرف «من» وغرضه، وما فائدة القصر بالنفي والاستثناء، وما وجه البلاغة في استعمال مفردة الافتراء؟","answer":"بعد حصر الإله الحق كشف أن تعدد الآلهة اختلاق بلا برهان؛ فالشرك ليس نقص دليل فقط بل نسبة باطلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص146–147، تحت «دلالة حرف «من» وغرضه؛ فائدة القصر بالنفي والاستثناء؛ بلاغة استعمال مفردة الافتراء»","url":""}]},{"id":"s11-94","number":94,"surah":11,"verses":[51],"references":[{"surah":11,"verses":[51]}],"verseLabel":"هود: 51","question":"ما دلالة نفي هود طلب الأجر في قوله: ﴿لا أسألكم عليه أجرًا﴾؟","answer":"يدل على إخلاص الدعوة وأنها ليست تجارة أو طلب منفعة من القوم، ويقطع شبهة أن يكون وراء دعوته مطمع دنيوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص147، تحت «دلالة نفي السؤال»","url":""}]},{"id":"s11-215","number":215,"surah":11,"verses":[51],"references":[{"surah":11,"verses":[51]}],"verseLabel":"هود: 51","question":"ما سر قول هود: ﴿إن أجري إلا على الذي فطرني﴾؟","answer":"اختار ﴿فطرني﴾ تذكيرًا بأن الخالق الذي أوجده هو وحده المستحق للعبادة والقادر على جزائه، بخلاف الأصنام التي لا تخلق ولا تنفع.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص149، تحت «سر استعمال «فطرني»»","url":""}]},{"id":"s11-95","number":95,"surah":11,"verses":[52],"references":[{"surah":11,"verses":[52]}],"verseLabel":"هود: 52","question":"لماذا ربط هود الاستغفار بنزول المطر وزيادة القوة؟","answer":"لأن التوبة سبب لفتح أبواب البركة، وجاء الوعد بما كانت عاد أحوج إليه: الغيث الذي يحيي أرضهم، وقوة تزداد على قوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص162، تحت «وجه الوعد بإنزال الماء»","url":""}]},{"id":"s11-96","number":96,"surah":11,"verses":[53],"references":[{"surah":11,"verses":[53]}],"verseLabel":"هود: 53","question":"ما دلالة قول قوم هود: ﴿ما جئتنا ببينة﴾؟","answer":"يعبر النفي عن عنادهم وعدم اعتدادهم بالحجج، لا عن خلو دعوته من البينة؛ فقد جعلوا إنكارها ذريعة للبقاء على كفرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص169، تحت «دلالة النفي»","url":""}]},{"id":"s11-97","number":97,"surah":11,"verses":[54],"references":[{"surah":11,"verses":[54]}],"verseLabel":"هود: 54","question":"ما دلالة اتهام قوم هود له بقولهم: ﴿إن نقول إلا اعتراك بعض آلهتنا بسوء﴾؟","answer":"عجزوا عن رد حجته ففسروا ثباته بالمس والجنون، ونسبوا الضر إلى أصنامهم ليحموا هيبتها؛ فجاء إعلان براءته منها وتحديه لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص179–180، تحت «دلالة التعبير بلفظ «بعض»؛ الغرض من الخبر في الاتهام بالجنون»","url":""}]},{"id":"s11-98","number":98,"surah":11,"verses":[55],"references":[{"surah":11,"verses":[55]}],"verseLabel":"هود: 55","question":"ما دلالة تحدي هود قومه بقوله: ﴿فكيدوني جميعًا ثم لا تنظرون﴾؟","answer":"إظهار عملي لبطلان آلهتهم وثقته بالله؛ دعاهم مع معبوداتهم إلى أقصى الكيد دون إمهال، فعجزهم حجة محسوسة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص184، 186–187، تحت «معنى الفاء في قوله «فكيدوني»؛ بلاغة الكناية في الآية الكريمة؛ نكتة استعمال لفظ «جميعًا»»","url":""}]},{"id":"s11-99","number":99,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما دلالة الاستئناف التعليلي في «إني توكلت»، وما دلالة التعبير بـ«الله ربي»؟","answer":"جمع بين ربوبيته الخاصة التي تبعث الطمأنينة وربوبيته لهم التي تثبت سلطان الله عليهم ولو أنكروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص193–194، تحت «دلالة الاستئناف التعليلي في «إني توكلت»؛ دلالة التعبير بـ«الله ربي»»","url":""}]},{"id":"s11-100","number":100,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما سر صورة ﴿ما من دابة إلا هو آخذ بناصيتها﴾؟","answer":"تمثل الصورة كل حي منقادًا تحت قبضة الله وتدبيره، كما يقاد المأخوذ بناصيته؛ فلا تتحرك قوة مستقلة عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص195، تحت «بلاغة الاستعارة التمثيلية في الأخذ بالناصية»","url":""}]},{"id":"s11-101","number":101,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما دلالة قوله تعالى: ﴿إن ربي على صراط مستقيم﴾ بعد ذكر التوكل وسلطان الله على كل دابة؟","answer":"يبين أن سلطان الله وتدبيره قائمان على الحق والعدل؛ لذلك صح التوكل عليه، فلا يخذل من اعتصم به ولا يفلت الظالم من حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص196، تحت «سر التعليل بعد ذكر التوكل»","url":""}]},{"id":"s11-216","number":216,"surah":11,"verses":[56],"references":[{"surah":11,"verses":[56]}],"verseLabel":"هود: 56","question":"ما دلالة تصوير عدل الله بقوله: ﴿إن ربي على صراط مستقيم﴾؟","answer":"صُوّر نهج الله في تدبير خلقه بالصراط المستقيم الذي لا عوج فيه، للدلالة على كمال العدل والاستقامة في حكمه ووعده ووعيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص197، تحت «بلاغة الاستعارة التصريحية في «صراط مستقيم»»","url":""}]},{"id":"s11-102","number":102,"surah":11,"verses":[57],"references":[{"surah":11,"verses":[57]}],"verseLabel":"هود: 57","question":"ما سرّ التعبير في قول هود: ﴿فقد أبلغتكم ما أرسلت به إليكم﴾؟","answer":"أقام الحجة وأعلن تمام مهمته؛ فإذا تولوا فالخسارة عليهم، والله قادر أن يستبدل بهم قومًا لا يعصونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص205–206، 208، تحت «معنى الفاء في قوله «فقد أبلغتكم»؛ دلالة «ما» في «ما أرسلت»؛ دلالة جملة الاستئناف في «ويستخلف ربي»»","url":""}]},{"id":"s11-103","number":103,"surah":11,"verses":[58],"references":[{"surah":11,"verses":[58]}],"verseLabel":"هود: 58","question":"ما سر تكرار فعل النجاة في قوله: ﴿نجينا هودًا﴾ ثم ﴿ونجيناهم من عذاب غليظ﴾؟","answer":"يفخم التكرار نعمة النجاة وينبه إلى تعدد وجوهها؛ فنجوا من العذاب الذي نزل بعاد، وقيل إن الثانية تشير كذلك إلى النجاة من عذاب الآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص220، تحت «بلاغة الإطناب في تكرار الإنجاء في الآية»","url":""}]},{"id":"s11-217","number":217,"surah":11,"verses":[58],"references":[{"surah":11,"verses":[58]}],"verseLabel":"هود: 58","question":"ما دلالة تنكير ﴿عذاب غليظ﴾ في قصة عاد؟","answer":"يفيد تفخيم العذاب وتهويل شدته، حتى كأنه عذاب لا يحيط الوصف بمقداره ولا تعرف له غلظة مماثلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص221، تحت «إيثار التعبير بالتنكير في «عذاب غليظ»»","url":""}]},{"id":"s11-104","number":104,"surah":11,"verses":[59],"references":[{"surah":11,"verses":[59]}],"verseLabel":"هود: 59","question":"ما سرّ التعبير في قوله تعالى عن عاد: ﴿وتلك عاد جحدوا بآيات ربهم﴾؟","answer":"اسم الإشارة يعرضهم كأثر حاضر للعبرة، وجمع الجحود وعصيان الرسل واتباع الجبابرة جذور سقوطهم الديني والسياسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص226–228، 233، تحت «سر الإشارة بلفظ «وتلك»؛ سر إيثار التعبير بلفظ الجحود؛ نكتة ترتيب الجمل المبدوءة بالأفعال»","url":""}]},{"id":"s11-105","number":105,"surah":11,"verses":[60],"references":[{"surah":11,"verses":[60]}],"verseLabel":"هود: 60","question":"ما دلالة قوله في عاد: ﴿وأتبعوا في هذه الدنيا لعنة ويوم القيامة﴾؟","answer":"صوّر اللعنة كأنها لاحقة بهم ملازمة لآثارهم في الدنيا، ثم تتبعهم يوم القيامة؛ فليس هلاك حضارتهم نهاية الحساب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص239، تحت «سر إيثار التعبير بـ«وأتبعوا» و«لعنة»»","url":""}]},{"id":"s11-106","number":106,"surah":11,"verses":[60],"references":[{"surah":11,"verses":[60]}],"verseLabel":"هود: 60","question":"ما دلالة ختم قصة عاد بقوله تعالى: ﴿ألا بعدًا لعاد قوم هود﴾؟","answer":"﴿ألا﴾ تلفت إلى الحكم النهائي، ونسبتهم إلى هود تزيد التوبيخ: جاءهم ناصح منهم فعادوه، فاستحقوا الإبعاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص241–243، تحت «نكتة تكرار «ألا»؛ دلالة الدعاء عليهم في «بعدًا لعاد»؛ دلالة عطف البيان في ختام الآية»","url":""}]},{"id":"s11-107","number":107,"surah":11,"verses":[61],"references":[{"surah":11,"verses":[61]}],"verseLabel":"هود: 61","question":"ما سرّ التعبير في قول صالح: ﴿هو أنشأكم من الأرض واستعمركم فيها﴾؟","answer":"ذكّرهم بأصلهم الأرضي وبالتكليف بعمارتها؛ فالذي أنشأهم ومكّنهم هو المستحق للعبادة لا ما يصنعونه فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص253–255، تحت «فائدة جملة «هو أنشأكم»؛ دلالة التعبير بصيغة «واستعمركم»»","url":""}]},{"id":"s11-108","number":108,"surah":11,"verses":[61],"references":[{"surah":11,"verses":[61]}],"verseLabel":"هود: 61","question":"ما دلالة ختم دعوة صالح إلى التوبة بقوله: ﴿إن ربي قريب مجيب﴾؟","answer":"القرب يزيل وحشة الرجوع، والإجابة تبعث الأمل في قبول الدعاء؛ فجاءت الخاتمة ملائمة للاستغفار والتوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص257–258، تحت «دلالة الاستئناف البياني بـ«إن»؛ نكتة الجمع بين القريب والمجيب»","url":""}]},{"id":"s11-109","number":109,"surah":11,"verses":[62],"references":[{"surah":11,"verses":[62]}],"verseLabel":"هود: 62","question":"ما دلالة قول قوم صالح: ﴿قد كنت فينا مرجوًا قبل هذا﴾؟","answer":"حاولوا الضغط عليه بماضي مكانته بينهم: كنا نرجو أن تكون زعيمًا موافقًا لنا، فإذا بالتوحيد يهدم توقعهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص265، تحت «سر الوصف بكونه «مرجوًا»؛ فائدة التعبير بقوله «قبل هذا»»","url":""}]},{"id":"s11-110","number":110,"surah":11,"verses":[62],"references":[{"surah":11,"verses":[62]}],"verseLabel":"هود: 62","question":"ما دلالة كثرة التوكيد في قول قوم صالح: ﴿وإننا لفي شك مما تدعونا إليه﴾؟","answer":"بالغوا في تثبيت شكهم ليصوروه موقفًا راسخًا لا ترددًا عابرًا، ولييئسوا صالحًا من استجابتهم، مع أن قولهم مسوق للطعن وتبرير الرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص268، تحت «دلالة تأكيد الخبر في شكهم في دعوته»","url":""}]},{"id":"s11-218","number":218,"surah":11,"verses":[62],"references":[{"surah":11,"verses":[62]}],"verseLabel":"هود: 62","question":"ما دلالة وصف شك قوم صالح بأنه ﴿مريب﴾؟","answer":"يدل على شك يورث الريبة والقلق ويمنع النفس من الطمأنينة إلى الدعوة، فزاد الوصف تصوير اضطرابهم مع إصرارهم على الرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص270، تحت «غرض وصف الشك بأنه ﴿مريب﴾»","url":""}]},{"id":"s11-111","number":111,"surah":11,"verses":[63],"references":[{"surah":11,"verses":[63]}],"verseLabel":"هود: 63","question":"ما سرّ الاستفهام في قول صالح: ﴿فمن ينصرني من الله إن عصيته﴾؟","answer":"ينكر وجود من يحميه من الله إن عصاه إرضاءً لقومه، فيرد طلبهم إلى ميزان المسؤولية ويبين أن موافقتهم في الشرك خذلان لا نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص285، تحت «غرض الاستفهام البلاغي»","url":""}]},{"id":"s11-112","number":112,"surah":11,"verses":[64],"references":[{"surah":11,"verses":[64]}],"verseLabel":"هود: 64","question":"ما دلالة إضافة الناقة إلى الله في قوله: ﴿هذه ناقة الله﴾؟","answer":"إضافة تشريف وملكية خاصة؛ لأنها آية خلقها الله على وجه خارق وجعل لها حرمة، لا ملكًا عاديًا للبشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص294، تحت «دلالة التعريف بالإضافة»","url":""}]},{"id":"s11-219","number":219,"surah":11,"verses":[64],"references":[{"surah":11,"verses":[64]}],"verseLabel":"هود: 64","question":"ما دلالة إضافة الأرض إلى الله في قوله: ﴿تأكل في أرض الله﴾؟","answer":"تقرر أن الأرض لله لا لقوم صالح، فلا يملكون منع ناقته من رزق ساقه الله إليها في ملكه الواسع.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص298، تحت «بديع التعريف بإضافة ﴿أرض﴾ للفظ الجلالة»","url":""}]},{"id":"s11-114","number":114,"surah":11,"verses":[65],"references":[{"surah":11,"verses":[65]}],"verseLabel":"هود: 65","question":"ما غرض الأمر في قوله لقوم صالح: ﴿تمتعوا في داركم﴾؟","answer":"ليس إباحة مطمئنة، بل تهديد ووعيد بأن متاعهم قصير يعقبه العذاب المحتوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص307، تحت «غرض الأمر»","url":""}]},{"id":"s11-220","number":220,"surah":11,"verses":[65],"references":[{"surah":11,"verses":[65]}],"verseLabel":"هود: 65","question":"ما دلالة توقيت عذاب ثمود بثلاثة أيام؟","answer":"يجعل الوعيد قريبًا محسوسًا، فتتحول المهلة المحدودة إلى انتظار يملؤه الخوف والقلق ويقيم الحجة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص309، تحت «دلالة توقيت العذاب»","url":""}]},{"id":"s11-221","number":221,"surah":11,"verses":[65],"references":[{"surah":11,"verses":[65]}],"verseLabel":"هود: 65","question":"ما دلالة وصف الوعد بأنه ﴿غير مكذوب﴾؟","answer":"يؤكد أن الوعيد حق واقع لا خلف فيه ولا كذب، فيقطع طمعهم في النجاة بعد انتهاء المهلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص310، تحت «سر الوصف بقوله ﴿غير مكذوب﴾»","url":""}]},{"id":"s11-115","number":115,"surah":11,"verses":[66],"references":[{"surah":11,"verses":[66]}],"verseLabel":"هود: 66","question":"ما دلالة تنكير ﴿رحمة﴾ في قوله: ﴿برحمة منا﴾؟","answer":"يفخم الرحمة التي أحاطت بصالح والمؤمنين؛ فالنجاة فضل عظيم من الله لا استحقاق يلزمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص317، تحت «غرض تنكير ﴿رحمة﴾»","url":""}]},{"id":"s11-222","number":222,"surah":11,"verses":[66],"references":[{"surah":11,"verses":[66]}],"verseLabel":"هود: 66","question":"ما دلالة قوله في نجاة المؤمنين: ﴿ومن خزي يومئذ﴾؟","answer":"يبين أنهم نُجّوا من الذلة والهوان والفضيحة المشهودة مع نجاتهم من الهلاك، فحُفظت سلامتهم وكرامتهم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص318، تحت «دلالة التعبير بمفردة ﴿خزي﴾»","url":""}]},{"id":"s11-116","number":116,"surah":11,"verses":[67],"references":[{"surah":11,"verses":[67]}],"verseLabel":"هود: 67","question":"ما دلالة أخذ الظالمين بالصيحة؟","answer":"تصور الصيحة عذابًا مباغتًا شديدًا يقطع حركتهم دفعة واحدة ويبرز سرعة نزول العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص327، تحت «فائدة التعبير بالصيحة»","url":""}]},{"id":"s11-223","number":223,"surah":11,"verses":[67],"references":[{"surah":11,"verses":[67]}],"verseLabel":"هود: 67","question":"ما دلالة وصف ثمود بأنهم ﴿في ديارهم جاثمين﴾؟","answer":"يصوّر سكونهم التام وعجزهم عن الحركة والهرب بعد الصيحة، حتى صاروا أجسادًا لا حراك بها في مساكنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص329، تحت «سر التعبير بالجثوم»","url":""}]},{"id":"s11-117","number":117,"surah":11,"verses":[68],"references":[{"surah":11,"verses":[68]}],"verseLabel":"هود: 68","question":"ما وجه البلاغة في التعبير بقوله تعالى ﴿لم يغنوا فيها﴾؟","answer":"يصوّر زوالهم التام حتى كأنهم لم يقيموا وينعموا في تلك الديار قط؛ وهو انقلاب يبدد غرور الحضارة الراسخة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص330، تحت «بلاغة التعبير بقوله تعالى ﴿لم يغنوا فيها﴾»","url":""}]},{"id":"s11-118","number":118,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما سرّ اختيار المجيء في قوله: ﴿ولقد جاءت رسلنا إبراهيم﴾ دون الإرسال؟","answer":"يستحضر وصول الملائكة إلى إبراهيم ومشهد لقائهم به، مع أنهم مرسلون أصلًا إلى قوم لوط، فيقرب الحدث من الحس.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص337، تحت «سر اختيار لفظ المجيء دون الإرسال»","url":""}]},{"id":"s11-224","number":224,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما دلالة قول الله: ﴿جاءت رسلنا إبراهيم بالبشرى﴾؟","answer":"تصوّر الباء البشرى كأنها شيء تحمله الرسل وتجيء به إلى إبراهيم، فتقدم معنى السرور في مشهد اللقاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص338، تحت «بلاغة استعمال حرف الباء»","url":""}]},{"id":"s11-119","number":119,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما دلالة قوله في ضيافة إبراهيم: ﴿فما لبث أن جاء﴾؟","answer":"ينفي التباطؤ ليصور مبادرته وسرعة إكرامه للضيوف قبل أن يعرف حقيقتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص340، تحت «غرض النفي»","url":""}]},{"id":"s11-225","number":225,"surah":11,"verses":[69],"references":[{"surah":11,"verses":[69]}],"verseLabel":"هود: 69","question":"ما دلالة وصف العجل بأنه ﴿حنيذ﴾؟","answer":"يفيد أنه طعام مشوي مهيأ للضيف، فيصوّر جودة الضيافة وتمام كرم إبراهيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص341، تحت «فائدة التعبير بوصف ﴿حنيذ﴾»","url":""}]},{"id":"s11-120","number":120,"surah":11,"verses":[70],"references":[{"surah":11,"verses":[70]}],"verseLabel":"هود: 70","question":"ما دلالة التعبير عن امتناع الضيوف بقول الله: ﴿رأى أيديهم لا تصل إليه﴾؟","answer":"هو كناية حية عن تركهم الطعام، تعرض المشهد أمام القارئ بدل الاكتفاء بالإخبار أنهم لم يأكلوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص346، تحت «بلاغة التعبير بنفي وصول الأيدي إلى العجل»","url":""}]},{"id":"s11-226","number":226,"surah":11,"verses":[70],"references":[{"surah":11,"verses":[70]}],"verseLabel":"هود: 70","question":"ما دلالة عطف ﴿وأوجس منهم خيفة﴾ على ﴿نكرهم﴾؟","answer":"يصوّر تدرج أثر امتناعهم فيه: بدأ باستغراب حالهم ثم تحول إلى خوف أحسه في نفسه وأخفاه إكرامًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص347، تحت «بلاغة عطف الإيجاس على النكارة»","url":""}]},{"id":"s11-121","number":121,"surah":11,"verses":[71],"references":[{"surah":11,"verses":[71]}],"verseLabel":"هود: 71","question":"ما دلالة ذكر ضحك امرأة إبراهيم قبل بشارتها بإسحاق؟","answer":"يفيد زوال الخوف وعودة الطمأنينة، ثم جاءت البشارة عقب ذلك؛ فانتقل المشهد من الخيفة إلى السرور ثم إلى بشارة عظيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص352، تحت «دلالة ذكر الضحك»","url":""}]},{"id":"s11-122","number":122,"surah":11,"verses":[71],"references":[{"surah":11,"verses":[71]}],"verseLabel":"هود: 71","question":"ما سرّ التعبير بقوله تعالى: ﴿ومن وراء إسحاق يعقوب﴾؟","answer":"لم تقتصر البشرى على الولد مع الكبر، بل امتدت إلى الحفيد؛ فضمنت بقاء إسحاق حتى يولد له يعقوب وزادت الطمأنينة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص353، تحت «براعة التعبير بقوله «ومن وراء»»","url":""}]},{"id":"s11-123","number":123,"surah":11,"verses":[72],"references":[{"surah":11,"verses":[72]}],"verseLabel":"هود: 72","question":"ما دلالة جمع سارة بين قولها: ﴿وأنا عجوز﴾ وقولها: ﴿وهذا بعلي شيخًا﴾؟","answer":"سبب الاستبعاد في نظر العادة مركب من حالهما معًا، فجمعهما يصور شدة دهشتها البشرية أمام القدرة الإلهية.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص361، تحت «براعة اجتماع الحال»","url":""}]},{"id":"s11-124","number":124,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة استفهام الملائكة: ﴿أتعجبين من أمر الله﴾؟","answer":"ينكر استبعادها للخبر ويطمئنها؛ فبيت النبوة الذي عرف آيات الله ورحمته لا يستبعد في حقه خرق العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص368، تحت «غرض الاستفهام»","url":""}]},{"id":"s11-227","number":227,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة إيثار المضارع في قوله: ﴿أتعجبين﴾؟","answer":"يستحضر تعجبها في لحظته ويصوره متجددًا أمام السامع، فيجيء الإنكار والتطمين مباشرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص369، تحت «نكتة إيثار المضارع على الماضي»","url":""}]},{"id":"s11-228","number":228,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة إضافة الأمر إلى الله في قوله: ﴿من أمر الله﴾؟","answer":"ترد الأمر إلى القدرة الإلهية التي لا تقيدها أسباب العادة، فيزول وجه الاستبعاد مع العلم بأن البشارة من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص370، تحت «دلالة الإضافة»","url":""}]},{"id":"s11-125","number":125,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة مجيء قوله: ﴿رحمت الله وبركاته عليكم أهل البيت﴾ عقب إنكار تعجب سارة؟","answer":"يعلل زوال العجب بأن ما بُشرت به امتداد لرحمات وبركات عرفها هذا البيت النبوي، لا حادثًا بعيدًا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص370، تحت «براعة موقع الجمل من السابق»","url":""}]},{"id":"s11-229","number":229,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة تقديم الرحمة على البركة في خطاب أهل بيت إبراهيم؟","answer":"الرحمة أصل الإنعام والرعاية، والبركات آثارها المتكاثرة؛ فقدم الأصل ثم أتبع بما يتفرع عنه من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص371، تحت «فائدة تقديم الرحمة على البركة»","url":""}]},{"id":"s11-230","number":230,"surah":11,"verses":[73],"references":[{"surah":11,"verses":[73]}],"verseLabel":"هود: 73","question":"ما دلالة اجتماع وصفي ﴿حميد مجيد﴾ في ختام بشارة أهل بيت إبراهيم؟","answer":"يجمع الحمد على النعم والمجد الدال على سعة العظمة والكرم؛ فيناسب مقام الرحمة والبركة والبشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص375، تحت «بلاغة اجتماع وصفي ﴿حميد مجيد﴾»","url":""}]},{"id":"s11-126","number":126,"surah":11,"verses":[74],"references":[{"surah":11,"verses":[74]}],"verseLabel":"هود: 74","question":"ما دلالة التعبير عن مراجعة إبراهيم في قوم لوط بالمجادلة دون المحاورة؟","answer":"تفيد المجادلة شدة مراجعته رجاء تأخير العذاب لوجود مؤمنين أو إمهال القوم للتوبة، وكان دافعها حلمه ورحمته بعد زوال الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص386، تحت «دلالة استعمال مفردة المجادلة دون المحاورة»","url":""}]},{"id":"s11-127","number":127,"surah":11,"verses":[75],"references":[{"surah":11,"verses":[75]}],"verseLabel":"هود: 75","question":"ما دلالة وصف إبراهيم بأنه ﴿حليم أواه منيب﴾ في سياق مجادلته في قوم لوط؟","answer":"الحلم يفسر رفقه بالمعاندين، والأواه رقة قلبه، والإنابة رجوعه إلى الله؛ فترتيب الصفات يكشف منابع مجادلته الرحيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص391، تحت «بلاغة اجتماع الأوصاف وترتيبها»","url":""}]},{"id":"s11-128","number":128,"surah":11,"verses":[76],"references":[{"surah":11,"verses":[76]}],"verseLabel":"هود: 76","question":"لماذا قيل لإبراهيم: ﴿أعرض عن هذا﴾ بدل النهي عن الجدال؟","answer":"لأن الرحمة التي دفعته إلى المراجعة محمودة، وإنما طُلب منه أن يصرف نفسه عن أمر انتهى حكمه بعد قيام الحجة ومجيء أمر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص394، تحت «سر الأمر بالإعراض دون النهي عن الجدال»","url":""}]},{"id":"s11-231","number":231,"surah":11,"verses":[76],"references":[{"surah":11,"verses":[76]}],"verseLabel":"هود: 76","question":"ما دلالة وصف عذاب قوم لوط بأنه ﴿غير مردود﴾ في سياق مجادلة إبراهيم؟","answer":"يقطع الرجاء في دفعه بعد أن بلغ الحكم نهايته؛ فصار استمرار المجادلة بلا محل مهما كان باعثها الرحمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص399، تحت «نكتة وصف العذاب في سياق المجادلة»","url":""}]},{"id":"s11-129","number":129,"surah":11,"verses":[77],"references":[{"surah":11,"verses":[77]}],"verseLabel":"هود: 77","question":"ما دلالة عطف ﴿وضاق بهم ذرعًا﴾ على ﴿سيء بهم﴾؟","answer":"يجمع أثرين متتابعين: ساءه مجيئهم لما خشي عليهم، ثم ضاق بعجزه عن حمايتهم؛ فاجتمع ألم النفس وقلة الحيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص406، تحت «فائدة العطف»","url":""}]},{"id":"s11-232","number":232,"surah":11,"verses":[77],"references":[{"surah":11,"verses":[77]}],"verseLabel":"هود: 77","question":"ما الصورة التي يرسمها التعبير: ﴿وضاق بهم ذرعًا﴾؟","answer":"يمثل حال لوط وقد عجزت قدرته عن حمايتهم بحال من ضاق مدى ذراعه عن بلوغ ما يريد، فيصور شدة الحرج وقلة الحيلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص406، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s11-130","number":130,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما سرّ ذكر لوط النساء باسم البنات في قوله: ﴿هؤلاء بناتي﴾؟","answer":"دعا قومه إلى النساء بطريق الزواج المشروع، وقيل أراد نساء قومه لأن النبي في مقام الأب لهم؛ فصرفهم من الفاحشة إلى الحلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص420، تحت «فائدة ذكر النساء باسم البنات»","url":""}]},{"id":"s11-233","number":233,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما دلالة قوله: ﴿هن أطهر لكم﴾ مع أن الفاحشة لا طهارة فيها؟","answer":"ليس المراد مشاركة الطريقين في الطهر، بل بيان أن الزواج هو الطريق الطاهر وحده، فجاء اسم التفضيل للحث الشديد على العدول إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص424، تحت «نكتة مجيء اسم التفضيل مع انتفاء المفاضلة»","url":""}]},{"id":"s11-131","number":131,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما دلالة الاستفهام في قول لوط: ﴿أليس منكم رجل رشيد﴾؟","answer":"يستنكر خلو هذا الجمع ممن يردهم عن الفاحشة وفضيحة الضيف، ويوقظ ما بقي فيهم من فطرة وعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص428، تحت «غرض الاستفهام»","url":""}]},{"id":"s11-234","number":234,"surah":11,"verses":[78],"references":[{"surah":11,"verses":[78]}],"verseLabel":"هود: 78","question":"ما دلالة تنكير ﴿رجل﴾ ووصفه بـ﴿رشيد﴾ في قول لوط؟","answer":"يفيد أنه كان يطلب أي رجل، ولو واحدًا، يملك رشدًا يرده وقومه عن المنكر؛ وفي ذلك تصوير لشدة فساد الجماعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص429، تحت «غرض التنكير وسر الوصف»","url":""}]},{"id":"s11-132","number":132,"surah":11,"verses":[79],"references":[{"surah":11,"verses":[79]}],"verseLabel":"هود: 79","question":"ما دلالة التوكيد في قول قوم لوط: ﴿لقد علمت ما لنا في بناتك من حق﴾؟","answer":"يصرح بإصرارهم على رفض الحلال، ويزعمون أن مقصدهم معلوم لا يحتاج نقاشًا؛ فبلغت مجاهرتهم غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص429، تحت «غرض التوكيد»","url":""}]},{"id":"s11-235","number":235,"surah":11,"verses":[79],"references":[{"surah":11,"verses":[79]}],"verseLabel":"هود: 79","question":"ما دلالة قول قوم لوط: ﴿لقد علمت﴾ بدل الإخبار المباشر برفضهم؟","answer":"احتجوا بعلمه السابق بحالهم ليغلقوا باب المراجعة، كأن مقصدهم مقرر لا يخفى ولا يتغير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص430، تحت «دلالة استعمال لفظ العلم مادة وصيغة»","url":""}]},{"id":"s11-236","number":236,"surah":11,"verses":[79],"references":[{"surah":11,"verses":[79]}],"verseLabel":"هود: 79","question":"عمّ كنّى قوم لوط بقولهم: ﴿وإنك لتعلم ما نريد﴾؟","answer":"كنوا عن الفاحشة التي يقصدونها، لكن الكناية هنا لا تستر قبحهم بل تكشف مجاهرتهم بالمقصد حتى جعلوه معلومًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص431، تحت «بلاغة الكناية»","url":""}]},{"id":"s11-133","number":133,"surah":11,"verses":[80],"references":[{"surah":11,"verses":[80]}],"verseLabel":"هود: 80","question":"ما سرّ تمني لوط قوة أو ركنًا شديدًا؟","answer":"نطق بها في لحظة استضعاف طلبًا لوسيلة تحمي ضيوفه، مع أن ركنه الحقيقي كان الله؛ ولذلك كشفت الملائكة فورًا أنهم رسل ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص433–436، تحت «غرض استعمال «لو»؛ فائدة التقديم والتأخير؛ بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s11-134","number":134,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما سرّ التعبير بـ﴿بقطع من الليل﴾ في أمر لوط بالخروج بأهله؟","answer":"الليل أستر للخروج وأبعد عن ملاحقة القوم، والقطع جزء منه؛ فالتعبير يرسم نجاة خفية قبل حلول الصبح.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص449، تحت «بلاغة التعبير «بقطع من الليل» دون «في الليل»»","url":""}]},{"id":"s11-135","number":135,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما دلالة النهي في قوله تعالى: ﴿ولا يلتفت منكم أحد﴾؟","answer":"ليقطعوا صلتهم النفسية والمكانية ببلد العذاب، ويمضوا إلى النجاة بلا تباطؤ أو تحسر على ما تركوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص450، تحت «غرض النهي»","url":""}]},{"id":"s11-136","number":136,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما سرّ إيثار لفظ ﴿الصبح﴾ على الفجر في تحديد موعد عذاب قوم لوط؟","answer":"الصبح زمن انكشاف الضوء ووضوح الأشياء، فناسب ظهور العذاب وتمام النجاة، وفيه تطمين بأن الموعد قد دنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص454، تحت «سر إيثار الصبح على الفجر»","url":""}]},{"id":"s11-237","number":237,"surah":11,"verses":[81],"references":[{"surah":11,"verses":[81]}],"verseLabel":"هود: 81","question":"ما دلالة الاستفهام في قوله: ﴿أليس الصبح بقريب﴾؟","answer":"يقرر قرب الموعد ويطمئن لوطًا بأن الخلاص قد دنا، وقد يحمل كذلك على الحث على الإسراع في الخروج.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص455، تحت «غرض الاستفهام»","url":""}]},{"id":"s11-137","number":137,"surah":11,"verses":[82],"references":[{"surah":11,"verses":[82]}],"verseLabel":"هود: 82","question":"ما دلالة التعبير بالجعل في قوله: ﴿جعلنا عاليها سافلها﴾؟","answer":"يصوّر تحويلًا حقيقيًا تامًا لحال القرى، ويبرز قدرة الله على قلب نظامها الذي استقر عليه أهلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص462، تحت «سر التعبير بالجعل»","url":""}]},{"id":"s11-238","number":238,"surah":11,"verses":[82],"references":[{"surah":11,"verses":[82]}],"verseLabel":"هود: 82","question":"ما دلالة التعبير بـ﴿عاليها﴾ و﴿سافلها﴾ في عذاب قوم لوط؟","answer":"يرسم انقلاب القرى من أعلاها إلى أسفلها، ويهوّل الإهانة إذ صارت مواضع استقرارهم مقلوبة عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص463، تحت «نكتة التعبير بـ﴿عاليها﴾ و﴿سافلها﴾»","url":""}]},{"id":"s11-138","number":138,"surah":11,"verses":[82],"references":[{"surah":11,"verses":[82]}],"verseLabel":"هود: 82","question":"ما دلالة وصف الحجارة بأنها ﴿من سجيل منضود﴾؟","answer":"يبرز «سجيل»، على تفسيره الذي رجحه المصدر، صلابة الحجارة وشدتها، فهي من طين تحجر فاشتد. ويصور «منضود» كثرتها وإعدادها وتتابع بعضها إثر بعض، فيكتمل به تصوير هول العذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص467–468، تحت «إيثار لفظ «سجيل» في وصف الحجارة؛ دلالة وصف «سجيل» بـ«منضود»»","url":""}]},{"id":"s11-139","number":139,"surah":11,"verses":[83],"references":[{"surah":11,"verses":[83]}],"verseLabel":"هود: 83","question":"ما سرّ التعبير بـ«مسومة»، وما دلالة الكناية في «مسومة»، وما دلالة التعبير بالظرفية «عند»؟","answer":"أي معلَّمة أو مقدرة لمستحقيها، فتبدو العقوبة دقيقة لا عشوائية؛ كل حجر يجري بعلم وتقدير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص468–469، تحت «سر التعبير بـ«مسومة»؛ دلالة الكناية في «مسومة»؛ دلالة التعبير بالظرفية «عند»»","url":""}]},{"id":"s11-140","number":140,"surah":11,"verses":[83],"references":[{"surah":11,"verses":[83]}],"verseLabel":"هود: 83","question":"ما دلالة ختم قصة لوط بقوله تعالى: ﴿وما هي من الظالمين ببعيد﴾؟","answer":"يحول القصة إلى تهديد دائم لكل من يشابههم في الظلم؛ فالعبرة ليست محصورة في قوم مضوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص471–472، 474، تحت «نكتة التعبير بالإضمار في «وما هي»؛ علة اختيار وصف الظالمين؛ دلالة ختام قصة لوط»","url":""}]},{"id":"s11-141","number":141,"surah":11,"verses":[84],"references":[{"surah":11,"verses":[84]}],"verseLabel":"هود: 84","question":"ما سرّ التعبير في قوله تعالى في شعيب: ﴿أخاهم شعيبًا﴾؟","answer":"يكرر قرب الرسول من قومه ومعرفته بأحوالهم، فلا عذر لهم بدعوى الغربة؛ وقد واجه فساد عبادتهم ومعاملاتهم معًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص481–482، 487، تحت «سر التعبير بالأخوة في «أخاهم»؛ دلالة الإضافة في «أخاهم»؛ أسلوب القرآن في عرض أصول دعوة شعيب»","url":""}]},{"id":"s11-142","number":142,"surah":11,"verses":[84],"references":[{"surah":11,"verses":[84]}],"verseLabel":"هود: 84","question":"ما دلالة الجمع بين التوحيد والنهي عن نقص المكيال والميزان في دعوة شعيب؟","answer":"يبين أن الدين لا ينفصل عن السوق؛ فمن عبد الله لزمه العدل في أموال الناس، وإلا ناقضت معاملته عقيدته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص487، تحت «أسلوب القرآن في عرض أصول دعوة شعيب»","url":""}]},{"id":"s11-143","number":143,"surah":11,"verses":[84],"references":[{"surah":11,"verses":[84]}],"verseLabel":"هود: 84","question":"ما سرّ التعبير في قوله تعالى: ﴿إني أراكم بخير﴾ ثم خوّفهم العذاب؟","answer":"كانوا في سعة تغنيهم عن الغش، فصار التطفيف أشد قبحًا؛ كما أن الخير القائم قد يزول بعذاب محيط إن كفروا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص491–494، تحت «دلالة الفصل في «إني أراكم بخير»؛ سر التعبير بـ«خير»؛ بلاغة الإجمال في «عذاب يوم محيط»»","url":""}]},{"id":"s11-144","number":144,"surah":11,"verses":[85],"references":[{"surah":11,"verses":[85]}],"verseLabel":"هود: 85","question":"لماذا أُمر قوم شعيب بإيفاء المكيال والميزان بعد نهيهم عن النقص؟","answer":"لأن ترك النقص لا يكفي حتى يتحول إلى أداء إيجابي كامل للحقوق؛ فجمع السياق بين إزالة الظلم وإقامة العدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص500، تحت «علة الأمر بالإيفاء بعد النهي عن النقص»","url":""}]},{"id":"s11-239","number":239,"surah":11,"verses":[85],"references":[{"surah":11,"verses":[85]}],"verseLabel":"هود: 85","question":"ما دلالة تقييد إيفاء المكيال والميزان بـ﴿القسط﴾؟","answer":"يبين أن المطلوب إتمام الحقوق على وجه العدل والتسوية، لا مجرد زيادة ظاهرية أو وفاء يخالطه ميل وجور.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص501، تحت «دلالة لفظ القسط»","url":""}]},{"id":"s11-145","number":145,"surah":11,"verses":[85],"references":[{"surah":11,"verses":[85]}],"verseLabel":"هود: 85","question":"ما سرّ التعبير بـ«ولا تعثوا»، وما سرّ التعبير بالاسمية «مفسدين»، وما وجه البلاغة في التأكيد في «ولا تعثوا في الأرض مفسدين»؟","answer":"العثو فساد شديد منتشر، والحال ﴿مفسدين﴾ تكشف أن حركتهم في الأرض تحولت إلى صناعة فساد لا خطأ عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص504–505، 507، تحت «سر التعبير بـ«ولا تعثوا»؛ سر التعبير بالاسمية «مفسدين»؛ بلاغة التأكيد في «ولا تعثوا في الأرض مفسدين»»","url":""}]},{"id":"s11-146","number":146,"surah":11,"verses":[86],"references":[{"surah":11,"verses":[86]}],"verseLabel":"هود: 86","question":"ما دلالة التعبير بـ﴿بقية الله﴾ في قوله تعالى: ﴿بقية الله خير لكم﴾؟","answer":"ما يبقيه الله لكم من الربح الحلال بعد ترك التطفيف خير من الزيادة المحرمة، ويدخل فيه ثواب الطاعة الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص514–516، تحت «سر التعبير بلفظ «بقية»؛ دلالة الإضافة «بقية الله»؛ دلالة التعبير بقوله «خير»»","url":""}]},{"id":"s11-148","number":148,"surah":11,"verses":[87],"references":[{"surah":11,"verses":[87]}],"verseLabel":"هود: 87","question":"ما دلالة قول قوم شعيب: ﴿أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء﴾؟","answer":"ساقوا السؤال للسخرية من شعيب وصلاته، واعترضوا على دعوته في أصلين: ترك عبادة الآباء، وترك التصرف الظالم في المال. وإسناد الأمر إلى الصلاة يربط عبادته بما يدعو إليه؛ فقد كانت عنوان إيمانه وتقواه ودافعًا إلى إصلاح الاعتقاد والمعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص524–525، 529–531، تحت «دلالة الاستفهام في «أصلاتك»؛ سر اختيارهم للصلاة؛ بلاغة المجاز العقلي في «أصلاتك تأمرك»؛ سر الجمع بين عدم الترك وحرية التصرف»","url":""}]},{"id":"s11-149","number":149,"surah":11,"verses":[87],"references":[{"surah":11,"verses":[87]}],"verseLabel":"هود: 87","question":"ما دلالة وصف قوم شعيب له بقولهم: ﴿إنك لأنت الحليم الرشيد﴾؟","answer":"يحتمل التهكم وإرادة الضد، ويحتمل اعترافهم بما عرفوه من حلمه ورشده ثم احتجاجهم بهما عليه؛ وفي الوجهين تكشف العبارة اعتراضهم لا حجة تبطل دعوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص532، تحت «علة الوصف بـ﴿الحليم الرشيد﴾»","url":""}]},{"id":"s11-150","number":150,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة النفي في قول شعيب: ﴿وما أريد أن أخالفكم إلى ما أنهاكم عنه﴾؟","answer":"يعلن اتساق قوله وعمله وينفي أصل قصده إلى فعل ما ينهى عنه؛ فمصداقية المصلح تبدأ من نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص550، تحت «بلاغة أسلوب النفي»","url":""}]},{"id":"s11-240","number":240,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة اختيار فعل ﴿أخالفكم﴾ في كلام شعيب؟","answer":"يصور أن يفعل المصلح من وراء قومه ما نهاهم عنه كأنه يتجه إلى الجهة المخالفة لهم؛ فنفى عن نفسه ازدواج القول والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص551، تحت «سر اختيار فعل ﴿أخالفكم﴾»","url":""}]},{"id":"s11-151","number":151,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة القصر في قول شعيب: ﴿إن أريد إلا الإصلاح﴾؟","answer":"حصر قصده في الإصلاح، فنفى عن دعوته كل غرض شخصي وأثبت أنه لا يريد إلا صلاح قومه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص553، تحت «دلالة أسلوب القصر»","url":""}]},{"id":"s11-241","number":241,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"لماذا قيّد شعيب إرادته الإصلاح بقوله: ﴿ما استطعت﴾؟","answer":"اعترافًا بحدود القدرة البشرية وتواضعًا؛ فهو يبذل ما يقدر عليه ولا يدعي إصلاحًا يتجاوز استطاعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص555، تحت «سر التعبير بالاستطاعة»","url":""}]},{"id":"s11-242","number":242,"surah":11,"verses":[88],"references":[{"surah":11,"verses":[88]}],"verseLabel":"هود: 88","question":"ما دلالة قول شعيب: ﴿وما توفيقي إلا بالله﴾؟","answer":"احتراس من توهم استقلاله بقدرته؛ فالنية والسعي منه، أما إصابة الحق وتمام الأثر فبتوفيق الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص556، تحت «بلاغة الاحتراس في «وما توفيقي إلا بالله»»","url":""}]},{"id":"s11-152","number":152,"surah":11,"verses":[89],"references":[{"surah":11,"verses":[89]}],"verseLabel":"هود: 89","question":"كيف يُوجَّه بلاغيًا التعبير بقوله «لا يجرمنكم»، وما الغرض البلاغي من النهي وبلاغة مجازه، وما معنى الإضافة ودلالتها؟","answer":"المعنى: لا تجعلوا عداوتكم لي سببًا للإعراض عن الدعوة والإصرار على الباطل، فيصيبكم مثل ما أصاب الأمم المكذبة. وصوّر الشقاق كأنه يكسبهم العذاب، تنبيهًا إلى أن خصومتهم للرسول تضرهم هم بعاقبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص565–567، تحت «توجيه التعبير بقوله «لا يجرمنكم»؛ غرض النهي وبلاغة مجازه؛ معنى الإضافة ودلالتها»","url":""}]},{"id":"s11-153","number":153,"surah":11,"verses":[89],"references":[{"surah":11,"verses":[89]}],"verseLabel":"هود: 89","question":"ما دلالة ختم تعداد الأمم بقوله تعالى: ﴿وما قوم لوط منكم ببعيد﴾؟","answer":"لأنهم قريبون زمانًا أو مكانًا ومعرفةً، وآثارهم أمامهم؛ فالحجة الأقرب أشد إيقاظًا من أخبار بعيدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص573، تحت «نكتة التعبير «ببعيد»»","url":""}]},{"id":"s11-154","number":154,"surah":11,"verses":[90],"references":[{"surah":11,"verses":[90]}],"verseLabel":"هود: 90","question":"ما سرّ التعبير في قوله تعالى: ﴿إن ربي رحيم ودود﴾ بعد الاستغفار والتوبة؟","answer":"جمع الوصفان سعة الرحمة والمغفرة مع المحبة والإحسان إلى التائب. فجاء الختام تعليلًا للدعوة إلى الاستغفار والتوبة، وترغيبًا فيها، حتى لا يحملهم ما سبق من ذنوبهم على اليأس من قبول الله ورحمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص582، تحت «الجمع بين وصفي «رحيم ودود»»","url":""}]},{"id":"s11-155","number":155,"surah":11,"verses":[91],"references":[{"surah":11,"verses":[91]}],"verseLabel":"هود: 91","question":"ما سرّ تعبير قوم شعيب بـ﴿ما نفقه كثيرًا مما تقول﴾ بدلًا من «لا نفهم»؟","answer":"الفقه فهم عميق يأتي بعد تأمل؛ فاختياره يزيد التعريض بكلام شعيب، وكأنهم يدّعون أنه لا يستحق هذا النظر أو لا يفهم مع إعماله. ولم يكن كلامه غامضًا؛ وإنما كشف النفي عن إعراضهم وعدم تصديقهم، ثم أسندوه إلى جماعتهم لتقوية الاعتراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص588، 596، تحت «دلالة النفي بـ«ما»؛ نكتة إسناد نفي الفقه للجميع؛ الفقه والفهم»","url":""}]},{"id":"s11-156","number":156,"surah":11,"verses":[91],"references":[{"surah":11,"verses":[91]}],"verseLabel":"هود: 91","question":"ما دلالة قول قوم شعيب: ﴿ولولا رهطك لرجمناك﴾؟","answer":"صرحوا بأن المانع من رجمه مراعاة قرابته الباقين على دينهم. ولفظ «رهطك» يدل على قلة هذه الجماعة؛ فلم يكن امتناعهم إقرارًا بحقه أو احترامًا لدعوته، بل إكرامًا لرهطه الموافقين لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص591–592، 596، تحت «سر التعبير بـ«لولا»؛ سر التعبير بالرهط دون القوم؛ بلاغة التذييل»","url":""}]},{"id":"s11-157","number":157,"surah":11,"verses":[92],"references":[{"surah":11,"verses":[92]}],"verseLabel":"هود: 92","question":"ما سرّ التعبير في قول شعيب: ﴿أرهطي أعز عليكم من الله﴾؟","answer":"فضح انقلاب ميزانهم: راعوا رهطه الضعيف ولم يراعوا الله القادر، فجعلوا حرمة القبيلة فوق حرمة الرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص603، تحت «غرض التعبير بصيغة المفاضلة «أعز»»","url":""}]},{"id":"s11-158","number":158,"surah":11,"verses":[92],"references":[{"surah":11,"verses":[92]}],"verseLabel":"هود: 92","question":"ما دلالة ﴿واتخذتموه وراءكم ظهريًا﴾؟","answer":"كناية عن الإهمال والنبذ؛ صوّرتهم كمن يطرح أمر الله خلف ظهره فلا يلتفت إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص605، تحت «بلاغة الكناية»","url":""}]},{"id":"s11-243","number":243,"surah":11,"verses":[92],"references":[{"surah":11,"verses":[92]}],"verseLabel":"هود: 92","question":"ما دلالة وصف الله بأنه ﴿بما تعملون محيط﴾؟","answer":"يدل على إحاطة علمه وقدرته بأعمالهم إحاطة لا يفلت منها شيء، وفيه وعيد لمن نبذ أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص608، تحت «قوله تعالى «محيط» بين المجاز والاستعارة»","url":""}]},{"id":"s11-160","number":160,"surah":11,"verses":[94],"references":[{"surah":11,"verses":[94]}],"verseLabel":"هود: 94","question":"ما وجه البلاغة في التعبير المجازي بالرحمة في قوله تعالى: ﴿نجينا شعيبًا والذين آمنوا معه برحمة منا﴾؟","answer":"نسب النجاة إلى رحمة الله لا إلى الاستحقاق المجرد، ليظل المؤمن شاكرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص634، تحت «بلاغة التعبير المجازي بالرحمة»","url":""}]},{"id":"s11-244","number":244,"surah":11,"verses":[94],"references":[{"surah":11,"verses":[94]}],"verseLabel":"هود: 94","question":"ما النكتة البلاغية في إسناد فعل الأخذ للصيحة في قوله تعالى: ﴿وأخذت الذين ظلموا الصيحة﴾؟","answer":"صوّر الصيحة كقوة استولت عليهم وأحاطت بهم فلم يستطيعوا منها فرارًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص635، تحت «نكتة إسناد فعل الأخذ للصيحة»","url":""}]},{"id":"s11-161","number":161,"surah":11,"verses":[95],"references":[{"surah":11,"verses":[95]}],"verseLabel":"هود: 95","question":"ما دلالة تكرار ﴿كأن لم يغنوا فيها﴾ في ختام قصتي ثمود ومدين؟","answer":"تلتقي العبارتان في تصوير الاستئصال: زال القوم حتى صاروا كأنهم لم يقيموا في ديارهم ولم ينعموا بعيشها. فالتشبيه يجمع المصيرين في صورة واحدة، ويجعل ما عرفوه من عمران ورخاء شاهدًا على شدة ما نزل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص330، تحت «بلاغة التشبيه»","url":""}]},{"id":"s11-162","number":162,"surah":11,"verses":[96],"references":[{"surah":11,"verses":[96]}],"verseLabel":"هود: 96","question":"لماذا عبّر عن معجزات موسى بلفظ ﴿آياتنا﴾؟","answer":"لأنها علامات بينات تدل على صدقه وقدرة مرسلها، فلا تقف دلالتها عند خرق العادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص649، تحت «سر التعبير بالآيات دون المعجزات»","url":""}]},{"id":"s11-245","number":245,"surah":11,"verses":[96],"references":[{"surah":11,"verses":[96]}],"verseLabel":"هود: 96","question":"ما سر وصف حجة موسى بأنها ﴿سلطان مبين﴾؟","answer":"لأن الحجة الواضحة تتسلط على الباطل وتظهر عليه، فيبرز اللفظ قوتها وقهرها للشبهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص651، تحت «سر التعبير بالسلطان عن الحجة»","url":""}]},{"id":"s11-163","number":163,"surah":11,"verses":[97],"references":[{"surah":11,"verses":[97]}],"verseLabel":"هود: 97","question":"ما دلالة قوله عن قوم فرعون: ﴿فاتبعوا أمر فرعون﴾؟","answer":"يصوّر انقيادهم لقيادته مع وضوح آيات موسى، فيحمّلهم تبعة اختيار طريق الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص654، تحت «دلالة ذكر لفظ الاتباع»","url":""}]},{"id":"s11-246","number":246,"surah":11,"verses":[97],"references":[{"surah":11,"verses":[97]}],"verseLabel":"هود: 97","question":"لماذا قال: ﴿وما أمر فرعون برشيد﴾ بدل التصريح بسفهه؟","answer":"نفي الرشد يوبخ من اتبعوه؛ فقد تبعوا أمرًا لا يقود إلى صلاح أو نجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص656، تحت «سر نفي الرشد دون إثبات السفه»","url":""}]},{"id":"s11-164","number":164,"surah":11,"verses":[98],"references":[{"surah":11,"verses":[98]}],"verseLabel":"هود: 98","question":"ما سرّ التعبير في قوله تعالى عن فرعون: ﴿يقدم قومه يوم القيامة فأوردهم النار﴾؟","answer":"كما قادهم في الدنيا إلى الضلال يتقدمهم في الآخرة إلى نتيجته؛ فقلب صورة الزعيم الذي يوصل قومه إلى الموارد إلى قائد يوردهم النار.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص662–663، 665–666، تحت «نكتة إيثار لفظ «يقدم»؛ نكتة إيثار صيغة المضارع؛ بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s11-165","number":165,"surah":11,"verses":[99],"references":[{"surah":11,"verses":[99]}],"verseLabel":"هود: 99","question":"ما سرّ تسمية اللعنة ﴿رفدًا﴾ في قوله تعالى: ﴿بئس الرفد المرفود﴾؟","answer":"الرفد عادة عطاء ومعونة، فاستعمل تهكمًا: عطاؤهم المتتابع لعنة في الدنيا ثم لعنة في الآخرة، وبئس العطاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص675، تحت «بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s11-166","number":166,"surah":11,"verses":[100],"references":[{"surah":11,"verses":[100]}],"verseLabel":"هود: 100","question":"ما سرّ التعبير في قوله تعالى عن القرى: ﴿منها قائم وحصيد﴾؟","answer":"شبه آثارها بزرع: منه ما بقي قائمًا يراه الناس، ومنه ما استؤصل كالحصيد؛ وفي الحالتين تشهد البقايا أو الفراغ بالمصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص683، تحت «بلاغة الاستعارة التصريحية»","url":""}]},{"id":"s11-167","number":167,"surah":11,"verses":[101],"references":[{"surah":11,"verses":[101]}],"verseLabel":"هود: 101","question":"ما وجه البلاغة في العموم في قوله تعالى: ﴿فما أغنت عنهم آلهتهم... من شيء﴾؟","answer":"عمّم نفي النفع، فلا تدفع آلهتهم عنهم قليلًا من العذاب ولا كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص689، تحت «بلاغة العموم»","url":""}]},{"id":"s11-247","number":247,"surah":11,"verses":[101],"references":[{"surah":11,"verses":[101]}],"verseLabel":"هود: 101","question":"كيف يُوجَّه بلاغيًا استعمال «تتبيب» في سياقها؟","answer":"زادهم تعلقهم بآلهتهم خسارًا وهلاكًا؛ لأن رجاء نصرتها صدّهم عن التوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص691، تحت «توجيه استعمال «تتبيب» في سياقها»","url":""}]},{"id":"s11-168","number":168,"surah":11,"verses":[102],"references":[{"surah":11,"verses":[102]}],"verseLabel":"هود: 102","question":"ما الغرض البلاغي من التشبيه في الآية في قوله تعالى: ﴿وكذلك أخذ ربك إذا أخذ القرى وهي ظالمة﴾؟","answer":"شبّه أخذ كل قرية ظالمة بما قصه من أخذ الأمم، ليعمم العبرة ويؤكد ثبات سنة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص696، تحت «غرض التشبيه في الآية»","url":""}]},{"id":"s11-248","number":248,"surah":11,"verses":[102],"references":[{"surah":11,"verses":[102]}],"verseLabel":"هود: 102","question":"ما دلالة الجمع بين ﴿أليم﴾ و﴿شديد﴾؟","answer":"الأليم يبرز وجع العذاب، والشديد يبرز قوته وصعوبة الخلاص منه؛ فاجتماعهما أبلغ في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص699، تحت «نكتة الجمع بين صفتي الألم والشدة»","url":""}]},{"id":"s11-169","number":169,"surah":11,"verses":[103],"references":[{"surah":11,"verses":[103]}],"verseLabel":"هود: 103","question":"ما سرّ إيثار لفظ الخوف في قوله تعالى: ﴿إن في ذلك لآية لمن خاف عذاب الآخرة﴾؟","answer":"المنتفع بالتاريخ هو من يرى وراء هلاك الدنيا حسابًا أكبر؛ أما من لا يخاف الآخرة فقد يشاهد الآثار ولا يعتبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص705، تحت «سر إيثار لفظ الخوف»","url":""}]},{"id":"s11-170","number":170,"surah":11,"verses":[103],"references":[{"surah":11,"verses":[103]}],"verseLabel":"هود: 103","question":"ما دلالة وصف يوم القيامة بأنه ﴿يوم مجموع له الناس﴾ و﴿يوم مشهود﴾؟","answer":"«مجموع له الناس» يؤكد ثبوت جمع الخلائق لأجل الحساب، و«مشهود» يبرز كثرة من يحضرون هذا الموقف وهوله. فتجتمع في الوصفين حتمية الجمع وعظمة المشهد الذي لا يغيب عنه أحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص708، تحت «دلالة استعمال صيغة المفعول»","url":""}]},{"id":"s11-171","number":171,"surah":11,"verses":[104],"references":[{"surah":11,"verses":[104]}],"verseLabel":"هود: 104","question":"ما النكتة البلاغية في إيثار لفظ «معدود»؟","answer":"يبين القصر أن تأخير القيامة إنما هو إلى وقت معلوم حدده الله، فلا يصح اتخاذ التأخير دليلًا على نفي البعث. ووصف الأجل بأنه «معدود» يؤكد ضبط مدته وانتهاءها بلا زيادة ولا نقصان.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص710، تحت «نكتة إيثار لفظ «معدود»»","url":""}]},{"id":"s11-172","number":172,"surah":11,"verses":[105],"references":[{"surah":11,"verses":[105]}],"verseLabel":"هود: 105","question":"ما فائدة الاستئناف في قوله «لا تكلم»، وما سرّ تنكير «نفس»، وكيف يُوجَّه بلاغيًا الاستثناء؟","answer":"يسقط كل وهم في الاحتجاج أو الشفاعة المستقلة؛ حتى الكلام في ذلك الموقف خاضع لسلطان الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص716–718، تحت «فائدة الاستئناف في قوله «لا تكلم»؛ سر تنكير «نفس»؛ توجيه الاستثناء»","url":""}]},{"id":"s11-173","number":173,"surah":11,"verses":[105],"references":[{"surah":11,"verses":[105]}],"verseLabel":"هود: 105","question":"ما دلالة تقسيم الناس إلى ﴿شقي وسعيد﴾ قبل تفصيل حال الفريقين؟","answer":"لخّص المصير النهائي بعد انقضاء زمن العمل: فريق بلغ الشقاء وفريق نال السعادة، ثم فصل حال كل منهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص723، تحت «بديع التقسيم»","url":""}]},{"id":"s11-174","number":174,"surah":11,"verses":[106],"references":[{"surah":11,"verses":[106]}],"verseLabel":"هود: 106","question":"ما دلالة وصف أهل النار بأن لهم فيها ﴿زفير وشهيق﴾؟","answer":"يصوّر ذكر الزفير والشهيق شدة الكرب واضطراب التنفس من الألم. والجمع بين إخراج النفس وإدخاله يبرز استمرار الحياة مع العذاب، ويجعل المشهد أوقع في التحذير وأشد تنفيرًا من أسبابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص725، تحت «توجيه تخصيص الزفير والشهيق بالذكر»","url":""}]},{"id":"s11-176","number":176,"surah":11,"verses":[108],"references":[{"surah":11,"verses":[108]}],"verseLabel":"هود: 108","question":"ما دلالة ختم نعيم الجنة بقوله تعالى: ﴿عطاء غير مجذوذ﴾؟","answer":"﴿غير مجذوذ﴾ أي غير مقطوع؛ فجاءت العبارة لتزيل أي توهم يولده الاستثناء السابق في انقطاع نعيمهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص733، تحت «إيثار لفظ «مجذوذ» دون لفظ مقطوع»","url":""}]},{"id":"s11-177","number":177,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما فائدة النهي عن الامتراء في قوله تعالى: ﴿فلا تك في مرية مما يعبد هؤلاء﴾؟","answer":"ليس نهيًا عن الشك في وقوع عبادتهم، بل عن الارتياب في بطلانها ومصيرها؛ فهم يقلدون آباءهم وسينالون نصيبهم كاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص739، تحت «فائدة النهي عن الامتراء»","url":""}]},{"id":"s11-178","number":178,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما دلالة كثرة المؤكدات في قوله: ﴿وإنا لموفوهم نصيبهم غير منقوص﴾؟","answer":"تقطع الشك في وقوع الجزاء كاملًا، وتبين أن تأخيره لا يعني سقوطه أو نقصه.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص748، تحت «بلاغة حشد المؤكدات في الآية»","url":""}]},{"id":"s11-249","number":249,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما وجه التهكم في تسمية عذابهم ﴿نصيبهم﴾؟","answer":"سُمّي العذاب نصيبًا كأنه عطاء ينتظرونه، تهكمًا بهم وإيذانًا بأن لهم منه حظًا مقررًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص749، تحت «أسلوب التهكم»","url":""}]},{"id":"s11-250","number":250,"surah":11,"verses":[109],"references":[{"surah":11,"verses":[109]}],"verseLabel":"هود: 109","question":"ما دلالة قوله عن نصيبهم: ﴿غير منقوص﴾؟","answer":"ينفي كل احتمال لنقص الجزاء، فيبلغ كل واحد ما استحقه كاملًا من غير بخس.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص750، تحت «علة التعبير بـ«منقوص»»","url":""}]},{"id":"s11-179","number":179,"surah":11,"verses":[110],"references":[{"surah":11,"verses":[110]}],"verseLabel":"هود: 110","question":"لماذا صرّح باسم موسى في قوله: ﴿ولقد آتينا موسى الكتاب فاختلف فيه﴾؟","answer":"استحضار قصته يسلي النبي ﷺ بأن الاختلاف في الوحي سنة قديمة لقيها رسول قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص756، تحت «وجه إظهار اسم موسى»","url":""}]},{"id":"s11-251","number":251,"surah":11,"verses":[110],"references":[{"surah":11,"verses":[110]}],"verseLabel":"هود: 110","question":"ما فائدة التعبير بـ«لولا»؟","answer":"يبين أن تأخير الفصل ليس إقرارًا للباطل، بل تنفيذ لكلمة سبقت بإمهالهم إلى الأجل.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص757، تحت «فائدة التعبير بـ«لولا»»","url":""}]},{"id":"s11-180","number":180,"surah":11,"verses":[111],"references":[{"surah":11,"verses":[111]}],"verseLabel":"هود: 111","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن كلًا لما ليوفينهم ربك أعمالهم﴾ بهذا التوكيد المتراكم؟","answer":"كثرة أدوات التوكيد تزيل الشك في شمول الجزاء لكل مختلف، وأن أعمالهم محفوظة لا يغيب منها شيء عن الخبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص766، تحت «بلاغة اجتماع المؤكدات»","url":""}]},{"id":"s11-181","number":181,"surah":11,"verses":[112],"references":[{"surah":11,"verses":[112]}],"verseLabel":"هود: 112","question":"ما دلالة تقييد الاستقامة بقوله تعالى: ﴿كما أمرت﴾، وما وجه شدة هذا التكليف؟","answer":"يطلب التعبير دوام الاستقامة مطابقةً لأمر الله في الاعتقاد والعمل والأخلاق، من غير إفراط ولا تفريط. ويشمل الأمر من تاب مع النبي، ثم يتبعه النهي عن الطغيان؛ فشدة التكليف في دقة الوفاء بهذا المنهج كله والثبات عليه مع ما يلقونه من أذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص777، تحت «بلاغة التشبيه بالكاف»","url":""}]},{"id":"s11-182","number":182,"surah":11,"verses":[112],"references":[{"surah":11,"verses":[112]}],"verseLabel":"هود: 112","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تطغوا﴾ بعد الأمر بالاستقامة؟","answer":"الاستقامة وسط بين التقصير ومجاوزة الحد؛ فحتى الحماسة للحق لا تبرر تعدي ما أمر الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص780، تحت «إيثار لفظ الطغيان دون غيره»","url":""}]},{"id":"s11-183","number":183,"surah":11,"verses":[113],"references":[{"surah":11,"verses":[113]}],"verseLabel":"هود: 113","question":"ما دلالة النهي عن الركون إلى الذين ظلموا؟","answer":"الركون ميل وسكون إلى الظالمين، ومنه الرضا بظلمهم وتحسين طريقهم. والنهي عن هذا الميل يمنع ما يفضي إلى مشاركتهم؛ فإذا ورد الوعيد على الركون، كانت المشاركة في الظلم أشد دخولًا في التحذير.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص787، تحت «إيثار لفظ الركون»","url":""}]},{"id":"s11-184","number":184,"surah":11,"verses":[113],"references":[{"surah":11,"verses":[113]}],"verseLabel":"هود: 113","question":"ما دلالة إيثار لفظ المس وبلاغة المجاز فيه في قوله تعالى: ﴿فتمسكم النار﴾؟","answer":"المس يوحي بأن أدنى اتصال بالنار كاف في التحذير، وهو مناسب للنهي عن أدنى ميل إلى الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص790، تحت «إيثار لفظ المس وبلاغة المجاز فيه»","url":""}]},{"id":"s11-185","number":185,"surah":11,"verses":[114],"references":[{"surah":11,"verses":[114]}],"verseLabel":"هود: 114","question":"ما دلالة التعبير عن أوقات الصلاة بـ﴿طرفي النهار﴾؟","answer":"يجمع أول النهار وآخره ليحيط اليوم بمحطتي ذكر متقابلتين تعينان على الاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص799، تحت «فائدة التعبير بالطرف وتثنيته»","url":""}]},{"id":"s11-252","number":252,"surah":11,"verses":[114],"references":[{"surah":11,"verses":[114]}],"verseLabel":"هود: 114","question":"ما دلالة إيثار لفظ الزلف في السياق في قوله تعالى: ﴿وزلفًا من الليل﴾؟","answer":"الزلف ساعات الليل القريبة، فاختير اللفظ لأوقات متقاربة تتكرر فيها الصلة بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص800، تحت «إيثار لفظ الزلف في السياق»","url":""}]},{"id":"s11-186","number":186,"surah":11,"verses":[114],"references":[{"surah":11,"verses":[114]}],"verseLabel":"هود: 114","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الحسنات يذهبن السيئات﴾ بعد الأمر بالصلاة؟","answer":"جاءت الجملة تعليلًا للأمر بالصلاة وترغيبًا في الحسنات، والصلاة في مقدمتها. والتعبير بالإذهاب يصوّر أثر الطاعة في محو السيئة، كما يشمل تهيئة النفس لتركها؛ فتقاوم الحسنات الذنب وتعين على دوام الاستقامة.","sources":[{"label":"موسوعة التفسير البلاغي، ج21، ص802، تحت «سر التعبير بقوله «يذهبن السيئات»»","url":""}]},{"id":"s11-187","number":187,"surah":11,"verses":[115],"references":[{"surah":11,"verses":[115]}],"verseLabel":"هود: 115","question":"ما مناسبة الأمر بالصبر بعد الأمر بالاستقامة؟","answer":"لأن الثبات على الطاعة واجتناب الطغيان والركون يحتاج إلى صبر على المشقة والأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص11، تحت «مناسبة وقوع الأمر بالصبر عقب الاستقامة»","url":""}]},{"id":"s11-253","number":253,"surah":11,"verses":[115],"references":[{"surah":11,"verses":[115]}],"verseLabel":"هود: 115","question":"لماذا قال: ﴿لا يضيع أجر المحسنين﴾ بدل «أجركم»؟","answer":"ليبين أن الصبر والامتثال من الإحسان، وليعم الوعد كل من أحسن عمله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص13، تحت «فائدة العدول من المضمر إلى المظهر»","url":""}]},{"id":"s11-188","number":188,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"ما دلالة ﴿فلولا كان من القرون من قبلكم﴾؟","answer":"جاءت ﴿لولا﴾ للتحضيض بمعنى هلا، وخرجت إلى توبيخ الأمم على ترك مقاومة الفساد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص17، تحت «دلالة لولا على التحضيض»","url":""}]},{"id":"s11-254","number":254,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"لماذا وصف الناهين عن الفساد بأنهم ﴿أولو بقية﴾؟","answer":"لأن البقية ما يُستبقى لنفاسته، فكانت كناية عن أصحاب الفضل والعقل والخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص19، تحت «إيثار لفظ البقية ودلالته»","url":""}]},{"id":"s11-189","number":189,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"ما دلالة استثناء ﴿قليلًا ممن أنجينا منهم﴾ بعد ذكر غياب الناهين عن الفساد؟","answer":"يستدرك الاستثناء ذكر الفئة القليلة التي نهت عن الفساد فأنجاها الله، فلا يوهم الكلام السابق خلو جميع القرون من المصلحين. وفي وصفهم بالقلة إبراز لندرتهم بالنسبة إلى أقوامهم، مع بيان أثر موقفهم في النجاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص20، تحت «توجيه الاستثناء»","url":""}]},{"id":"s11-190","number":190,"surah":11,"verses":[116],"references":[{"surah":11,"verses":[116]}],"verseLabel":"هود: 116","question":"ما دلالة إيثار لفظ الإتراف دون غيره في قوله تعالى: ﴿واتبع الذين ظلموا ما أترفوا فيه﴾؟","answer":"يصور الاتباع انقيادهم لما تنعموا به من الشهوات حتى أعرضوا عن النهي عن الفساد. ولفظ الإتراف يدل على مجاوزة حد الاعتدال في التنعم على وجه يورث البطر والطغيان، ثم جاء وصفهم بالإجرام ليكشف عاقبة هذا المسلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص23، تحت «إيثار لفظ الإتراف دون غيره»","url":""}]},{"id":"s11-191","number":191,"surah":11,"verses":[117],"references":[{"surah":11,"verses":[117]}],"verseLabel":"هود: 117","question":"ما النكتة البلاغية في النفي بـ«وما كان»، وما دلالة حرف الباء، وما دلالة الواو في «وأهلها مصلحون»، وكيف يُوجَّه بلاغيًا الحالية في جملة الفاصلة؟","answer":"ينفي أن يهلكهم ظلمًا منه وهم قائمون بالإصلاح؛ فالهلاك العام لا يأتي مع حياة الإصلاح، وإنما حين يستحكم فساد الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص26–29، تحت «نكتة النفي بـ«وما كان»؛ دلالة حرف الباء؛ دلالة الواو في «وأهلها مصلحون»؛ توجيه الحالية في جملة الفاصلة»","url":""}]},{"id":"s11-192","number":192,"surah":11,"verses":[118],"references":[{"surah":11,"verses":[118]}],"verseLabel":"هود: 118","question":"ما دلالة قوله تعالى: ﴿ولو شاء ربك لجعل الناس أمة واحدة﴾ في سياق اختلافهم؟","answer":"شاء أن يكون التكليف والابتلاء في مجال الاختيار، فتظهر الاستجابة والإعراض؛ ولو شاء قسرهم على طريق واحد لفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص35–38، 50، تحت «معنى لو في قوله «ولو شاء ربك»؛ نكتة التعبير بالجملة الشرطية في الآية؛ معنى أل في الناس؛ فائدة الخبر «ولذلك خلقهم»»","url":""}]},{"id":"s11-193","number":193,"surah":11,"verses":[118],"references":[{"surah":11,"verses":[118]}],"verseLabel":"هود: 118","question":"ما فائدة الخبر «ولا يزالون مختلفين»، وما النكتة البلاغية في المضارع في «ولا يزالون»، وما النكتة البلاغية في حذف متعلق «مختلفين»، وما وجه البلاغة في القصر في الآية الكريمة؟","answer":"يصور استمرار الاختلاف ما دام الاختيار والهوى، لا أنه غاية محمودة في ذاته؛ ثم استثنى من رحمهم الله بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص40–45، تحت «فائدة الخبر «ولا يزالون مختلفين»؛ نكتة المضارع في «ولا يزالون»؛ نكتة حذف متعلق «مختلفين»؛ بلاغة القصر في الآية الكريمة»","url":""}]},{"id":"s11-194","number":194,"surah":11,"verses":[119],"references":[{"surah":11,"verses":[119]}],"verseLabel":"هود: 119","question":"ما دلالة الإشارة في قوله تعالى: ﴿ولذلك خلقهم﴾: أإلى الاختلاف تعود أم إلى الرحمة؟","answer":"ذكر المصدر ثلاثة أوجه لعود الإشارة: الاختلاف، أو الرحمة، أو مجموعهما. فعلى عودها إلى الاختلاف أو مجموعهما قد تكون اللام للعاقبة، أو يفسر الاختلاف بما جُبل عليه الناس من تفاوت واختيار؛ وعلى عودها إلى الرحمة تكون للتعليل. فلا يصح اختزال هذه الأوجه في الجزم بأن الكفر غاية محبوبة؛ والسياق يبين الاختيار وعاقبته ورحمة الله بالمهتدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص35، 46–50، تحت «معنى الواو في «ولذلك»؛ معنى اللام في قوله «ولذلك»؛ مرجع اسم الإشارة؛ دلالة التعبير باسم الإشارة «ذلك»؛ فائدة الخبر»","url":""}]},{"id":"s11-195","number":195,"surah":11,"verses":[119],"references":[{"surah":11,"verses":[119]}],"verseLabel":"هود: 119","question":"ما وجه البلاغة في العطف في قوله «وتمت كلمة ربك»، وما وجه البلاغة في المجاز، وما فائدة توالي المؤكدات في قوله «لأملأن»، وما معنى من في «من الجنة»، وما فائدة التوكيد بـ«أجمعين»؟","answer":"يقرر نفاذ الحكم فيمن اختار طريق الشقاء من الصنفين؛ فلا يعطل اختلافهم وعد الله ولا يخرجهم عن سلطانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص50–57، تحت «بلاغة العطف في قوله «وتمت كلمة ربك»؛ بلاغة المجاز؛ فائدة توالي المؤكدات في قوله «لأملأن»؛ معنى من في «من الجنة»؛ فائدة التوكيد بـ«أجمعين»»","url":""}]},{"id":"s11-196","number":196,"surah":11,"verses":[120],"references":[{"surah":11,"verses":[120]}],"verseLabel":"هود: 120","question":"ما النكتة البلاغية في تقديم المفعول «كلا»، وما معنى ما في «ما نثبت» وإعرابها، وما دلالة التعبير بالمضارع ونون العظمة في «نثبت»، وما وجه البلاغة في الاستعارة؟","answer":"القصص لم تسق للاستمتاع التاريخي، بل كل خبر منها يمد القلب بدليل ثبات جديد أمام تكرر التكذيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص66–67، 71–73، تحت «نكتة تقديم المفعول «كلا»؛ معنى ما في «ما نثبت» وإعرابها؛ دلالة التعبير بالمضارع ونون العظمة في «نثبت»؛ بلاغة الاستعارة»","url":""}]},{"id":"s11-197","number":197,"surah":11,"verses":[120],"references":[{"surah":11,"verses":[120]}],"verseLabel":"هود: 120","question":"ما الغرض البلاغي من العطف في قوله «وجاءك»، وما سرّ التخصيص بالحق في الآية، وما دلالة التعبير بـ«موعظة»، وما فائدة تقديم الموعظة على الذكرى؟","answer":"خص هذه السورة بما جمعته من حقائق القصص المطمئنة، وموعظة تزجر، وذكرى تجدد ما يعرفه المؤمن؛ فتنوع أثر الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص74–80، تحت «غرض العطف في قوله «وجاءك»؛ سر التخصيص بالحق في الآية؛ دلالة التعبير بـ«موعظة»؛ فائدة تقديم الموعظة على الذكرى»","url":""}]},{"id":"s11-198","number":198,"surah":11,"verses":[121],"references":[{"surah":11,"verses":[121]}],"verseLabel":"هود: 121","question":"ما سرّ توجيه الخطاب إلى المكذبين بقوله تعالى: ﴿اعملوا على مكانتكم إنا عاملون﴾؟","answer":"أمر تهديد لا إباحة: استمروا على طريقكم وسنستمر على الحق، وستكشف النهاية قيمة كل عمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص87–91، تحت «دلالة الأمر في قوله «اعملوا»؛ سر اختيار مادة العمل؛ نكتة التعدية في قوله «على مكانتكم»؛ نكتة فصل قوله تعالى «إنا عاملون»»","url":""}]},{"id":"s11-199","number":199,"surah":11,"verses":[122],"references":[{"surah":11,"verses":[122]}],"verseLabel":"هود: 122","question":"ما دلالة المقابلة في قوله تعالى: ﴿وانتظروا إنا منتظرون﴾؟","answer":"قابل انتظارهم سقوط الدعوة بانتظار المؤمنين حكم الله؛ والتكرار يصور المواجهة ويثبت أن العاقبة ستفصل بين الانتظارين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص95، تحت «بلاغة المقابلة في الآية»","url":""}]},{"id":"s11-200","number":200,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما دلالة تقديم ﴿لله﴾ في قوله: ﴿ولله غيب السماوات والأرض﴾؟","answer":"يفيد اختصاص الله بعلم الغيب كله، فلا يملك أحد سر المستقبل استقلالًا عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص100، تحت «نكتة التقديم في «ولله غيب»»","url":""}]},{"id":"s11-255","number":255,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما فائدة توكيد الأمر بـ«كله»؟","answer":"يرد التدبير والنتائج جميعًا إلى الله وحده، فلا يخرج شيء عن حكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص106، تحت «فائدة توكيد الأمر بـ«كله»»","url":""}]},{"id":"s11-201","number":201,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما دلالة الجمع بين العبادة والتوكل في ختام السورة: ﴿فاعبده وتوكل عليه﴾؟","answer":"يجمع الختام امتثال أمر الله مع الاعتماد عليه؛ فالعبادة عمل وطاعة، والتوكل ثقة بالله وتفويض الأمر إليه مع الأخذ بالأسباب. وتقديم العبادة يؤكد أن التوكل يصحب العمل، وباجتماعهما يثبت الرسول والمؤمنون على دعوتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص99، 107–109، تحت «دلالة الأمر في قوله «فاعبده وتوكل»؛ نكتة عطف التوكل في الآية؛ نكتة تقديم الأمر بالعبادة في الآية»","url":""}]},{"id":"s11-202","number":202,"surah":11,"verses":[123],"references":[{"surah":11,"verses":[123]}],"verseLabel":"هود: 123","question":"ما دلالة ختم سورة هود بقوله تعالى: ﴿وما ربك بغافل عما تعملون﴾؟","answer":"تختم بالرقابة الشاملة: لا يضيع عمل الداعية ولا يغيب ظلم المكذب، وفيها وعد ووعيد يلخصان مسار السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص114، تحت «بلاغة التذييل في آخر الآية»","url":""}]},{"id":"s11-256","number":256,"surah":11,"verses":[13],"references":[{"surah":11,"verses":[13]}],"verseLabel":"هود: 13","question":"ما دلالة قوله: ﴿فأتوا بعشر سور مثله مفتريات﴾، دون «مِن مثله» كما في البقرة؟","answer":"لما قالوا: ﴿افتراه﴾ قيل لهم: ﴿مثله مفتريات﴾، أي افتروا أنتم كما تزعمون أنه افترى. ولا يحسُن هنا «مِن مثله»؛ لأنها تفترض أن له مثلًا موجودًا، وما له مثل لا يكون مفترى. وفي البقرة لم يقولوا «افتراه» فجاء «مِن مثله».","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص8–10.","url":""}]},{"id":"s11-257","number":257,"surah":11,"verses":[35],"references":[{"surah":11,"verses":[35]}],"verseLabel":"هود: 35","question":"ما سر نسبة الإجرام إليهم في قوله: ﴿فعليّ إجرامي وأنا بريء مما تجرمون﴾، وفي سبأ: ﴿ولا نُسأل عما تعملون﴾؟","answer":"في آية هود نسبوا الافتراء إليه: ﴿أم يقولون افتراه﴾، فقال: إن افتريته فعليّ عقوبة إجرامي، وأنا بريء من إجرامكم في نسبة ذلك إليّ، فقابل الإجرام بالإجرام.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص63.","url":""}]},{"id":"s11-258","number":258,"surah":11,"verses":[40],"references":[{"surah":11,"verses":[40]}],"verseLabel":"هود: 40","question":"ما سر زيادة ﴿ومَن آمن﴾ وترك ﴿منهم﴾ في قوله: ﴿وأهلَك إلا من سبق عليه القول ومن آمن﴾، خلافًا لسورة المؤمنون؟","answer":"القصة في هود مبنية على العموم، وفي المؤمنون على الخصوص: فزاد في هود مَن آمن على الأهل، ونفى العاصم نفيًا عامًّا: ﴿لا عاصم اليوم من أمر الله﴾، وذكر البركات بالجمع عليه وعلى أمم ممن معه. ويبيّن أيضًا أن ﴿أهلَك﴾ اسم بمعنى الأهل، وليس فعلًا ماضيًا.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص88–90.","url":""}]},{"id":"s11-259","number":259,"surah":11,"verses":[54],"references":[{"surah":11,"verses":[54]}],"verseLabel":"هود: 54","question":"ما سر حذف الباء في قول هود: ﴿واشهدوا أني بريء مما تشركون﴾، وذكرها في آل عمران: ﴿اشهدوا بأنّا مسلمون﴾؟","answer":"الذكر أقوى وآكد من الحذف، وما ذكره الرسول ﷺ في آل عمران أكثر مما قاله هود؛ فهناك: ألا نعبد إلا الله، ولا نشرك به شيئًا، ولا يتخذ بعضنا بعضًا أربابًا، فناسب الموضعَ الأكثرَ التعبيرُ الآكد بذكر الباء.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص33–34.","url":""}]},{"id":"s11-260","number":260,"surah":11,"verses":[66],"references":[{"surah":11,"verses":[66]}],"verseLabel":"هود: 66","question":"ما سر التوكيد بـ«إنّ» وضمير الفصل في قوله: ﴿إن ربك هو القوي العزيز﴾، وتركه في الشورى: ﴿وهو القوي العزيز﴾؟","answer":"المقام في هود مقام عقوبة للكافرين ونصر للمؤمنين، أما في الشورى فمقام لطفه بالعباد ورزقه من يشاء، فأكّد القوة والعزة في المقام الذي يقتضيهما. ويلاحظ أن اسمه «القوي» لا يُقرن إلا بـ«العزيز» أو بـ«شديد العقاب».","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص25 وص79.","url":""}]},{"id":"s11-261","number":261,"surah":11,"verses":[72],"references":[{"surah":11,"verses":[72]}],"verseLabel":"هود: 72","question":"ما دلالة قول امرأة إبراهيم: ﴿يا ويلتى﴾، دون «يا ويلي»؟","answer":"«الويلة» هي الفضيحة والخزي، فالمعنى: يا للفضيحة، لأنها رأت أن تلد وهي عجوز وبعلها شيخ. ومثله قول المجرمين حين يرون فضائحهم في الكتاب: ﴿يا ويلتنا مال هذا الكتاب﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص131.","url":""}]},{"id":"s11-262","number":262,"surah":11,"verses":[72],"references":[{"surah":11,"verses":[72]}],"verseLabel":"هود: 72","question":"ما سر التوكيد بـ«إنّ» واللام في قولها: ﴿إن هذا لشيء عجيب﴾، وفي ق: ﴿هذا شيء عجيب﴾؟","answer":"تدرّج التعبير بحسب قوة العجب. ففي ق عجبوا من مجيء منذر منهم فلم يؤكد. أما في هود فالعجب أكبر، لأن امرأة عجوزًا عقيمًا بعلها شيخ تلد، فأُكّد بـ«إنّ» واللام. وفي ص بلغ العجب غايته فقال: ﴿لشيء عُجاب﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص36.","url":""}]},{"id":"s11-263","number":263,"surah":11,"verses":[77],"references":[{"surah":11,"verses":[77]}],"verseLabel":"هود: 77","question":"ما سر ترك «أن» بعد «لمّا» في قوله: ﴿ولما جاءت رسلنا لوطًا سيء بهم﴾، وذكرها في العنكبوت: ﴿ولما أن جاءت﴾؟","answer":"أفاض في العنكبوت في ذكر صفات قوم لوط السيئة، وفي دعائه بالنصر، وفي التصريح بالتنجية مرتين، فزاد «أن» مراعاة للتبسط وللدلالة على استطالة الوقت وطول الترقب. وليس ذلك في هود، إذ لم يزد على قوله: ﴿ومن قبل كانوا يعملون السيئات﴾.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص108–109.","url":""}]},{"id":"s11-264","number":264,"surah":11,"verses":[105,108],"references":[{"surah":11,"verses":[105,108]}],"verseLabel":"هود: 105، 108","question":"ما سر تقديم الأشقياء في قوله: ﴿فمنهم شقي وسعيد﴾، وجريان التفصيل على النسق نفسه؟","answer":"السياق في هود في ذكر الأمم الكافرة وما نزل بهم من العقوبات، وعقّب بـ﴿ذلك من أنباء القرى﴾، فقدّم الأشقياء. وجرى التفصيل على نسق الإجمال لأنهم كلهم غائبون، بخلاف آل عمران التي فيها مخاطَب وغائب.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص37–39.","url":""}]},{"id":"s11-265","number":265,"surah":11,"verses":[108],"references":[{"surah":11,"verses":[108]}],"verseLabel":"هود: 108","question":"ما معنى الاستثناء في قوله: ﴿خالدين فيها ما دامت السماوات والأرض إلا ما شاء ربك﴾، وهل يعني خروج أهل الجنة منها؟","answer":"أهل الجنة خالدون فيها أبدًا كما أخبر الله في مواطن عدة. ويذكر السامرائي أقوالًا في الاستثناء: منها أنه مدة الموقف قبل الحساب، أو مدة البرزخ، أو مرورهم على الجسر تحلّةً للقسم، أو فيمن يدخل النار من عصاة المسلمين ثم يخرج.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج2، ص65.","url":""}]},{"id":"s11-266","number":266,"surah":11,"verses":[2],"references":[{"surah":11,"verses":[2]}],"verseLabel":"هود: 2","question":"ما سر تقديم الإنذار على التبشير في قوله: ﴿إنني لكم منه نذير وبشير﴾، وعكسه في الأحزاب: ﴿شاهدًا ومبشرًا ونذيرًا﴾؟","answer":"الكلام في مطلع هود موجّه إلى الكافرين، وكرّر وصف الإنذار فقال: ﴿إنما أنت نذير﴾، وجوّ السورة تشيع فيه عقوبات الأمم البائدة، فناسب تقديم الإنذار. أما آية الأحزاب فالكلام فيها موجّه إلى المؤمنين، فقدّم التبشير.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص137–138.","url":""}]},{"id":"s11-267","number":267,"surah":11,"verses":[9],"references":[{"surah":11,"verses":[9]}],"verseLabel":"هود: 9","question":"ما سر تقديم ﴿منّا﴾ على ﴿رحمة﴾ في قوله: ﴿ولئن أذقنا الإنسان منّا رحمة﴾، وتأخيره في فصلت: ﴿ولئن أذقناه رحمة منّا﴾؟","answer":"إذا كان الكلام على الله قُدّم ما يدل عليه، وإذا كان الكلام على الرحمة قُدّمت. ومطلع هود كله في الكلام على الله: عبادته واستغفاره والمرجع إليه وعلمه بما يُسرّون ورزقه لكل دابة وخلقه السماوات، فقدّم ﴿منّا﴾.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص127–128.","url":""}]},{"id":"s11-268","number":268,"surah":11,"verses":[9],"references":[{"surah":11,"verses":[9]}],"verseLabel":"هود: 9","question":"ما دلالة وصف الإنسان بـ«كفور» في قوله: ﴿إنه ليؤوس كفور﴾؟","answer":"جاء وصف الإنسان بالكفور في كثير من الآيات على معنى كأنه مخلوق من هذا الوصف. أما «كفّار» فهي لمن يفعل الفعل وقتًا بعد وقت، ولم يُوصف بها الإنسان إلا في آية إبراهيم الواردة في سياق النعم المتجددة التي لا تُحصى.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص37–38.","url":""}]},{"id":"s11-269","number":269,"surah":11,"verses":[20],"references":[{"surah":11,"verses":[20]}],"verseLabel":"هود: 20","question":"ما سر التعبير بالماضي في قوله: ﴿أولئك لم يكونوا معجزين في الأرض وما كان لهم من دون الله من أولياء﴾، وبالخطاب في الشورى: ﴿وما أنتم بمعجزين﴾؟","answer":"الكلام في هود في الآخرة: ﴿أولئك يُعرضون على ربهم﴾، وهو يدور على أحداث ماضية كانت في الدنيا، فاقتضى الفعل الماضي. أما الخطاب في الشورى ففي الدنيا للحاضرين.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص87.","url":""}]},{"id":"s11-270","number":270,"surah":11,"verses":[22],"references":[{"surah":11,"verses":[22]}],"verseLabel":"هود: 22","question":"ما سر التعبير باسم التفضيل والتوكيد بـ«لا جرم» في قوله: ﴿لا جرم أنهم في الآخرة هم الأخسرون﴾، وفي النحل: ﴿هم الخاسرون﴾؟","answer":"آية هود فيمن صدّوا عن سبيل الله وصدّوا غيرهم، وافتروا على الله الكذب، وضُوعف لهم العذاب، فكانوا أخسر ممن صدّ ولم يصدّ غيره، فجيء لهم باسم التفضيل وأُكّد الخسران بـ«لا جرم» و«أنّ». ويذكر معه ما في «البرهان» للكرماني.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص159 وص235؛ ومن أسرار البيان القرآني، ص88.","url":""}]},{"id":"s11-271","number":271,"surah":11,"verses":[29],"references":[{"surah":11,"verses":[29]}],"verseLabel":"هود: 29","question":"ما سر قول نوح: ﴿لا أسألكم عليه مالًا﴾، وفي سائر المواضع «من أجر»؟","answer":"وقعت بعدها كلمة «الخزائن» في قوله: ﴿ولا أقول لكم عندي خزائن الله﴾، ولفظ المال بالخزائن أليق، بخلاف المواضع الأخرى التي جاء فيها «الأجر».","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص179.","url":""}]},{"id":"s11-283","number":283,"surah":11,"verses":[37],"references":[{"surah":11,"verses":[37]}],"verseLabel":"هود: 37","question":"ما سر الإخبار بالصيغة الاسمية ﴿إِنَّهُمْ مُغْرَقُونَ﴾ بدل «سيُغرَقون»؟","answer":"لم يقل: «سأغرقهم» أو «إنهم سيغرقون»، بل أخرجه مخرج الأمر الثابت بالصيغة الاسمية، للدلالة على أن الأمر حاصل لا محالة كأنه استقر وانتهى، وإن لم يقع بعد.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص21.","url":""}]},{"id":"s11-272","number":272,"surah":11,"verses":[39,93],"references":[{"surah":11,"verses":[39,93]}],"verseLabel":"هود: 39، 93","question":"ما سر ذكر الفاء في قول نوح: ﴿فسوف تعلمون من يأتيه عذاب يخزيه﴾، وتركها في قول شعيب: ﴿سوف تعلمون﴾؟","answer":"التهديد على لسان نوح أشد، فقد توعّدهم بأنه سيسخر منهم كما يسخرون، وزاد: ﴿ويحلّ عليه عذاب مقيم﴾، فلما زاد في التهديد زاد الفاء. ولم يزد شعيب على ذكر العذاب المخزي. ويذكر معه ما في «كشف المعاني» في مواضع مشابهة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص93.","url":""}]},{"id":"s11-273","number":273,"surah":11,"verses":[47],"references":[{"surah":11,"verses":[47]}],"verseLabel":"هود: 47","question":"ما سر ترك التوكيد في قول نوح: ﴿وإلا تغفر لي وترحمني أكن من الخاسرين﴾، وقد أُكّد في قول آدم وبني إسرائيل في الأعراف؟","answer":"التوكيد يتناسب وقدر المعصية. فسؤال نوح ليس معصية، بل فهم أن ابنه يدخل في الناجين، فلم يؤكده. وفعل آدم معصية فأُكّد بالنون، وفعل بني إسرائيل كفر وضلال فأُكّد بالنون واللام الموطئة.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص16 وص167.","url":""}]},{"id":"s11-274","number":274,"surah":11,"verses":[55],"references":[{"surah":11,"verses":[55]}],"verseLabel":"هود: 55","question":"ما سر ذكر الياء و«جميعًا» و«ثمّ» في قوله: ﴿فكيدوني جميعًا ثم لا تُنظِرون﴾، وفي الأعراف: ﴿ثم كيدونِ فلا تُنظِرون﴾؟","answer":"المقام في هود مقام تحدٍّ كبير، إذ قالوا إن بعض آلهتهم اعتراه بسوء، فتحدّى جميعهم وأظهر نفسه بذكر الياء. وأدخل «ثمّ» على الإنظار لأن سياق هود في الإمهال، كقوله: ﴿يمتّعكم متاعًا حسنًا إلى أجل مسمّى﴾، بخلاف الأعراف التي سياقها تعجيل العقوبات.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص82–86.","url":""}]},{"id":"s11-275","number":275,"surah":11,"verses":[60,99],"references":[{"surah":11,"verses":[60,99]}],"verseLabel":"هود: 60، 99","question":"ما سر ذكر «الدنيا» في عاد: ﴿وأُتبعوا في هذه الدنيا لعنة﴾، وتركها في قوم فرعون: ﴿وأُتبعوا في هذه لعنة﴾؟","answer":"قصة عاد في السورة إحدى عشرة آية، وقصة فرعون أربع آيات، فناسب ذكر الدنيا مقامَ الإطالة وحذفها مقامَ الإيجاز. وذكر في قصة عاد أمورًا تتعلق بالدنيا كإرسال السماء مدرارًا وزيادة القوة، وذكر في قصة فرعون أمرًا يتعلق بيوم القيامة: ﴿يقدُم قومه يوم القيامة﴾.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص90–92.","url":""}]},{"id":"s11-276","number":276,"surah":11,"verses":[64],"references":[{"surah":11,"verses":[64]}],"verseLabel":"هود: 64","question":"ما سر وصف العذاب بالقرب في قول صالح: ﴿فيأخذكم عذاب قريب﴾، وبالأليم في الأعراف؟","answer":"ذكر في الأعراف أنهم أعلنوا كفرهم وعتوا عن أمر ربهم وتحدّوه، فاستحقوا ذكر العذاب الأليم. أما في هود فلم يصرّحوا بكفرهم بل ذكروا أنهم في شك، ووُصف العذاب بالقرب لما ذُكر بعده: ﴿تمتّعوا في داركم ثلاثة أيام﴾. ويذكر معه ما في «البرهان» للكرماني.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص239–240.","url":""}]},{"id":"s11-277","number":277,"surah":11,"verses":[67,94],"references":[{"surah":11,"verses":[67,94]}],"verseLabel":"هود: 67، 94","question":"ما سر تذكير الفعل في قوم صالح: ﴿وأخذ الذين ظلموا الصيحة﴾، وتأنيثه في قوم شعيب: ﴿وأخذت الذين ظلموا الصيحة﴾؟","answer":"ينقل السامرائي عن «درة التنزيل» أن عذاب مدين ذُكر بألفاظ مؤنثة (الرجفة والصيحة والظلة) فغُلّب التأنيث، ثم يردّه بأن الظلة أصابت أصحاب الأيكة لا مدين، وأن الرجفة أخذت قوم صالح أيضًا. ويرى أنه عبّر عن عذاب قوم صالح بالخزي المذكر: ﴿ومن خزي يومئذ﴾، وأن التعقيب عليهم أشد، فناسبهم التذكير.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص92–94.","url":""}]},{"id":"s11-278","number":278,"surah":11,"verses":[75],"references":[{"surah":11,"verses":[75]}],"verseLabel":"هود: 75","question":"ما سر زيادة ﴿مُنيب﴾ في وصف إبراهيم: ﴿إن إبراهيم لحليم أوّاه منيب﴾، وفي التوبة: ﴿لأوّاه حليم﴾؟","answer":"فصّل في هود قصة إبراهيم مع الملائكة ومجادلته في قوم لوط، فزاد في وصفه. أما التوبة فلم يذكر فيها عنه إلا آية واحدة في استغفاره لأبيه، فأوجز.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص107.","url":""}]},{"id":"s11-279","number":279,"surah":11,"verses":[82,83],"references":[{"surah":11,"verses":[82,83]}],"verseLabel":"هود: 82–83","question":"ما سر وصف الحجارة بـ﴿منضود﴾ وجعل الإمطار ﴿عليها﴾ في هود، وفي الحجر: ﴿وأمطرنا عليهم حجارة من سجيل﴾؟","answer":"لما زاد في هود في وصف الحجارة: ﴿مسوّمة عند ربك وما هي من الظالمين ببعيد﴾، زاد الوصف بـ﴿منضود﴾، أي موضوع بعضه فوق بعض، دلالةً على الكثرة لأنها لعموم الظالمين. وجعل الإمطار في الحجر على القوم لأن الكلام عليهم هناك أشد، وفي هود على المدينة.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص108–109.","url":""}]},{"id":"s11-280","number":280,"surah":11,"verses":[94],"references":[{"surah":11,"verses":[94]}],"verseLabel":"هود: 94","question":"ما سر جمع الديار ووصفهم بالظلم في قوله: ﴿وأخذت الذين ظلموا الصيحة فأصبحوا في ديارهم جاثمين﴾، وفي الأعراف: ﴿فأخذتهم الرجفة فأصبحوا في دارهم﴾؟","answer":"ذكر في الأعراف من صفات قوم شعيب أشدّ مما في هود، فوصفهم بالكفر وذكر الرجفة وهي أشدّ. ووصفهم في هود بالظلم وهو أعم، وذكر الصيحة التي يبلغ مداها أبعد من الرجفة، فناسب ذلك جمع الديار.","sources":[{"label":"فاضل السامرائي، من أسرار البيان القرآني، ص304–306؛ والتعبير القرآني، ص47.","url":""}]},{"id":"s11-281","number":281,"surah":11,"verses":[110],"references":[{"surah":11,"verses":[110]}],"verseLabel":"هود: 110","question":"ما سر ترك ﴿إلى أجل مسمّى﴾ في قوله: ﴿ولولا كلمة سبقت من ربك لقُضي بينهم﴾، وذكره في الشورى؟","answer":"آية هود في أمة واحدة اختلفت في كتاب موسى: ﴿ولقد آتينا موسى الكتاب فاختُلف فيه﴾، والقضاء بينهم يمكن أن يكون عاجلًا أو آجلًا. أما آية الشورى ففي أمم مختلفة أكثرها هالك، فلا يُقضى بينهم إلا في الآخرة.","sources":[{"label":"فاضل السامرائي، أسئلة بيانية في القرآن الكريم، ج1، ص82–83.","url":""}]},{"id":"s11-282","number":282,"surah":11,"verses":[117],"references":[{"surah":11,"verses":[117]}],"verseLabel":"هود: 117","question":"ما سر التعبير بالفعل والختم بـ﴿مصلحون﴾ في قوله: ﴿وما كان ربك ليهلك القرى بظلم وأهلها مصلحون﴾، وفي الأنعام: ﴿مُهلِك القرى بظلم وأهلها غافلون﴾؟","answer":"آية الأنعام في مشهد من القيامة عما كان في الدنيا فجاءت بالاسم، وهنا جاء بلام الجحود مع المضارع للدلالة على الاستمرار والتجدد. والأنعام في سياق الرسل والإنذار فناسبها ﴿غافلون﴾، وأما هود فتقدّمها ﴿فلولا كان من القرون من قبلكم أولو بقية ينهون عن الفساد في الأرض﴾، ونقيض الفساد الصلاح، فخُتمت ب﴿مصلحون﴾. وينقل هذا التوجيه عن غيره بإحالة في الحاشية.","sources":[{"label":"فاضل السامرائي، التعبير القرآني، ص24–25 وص238–239.","url":""}]},{"id":"s12-1","number":1,"surah":12,"verses":[1],"references":[{"surah":12,"verses":[1]}],"verseLabel":"يوسف: 1","question":"ما دلالة افتتاح سورة يوسف بالحروف ﴿الر﴾ ثم ذكر الكتاب المبين؟","answer":"من الأوجه المذكورة في تفسير الحروف المقطعة أنها تنبّه إلى إعجاز القرآن: فهو مؤلف من الحروف التي يعرفها العرب، ومع ذلك يعجزون عن الإتيان بمثله. وعلى هذا الوجه يناسب أن يعقبها ذكر آيات الكتاب المبين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص129–130، تحت «المعنى الإجمالي»","url":""}]},{"id":"s12-2","number":2,"surah":12,"verses":[1],"references":[{"surah":12,"verses":[1]}],"verseLabel":"يوسف: 1","question":"ما سرّ وصف الكتاب في مطلع سورة يوسف بـ﴿المبين﴾؟","answer":"المبين هو الواضح في نفسه والمبيّن للحق. ويلائم هذا الوصف سورة يوسف خاصة؛ إذ تكشف تفاصيل قصة لم يكن العرب يعرفونها بهذا البيان قبل نزول القرآن، وتظهر فيها دلائل الوحي والعبر في أبلغ أسلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص133، تحت «دلالة التعبير بـ﴿المبين﴾ في الآية»","url":""}]},{"id":"s12-3","number":3,"surah":12,"verses":[2],"references":[{"surah":12,"verses":[2]}],"verseLabel":"يوسف: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿إنا أنزلناه قرآنًا عربيًا﴾، دون أن يقال «كتابًا عربيًا»؟","answer":"سبق وصفه بالكتاب، فجاء ﴿قرآنًا﴾ ليضيف أنه كتاب مقروء متلوّ، فيجتمع حفظه في السطور وحفظه في الصدور. ووصفه بالعربية يبين أنه نزل بلسان المخاطبين الأولين، ليعقلوا معانيه ويظهر لهم بيانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص143، تحت «فائدة العدول في ﴿قرآنًا﴾»","url":""}]},{"id":"s12-4","number":4,"surah":12,"verses":[2],"references":[{"surah":12,"verses":[2]}],"verseLabel":"يوسف: 2","question":"ما دلالة تعليل إنزال القرآن عربيًا بقوله: ﴿لعلكم تعقلون﴾؟","answer":"لأن وضوح اللسان يزيل عذر عدم الفهم، لكن الغاية ليست سماع الألفاظ وحدها بل عقل المعاني والاعتبار بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص145، تحت «غرض التعبير بـ﴿تعقلون﴾»","url":""}]},{"id":"s12-5","number":5,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"ما دلالة بدء قوله تعالى: ﴿نحن نقص عليك﴾ بضمير العظمة؟","answer":"إسناد القصّ إلى الله بضمير العظمة يقرر أن الخبر وحي صادق، ويفخم شأن القصة التي يتولى الله بيانها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص152، تحت «نكتة بدء الآية بضمير العظمة»","url":""}]},{"id":"s12-209","number":209,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"لماذا وُصف القصص في قوله تعالى: ﴿أحسن القصص﴾ بأنه أحسن؟","answer":"لأنه أحسن الاقتصاص والبيان، وأحسن الأخبار المقصوصة بما اشتملت عليه من صدق وحكم وعبر وجمال أداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص156، تحت «دلالة اسم التفضيل ﴿أحسن القصص﴾»","url":""}]},{"id":"s12-6","number":6,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"ما معنى الباء في قوله: ﴿بما أوحينا إليك﴾؟","answer":"يقرر أن معرفة النبي بهذه التفاصيل لم تأت من تعلم بشري، بل من الوحي؛ فالقصة نفسها برهان على النبوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص158، تحت «معنى الباء في قوله: ﴿بما أوحينا إليك﴾»","url":""}]},{"id":"s12-7","number":7,"surah":12,"verses":[3],"references":[{"surah":12,"verses":[3]}],"verseLabel":"يوسف: 3","question":"ما دلالة وصف النبي قبل الوحي بأنه ﴿لمن الغافلين﴾ عن هذا القصص؟","answer":"الغفلة هنا عدم العلم لا الذم؛ وذكرها يقوي الدليل، إذ جاءه خبر لم يكن يعرفه بهذه الصورة المحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص166، تحت «نكتة التعبير بـ﴿الغافلين﴾»","url":""}]},{"id":"s12-8","number":8,"surah":12,"verses":[4],"references":[{"surah":12,"verses":[4]}],"verseLabel":"يوسف: 4","question":"ما سرّ تكرار فعل الرؤية في قول يوسف: ﴿إني رأيت أحد عشر كوكبًا والشمس والقمر رأيتهم لي ساجدين﴾؟","answer":"قيل: أعاد الفعل لتوكيد الرؤية بعد طول الفصل بينه وبين حال السجود. وقيل: ﴿رأيتهم لي ساجدين﴾ جواب لسؤال مقدّر: كيف رأيتها؟ فتنتقل العبارة من ذكر المرئيات إلى بيان هيئتها العجيبة في الرؤيا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص179–181، تحت «الموقع البياني لـ﴿رأيتهم﴾»","url":""}]},{"id":"s12-9","number":9,"surah":12,"verses":[4],"references":[{"surah":12,"verses":[4]}],"verseLabel":"يوسف: 4","question":"ما سرّ استعمال ضمير العقلاء في ﴿رأيتهم﴾ للكواكب والشمس والقمر؟","answer":"لأنها ظهرت في الرؤيا ساجدة، والسجود فعل العقلاء؛ فشخّصها التعبير وجعلها مشهدًا حيًا ينبئ بأشخاص يسجدون.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص181–182، تحت «نكتة ضمير الجمع في الآية الكريمة»","url":""}]},{"id":"s12-10","number":10,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة بدء يعقوب نصيحته بقوله: ﴿يا بني﴾؟","answer":"تصغير التحبيب يهيئ يوسف لقبول النصح ويكشف حنان الأب، خصوصًا أن الأمر يتضمن كتمان رؤيا عظيمة عن إخوته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص188، تحت «فائدة تصغير (بني)، وإضافته في السياق»","url":""}]},{"id":"s12-11","number":11,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة نهي يعقوب يوسف عن قصّ الرؤيا على إخوته؟","answer":"هو نهي نصح وإرشاد؛ فقد أدرك يعقوب ما تبشر به الرؤيا من رفعة يوسف، وخشي أن يحمل الحسد إخوته على الكيد له. فإخفاؤها حماية له من الشر الذي قد يثيره ظهور هذه النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص189–190، تحت «دلالة النهي في: ﴿لا تقصص رؤياك﴾»","url":""}]},{"id":"s12-12","number":12,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"لماذا عُدّي فعل الكيد باللام في قوله تعالى: ﴿فيكيدوا لك﴾؟","answer":"تفيد اللام أن الكيد موجّه إلى يوسف ومخصوص به، وقيل ضُمّن الفعل معنى الاحتيال له.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص196، تحت «فائدة تعدية فعل الكيد باللام»","url":""}]},{"id":"s12-210","number":210,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما فائدة المفعول المطلق ﴿كيدًا﴾ في قوله تعالى: ﴿فيكيدوا لك كيدًا﴾؟","answer":"يؤكد المفعول المطلق وقوع الكيد وقوته، فيشدد التحذير من تدبير الإخوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص197، تحت «فائدة التعبير بالمفعول المطلق ﴿كيدًا﴾»","url":""}]},{"id":"s12-211","number":211,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة تنكير ﴿كيدًا﴾ في قوله تعالى: ﴿فيكيدوا لك كيدًا﴾؟","answer":"يفيد التنكير تهويل الكيد الذي قد يدبرونه ليوسف وإبهام صورته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص197، تحت «نكتة تنكير ﴿كيدًا﴾»","url":""}]},{"id":"s12-13","number":13,"surah":12,"verses":[5],"references":[{"surah":12,"verses":[5]}],"verseLabel":"يوسف: 5","question":"ما دلالة تعليل التحذير من كيد الإخوة بقوله: ﴿إن الشيطان للإنسان عدو مبين﴾؟","answer":"لم يقطع رابطة الأخوة باتهامهم وحدهم، بل كشف المحرك الذي يوقد الحسد؛ فالشيطان عدو ظاهر يسعى لإفساد الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص198، تحت «نكتة الفصل في: ﴿إن الشيطان﴾»","url":""}]},{"id":"s12-14","number":14,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك يجتبيك ربك﴾ بعد الرؤيا مباشرة؟","answer":"يربط التشبيه بين ما أكرمه الله به من الرؤيا وما سيختاره له من النبوة والتعليم وإتمام النعمة. فجاءت البشارة عقب التحذير من الكيد تطمينًا ليوسف وإعدادًا له لما سيلاقيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص205، تحت «بلاغة التشبيه في ﴿وكذلك﴾»","url":""}]},{"id":"s12-15","number":15,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما دلالة لفظ ﴿تأويل﴾ في قوله تعالى: ﴿تأويل الأحاديث﴾؟","answer":"التأويل ردّ الخبر إلى حقيقته وما يؤول إليه؛ أي كشف مآل الرؤيا وما ترمز إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص208، تحت «إيثار لفظ ﴿تأويل﴾ في السياق»","url":""}]},{"id":"s12-212","number":212,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما المراد بـ﴿الأحاديث﴾ في قوله تعالى: ﴿تأويل الأحاديث﴾؟","answer":"من تفسيرها الرؤى، وقيل تشمل معاني كتب الله وسنن الأنبياء وما فيها من دقائق وحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص209، تحت «معنى ﴿الأحاديث﴾، وسر استعمالها في السياق»","url":""}]},{"id":"s12-16","number":16,"surah":12,"verses":[6],"references":[{"surah":12,"verses":[6]}],"verseLabel":"يوسف: 6","question":"ما دلالة الجمع بين يوسف وآل يعقوب في إتمام النعمة؟","answer":"لم تقف بركة النعمة عند يوسف؛ بل شملت آل يعقوب بما حصل لهم بسببه من العز والتمكين والسرور. وذكره أولًا ثم عطف آله يبرز خصوص منزلته وامتداد أثر نعمته إلى أهله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص211، تحت «فائدة التعبير بـ﴿عليك وعلى آل يعقوب﴾»","url":""}]},{"id":"s12-17","number":17,"surah":12,"verses":[7],"references":[{"surah":12,"verses":[7]}],"verseLabel":"يوسف: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿لقد كان في يوسف وإخوته آيات للسائلين﴾ بالجمع؟","answer":"الجمع يدل على كثرة الدلائل وتنوعها في القصة؛ ففيها عاقبة الصبر، وآثار الحسد، ودلائل صدق الوحي. وتنكير ﴿آيات﴾ يفيد تعظيمها، فكأن كل مرحلة من القصة باب للعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص226، تحت «فائدة جمع ﴿آيات﴾ وتنكيرها في الآية الكريمة»","url":""}]},{"id":"s12-18","number":18,"surah":12,"verses":[7],"references":[{"surah":12,"verses":[7]}],"verseLabel":"يوسف: 7","question":"ما سرّ تخصيص ﴿السائلين﴾ بذكر الآيات في قصة يوسف؟","answer":"فيه حثّ على طلب خبر القصة والسؤال للتعلم والاعتبار؛ فالسائل المعتني أهيأ لفهم دلائلها ممن يعرض عنها. وقيل يوافق اللفظ سؤالًا كان سببًا لنزولها، مع أن عبرها لا تنحصر في أولئك السائلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص227–228، تحت «سر تقييد ﴿آيات﴾ بتعليقها بلفظ السائلين»","url":""}]},{"id":"s12-19","number":19,"surah":12,"verses":[8],"references":[{"surah":12,"verses":[8]}],"verseLabel":"يوسف: 8","question":"ما سرّ التعبير في قول الإخوة: ﴿ليوسف وأخوه أحب إلى أبينا منا﴾ ولم يسموا بنيامين؟","answer":"أضافوا الأخ إلى يوسف لأنهما شقيقان، فجمعوهما في جهة واحدة بإزاء بقية الإخوة، مع أنهم جميعًا إخوة. وفي قولهم ﴿وأخوه﴾ تظهر الجفوة التي أحدثها الحسد في نظرتهم إلى الأسرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص230–231، تحت «علة عطف قوله: ﴿وأخوه﴾ في السياق»","url":""}]},{"id":"s12-20","number":20,"surah":12,"verses":[8],"references":[{"surah":12,"verses":[8]}],"verseLabel":"يوسف: 8","question":"ما دلالة احتجاج الإخوة بقولهم: ﴿ونحن عصبة﴾؟","answer":"جعلوا القوة والعدد معيار استحقاق المحبة؛ رأوا أنفسهم أنفع للأب، وغفلوا أن المحبة ليست صفقة تقاس بالكثرة والمنفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص233، تحت «سر التعبير بلفظ ﴿عصبة﴾»","url":""}]},{"id":"s12-21","number":21,"surah":12,"verses":[8],"references":[{"surah":12,"verses":[8]}],"verseLabel":"يوسف: 8","question":"ما وجه قولهم عن أبيهم: ﴿إن أبانا لفي ضلال مبين﴾؟","answer":"أرادوا خطأه في تقدير المحبة لا ضلال الدين، لكن العبارة تكشف كيف يدفع الحسد صاحبه إلى تضخيم الحكم على أقرب الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص235، تحت «معنى ﴿ضلال﴾ وسر وصفه بالإبانة»","url":""}]},{"id":"s12-22","number":22,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما دلالة التخيير بـ﴿أو﴾ في قولهم: ﴿اقتلوا يوسف أو اطرحوه أرضًا﴾؟","answer":"عرضوا طريقين لتحقيق غرض واحد هو إبعاد يوسف عن أبيه: القتل المباشر أو الطرح في مكان بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص241، تحت «دلالة التخيير في ﴿أو﴾»","url":""}]},{"id":"s12-213","number":213,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما دلالة تنكير ﴿أرضًا﴾ في قولهم: ﴿أو اطرحوه أرضًا﴾؟","answer":"يلائم التنكير إرادتهم مكانًا مجهولًا بعيدًا لا يُعرف فيه أثر يوسف ولا يهتدي منه إلى أبيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص242، تحت «تنكير ﴿أرضًا﴾»","url":""}]},{"id":"s12-23","number":23,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما وجه قولهم: ﴿يخل لكم وجه أبيكم﴾؟","answer":"صوّروا وجه الأب واهتمامه كمساحة مشغولة بيوسف، وتوهموا أن إزالته ستفرغها لهم؛ وهي صورة دقيقة لاستحواذ الغيرة على رؤيتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص244، تحت «سر إسناد الخلو إلى الوجه بين الاستعارة والمجاز»","url":""}]},{"id":"s12-24","number":24,"surah":12,"verses":[9],"references":[{"surah":12,"verses":[9]}],"verseLabel":"يوسف: 9","question":"ما دلالة قول الإخوة: ﴿وتكونوا من بعده قومًا صالحين﴾ وهم يدبرون إبعاد يوسف؟","answer":"على تفسير الصلاح بصلاح الدين، سوّلت لهم أنفسهم أن يرتكبوا الجريمة ثم يتوبوا بعدها. وقيل أرادوا صلاح حالهم مع أبيهم وانتظام أمرهم بعد انفرادهم بمحبته؛ وفي الوجهين يظهر توهمهم أن إبعاد يوسف طريق إلى إصلاح شأنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص248، تحت «نكتة حذف متعلق ﴿صالحين﴾»","url":""}]},{"id":"s12-25","number":25,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما سرّ التصريح باسم يوسف في ﴿لا تقتلوا يوسف﴾ مع إمكان إضماره؟","answer":"ذكر الاسم يستحضر شخص يوسف في نفوس إخوته، ويستبقي ما في القلوب من رحمة به؛ فجاء مع النهي عن قتله لاستجلاب شفقتهم وإقناعهم بالعدول عن القتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص256، تحت «وضع المظهر ﴿يوسف﴾ موضع المضمر في الآية»","url":""}]},{"id":"s12-26","number":26,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما دلالة ﴿غيابت الجب﴾؟","answer":"الغيابة هي ما يستر عن العين، وفي الجب موضع مظلم لا يظهر فيه من أُلقي فيه. فاختيارها يبرز غرض الإخفاء، لا مجرد الوصول إلى أسفل البئر؛ إذ قد يكون القعر عميقًا مع بقاء ما فيه مرئيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص256، تحت «إيثار كلمتي ﴿غيابت الجب﴾»","url":""}]},{"id":"s12-27","number":27,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما بلاغة الاستعارة في قوله تعالى: ﴿يلتقطه﴾؟","answer":"صوّر العثور على يوسف وأخذه بصورة التقاط الشيء الضائع في الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص259، تحت «بلاغة الاستعارة في الفعل ﴿يلتقطه﴾»","url":""}]},{"id":"s12-214","number":214,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما فائدة التعبير بـ﴿بعض﴾ في قوله تعالى: ﴿يلتقطه بعض السيارة﴾؟","answer":"لأن إنقاذه على يد أي فرد من المسافرين يحقق غرض القائل: إبعاده مع إبقائه حيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص260، تحت «فائدة التعبير بلفظ ﴿بعض﴾»","url":""}]},{"id":"s12-215","number":215,"surah":12,"verses":[10],"references":[{"surah":12,"verses":[10]}],"verseLabel":"يوسف: 10","question":"ما دلالة التعريف في لفظ ﴿السيارة﴾؟","answer":"المراد جماعة المسافرين المعهودة التي تمر بالطريق وترد الماء، لا المركبة المعروفة في الاستعمال الحديث.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص260، تحت «دلالة (ال) في كلمة ﴿السيارة﴾»","url":""}]},{"id":"s12-28","number":28,"surah":12,"verses":[11],"references":[{"surah":12,"verses":[11]}],"verseLabel":"يوسف: 11","question":"ما وجه قولهم: ﴿ما لك لا تأمنا على يوسف﴾؟","answer":"بدأوا باستنكار عدم الثقة قبل طلب إخراجه، ليجعلوا الأب في موقف المدافع ويزيلوا حاجزه النفسي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص269، تحت «معنى التركيب ﴿ما لك﴾، ودلالة الاستفهام»","url":""}]},{"id":"s12-29","number":29,"surah":12,"verses":[11],"references":[{"surah":12,"verses":[11]}],"verseLabel":"يوسف: 11","question":"ما دلالة كثرة التوكيد في قولهم: ﴿وإنا له لناصحون﴾؟","answer":"جمعوا إنَّ واللام وتقديم ﴿له﴾ لتغطية موضع الشك، وكثرة التوكيد نفسها تناسب كذبًا يحتاج إلى تدعيم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص272، تحت «بلاغة اجتماع المؤكدات في جملتي النصح والحفظ»","url":""}]},{"id":"s12-30","number":30,"surah":12,"verses":[12],"references":[{"surah":12,"verses":[12]}],"verseLabel":"يوسف: 12","question":"ما وجه قولهم: ﴿يرتع ويلعب﴾؟","answer":"اختاروا ما يلائم سنه ويستميل قلب الأب إلى الترفيه عنه، ثم ألحقوا ضمان الحفظ ليكتمل الإقناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص277، تحت «إيثار استعمال الفعلين: ﴿يرتع ويلعب﴾»","url":""}]},{"id":"s12-31","number":31,"surah":12,"verses":[13],"references":[{"surah":12,"verses":[13]}],"verseLabel":"يوسف: 13","question":"ما دلالة التعبير عن فراق يوسف بالحزن، وعن أكل الذئب بالخوف؟","answer":"الحزن ألم الفراق الذي يستشعره يعقوب، حتى إن مجرد عزمهم على الذهاب بيوسف يؤلمه؛ أما الخوف فمتعلق بخطر يتوقعه ولم يقع. فجمع الكلام بين ألم البعد عنه والخشية من الضرر الذي قد يصيبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص294، تحت «الحزن والخوف»","url":""}]},{"id":"s12-32","number":32,"surah":12,"verses":[13],"references":[{"surah":12,"verses":[13]}],"verseLabel":"يوسف: 13","question":"ما سرّ تخصيص الذئب بالذكر في خوف يعقوب على يوسف؟","answer":"لأنه خطر معروف في مراعيهم عند الغفلة، لكن ذكره منحهم من حيث لا يريد الحجة التي سيستعملونها لاحقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص293، تحت «سر تخصيص الذئب دون سائر الحيوانات المفترسة»","url":""}]},{"id":"s12-33","number":33,"surah":12,"verses":[14],"references":[{"surah":12,"verses":[14]}],"verseLabel":"يوسف: 14","question":"ما وجه قولهم: ﴿لئن أكله الذئب ونحن عصبة إنا إذا لخاسرون﴾؟","answer":"جعلوا كثرتهم وقوتهم ضمانًا لحفظه، حتى عدّوا عجزهم عن حمايته من ذئب خسارة تهدر قيمتهم ورجاء أبيهم فيهم. وجمعوا القسم والتوكيد لإقناعه بإرسال يوسف معهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص302، تحت «بلاغة قوله في جواب الشرط: ﴿إنا إذًا لخاسرون﴾»","url":""}]},{"id":"s12-34","number":34,"surah":12,"verses":[15],"references":[{"surah":12,"verses":[15]}],"verseLabel":"يوسف: 15","question":"ما دلالة حذف جواب ﴿فلما ذهبوا به وأجمعوا أن يجعلوه في غيابت الجب﴾؟","answer":"على وجه حذف الجواب، دلّ السياق على أنهم أنفذوا ما عزموا عليه وألقوه في الجب. وفي الحذف إيجاز وتهويل؛ إذ يُترك للسامع أن يتصور فظاعة ما صنعوه، بدل تفصيل مشهد الأذى.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص311، تحت «دلالة حذف جواب (لما)»","url":""}]},{"id":"s12-35","number":35,"surah":12,"verses":[15],"references":[{"surah":12,"verses":[15]}],"verseLabel":"يوسف: 15","question":"ما دلالة الوعد ليوسف في الجب بقوله: ﴿لتنبئنهم بأمرهم هذا﴾؟","answer":"جاء الوعد في أشد لحظة ضعف ليغرس يقين العاقبة: سيأتي يوم يكون هو المخبر وهم لا يعرفونه؛ فالوحي سبق النجاة المادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص313، تحت «دلالة اللام في ﴿لتنبئنهم﴾، وإيثار التعبير بالإنباء»","url":""}]},{"id":"s12-36","number":36,"surah":12,"verses":[15],"references":[{"surah":12,"verses":[15]}],"verseLabel":"يوسف: 15","question":"ما دلالة إعراب جملة ﴿وهم لا يشعرون﴾، ودلالتها؟","answer":"تحتمل أنهم لا يشعرون بالوحي أو لا يعرفونه عند تحقق الوعد؛ وفي الحالين يظهر أن تدبير الله يجري خارج إدراكهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص314–315، تحت «إعراب جملة ﴿وهم لا يشعرون﴾، ودلالتها»","url":""}]},{"id":"s12-37","number":37,"surah":12,"verses":[16],"references":[{"surah":12,"verses":[16]}],"verseLabel":"يوسف: 16","question":"لماذا جاء إخوة يوسف أباهم ﴿عشاء﴾؟","answer":"اختاروا وقت العشاء وظلمته ليستتر اضطراب وجوههم ويقل تدقيق أبيهم في حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص321، تحت «إيثار كلمة ﴿عشاء﴾ دون مساء مثلًا»","url":""}]},{"id":"s12-216","number":216,"surah":12,"verses":[16],"references":[{"surah":12,"verses":[16]}],"verseLabel":"يوسف: 16","question":"ما سرّ استعمال ﴿يبكون﴾ في وصف مجيء إخوة يوسف؟","answer":"اتخذوا البكاء دليلًا مصطنعًا على صدق روايتهم، فصوّر السياق تمثيلهم للحزن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص322، تحت «سر استعمال ﴿يبكون﴾»","url":""}]},{"id":"s12-38","number":38,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما سرّ استعمال الفعل ﴿نستبق﴾ في اعتذار إخوة يوسف؟","answer":"اختاروا الاستباق لأنه نشاط مألوف يشغل الجماعة ويجعل ابتعادهم عن يوسف في ظاهر قصتهم معقولًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص325، تحت «سر استعمال الفعل ﴿نستبق﴾، ودلالة الصيغة»","url":""}]},{"id":"s12-217","number":217,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما دلالة جملة ﴿وتركنا يوسف﴾؟","answer":"اعترافهم بترك يوسف يشرح سبب غيابهم عنه، لكنه يكشف في الوقت نفسه تقصيرهم في حفظه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص325، تحت «دلالة جملة ﴿وتركنا يوسف﴾»","url":""}]},{"id":"s12-218","number":218,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما فائدة قولهم: ﴿عند متاعنا﴾؟","answer":"جعلوا بقاء يوسف عند المتاع سببًا طبيعيًا لعدم مشاركته في الاستباق، لتبدو قصتهم أقرب إلى التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص326، تحت «فائدة الظرف ﴿عند﴾، وإضافته إلى ﴿متاعنا﴾»","url":""}]},{"id":"s12-39","number":39,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"لماذا عبّر إخوة يوسف بالإيمان في قولهم: ﴿وما أنت بمؤمن لنا﴾ بدل التصديق؟","answer":"الإيمان هنا يتضمن الثقة والطمأنينة إلى خبرهم، لا مجرد الحكم اللفظي بصدقه، وهم يعلمون أنهم فقدوا هذه الثقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص331، تحت «سر التعبير بالإيمان دون التصديق»","url":""}]},{"id":"s12-219","number":219,"surah":12,"verses":[17],"references":[{"surah":12,"verses":[17]}],"verseLabel":"يوسف: 17","question":"ما فائدة قولهم: ﴿ولو كنا صادقين﴾؟","answer":"حاولوا تصوير عدم قبول أبيهم للخبر بأنه ناشئ عن شدة محبته ليوسف وسوء ظنه بهم حتى مع افتراض صدقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص331، تحت «فائدة جملة ﴿ولو كنا صادقين﴾»","url":""}]},{"id":"s12-40","number":40,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما سرّ وصف الدم نفسه بالكذب في قوله: ﴿بدم كذب﴾؟","answer":"وصف الدم نفسه بالكذب مبالغة، لأنه دليل مصنوع ينطق بخلاف الحقيقة؛ والقميص السليم فضح تناقض روايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص340، تحت «بلاغة الوصف بالمصدر في ﴿بدم كذب﴾»","url":""}]},{"id":"s12-41","number":41,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما سرّ التعبير في قول يعقوب: ﴿بل سولت لكم أنفسكم أمرًا﴾؟","answer":"لم يعرف التفصيل لكنه أدرك أن النفس زينت لهم فعلًا قبيحًا؛ فانتقل من دليل القميص إلى تشخيص الجذر الداخلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص342، تحت «إيثار الفعل ﴿سولت﴾»","url":""}]},{"id":"s12-42","number":42,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما النكتة البلاغية في وصف الصبر بالجمال ومعناه في قوله تعالى: ﴿فصبر جميل﴾؟","answer":"جاءت عبارة موجزة تدل على ثباته على الصبر: فالتقدير «صبري صبر جميل» أو «فصبر جميل أمثل». وحذف أحد طرفي الجملة يبرز القرار نفسه، والجميل هو الصبر الذي لا يخالطه جزع ولا شكوى إلى الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص344، تحت «نكتة وصف الصبر بالجمال ومعناه»","url":""}]},{"id":"s12-43","number":43,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما دلالة قول يعقوب: ﴿والله المستعان﴾؟","answer":"فيه إظهار افتقاره إلى معونة الله على احتمال البلاء؛ فلا يتحقق الصبر الجميل إلا بعونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص345، تحت «نكتة الإخبار عن اسم الجلالة بـ﴿المستعان﴾»","url":""}]},{"id":"s12-220","number":220,"surah":12,"verses":[18],"references":[{"surah":12,"verses":[18]}],"verseLabel":"يوسف: 18","question":"ما بلاغة التعبير بقوله: ﴿على ما تصفون﴾؟","answer":"سمّى روايتهم وصفًا يقولونه ولم يقرّ بأنها حقيقة؛ ففيه تعريض بكذبهم وإبقاء لباب الأمل في يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص346، تحت «البلاغة في التعبير بـ﴿ما تصفون﴾»","url":""}]},{"id":"s12-44","number":44,"surah":12,"verses":[19],"references":[{"surah":12,"verses":[19]}],"verseLabel":"يوسف: 19","question":"ما سرّ التعبير في قول الوارد: ﴿يا بشرى هذا غلام﴾؟","answer":"نادى البشرى، أو خاطب أصحابه بها، فرحًا بما وجد؛ فالتعبير يصور مفاجأة العثور على الغلام وشدة الاستبشار به.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص360، تحت «بلاغة المجاز في ﴿يا بشرى﴾»","url":""}]},{"id":"s12-45","number":45,"surah":12,"verses":[19],"references":[{"surah":12,"verses":[19]}],"verseLabel":"يوسف: 19","question":"ما دلالة الواو في ﴿وأسروه﴾، وإيثار التعبير بالفعل؟","answer":"أخفوا أمره وجعلوه في حكم البضاعة التي تُتجر؛ فجمع التعبير بين الكتمان واتخاذه متاعًا للبيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص363، تحت «دلالة الواو في ﴿وأسروه﴾، وإيثار التعبير بالفعل»","url":""}]},{"id":"s12-46","number":46,"surah":12,"verses":[19],"references":[{"surah":12,"verses":[19]}],"verseLabel":"يوسف: 19","question":"ما دلالة ختم مشهد إخراج يوسف من الجب بقوله: ﴿والله عليم بما يعملون﴾؟","answer":"تقرر الفاصلة أن أعمالهم وخفايا قصدهم لا تغيب عن الله. وفيها تطمين بأن ما يجري ليوسف داخل في تدبيره الحكيم؛ فقد بدا الأمر بيعًا وإبعادًا، وهو يساق إلى العاقبة التي وعده الله بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص366، تحت «أثر الفاصلة: ﴿والله عليم بما يعملون﴾»","url":""}]},{"id":"s12-47","number":47,"surah":12,"verses":[20],"references":[{"surah":12,"verses":[20]}],"verseLabel":"يوسف: 20","question":"ما دلالة وصف الثمن بأنه ﴿بخس﴾؟","answer":"يدل على ثمن ناقص زهيد لا يوافق قيمة يوسف، ويكشف استعجال البائعين التخلص منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص374، تحت «مدلول الوصف بـ﴿بخس﴾»","url":""}]},{"id":"s12-221","number":221,"surah":12,"verses":[20],"references":[{"surah":12,"verses":[20]}],"verseLabel":"يوسف: 20","question":"ما دلالة وصف الدراهم بأنها ﴿معدودة﴾؟","answer":"تصوّر قلتها حتى كانت تُعدّ باليد، فتزيد بيان زهْدهم في يوسف وجهلهم بقدره.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص375، تحت «إعراب ﴿دراهم﴾ ودلالة وصفها بـ﴿معدودة﴾»","url":""}]},{"id":"s12-48","number":48,"surah":12,"verses":[20],"references":[{"surah":12,"verses":[20]}],"verseLabel":"يوسف: 20","question":"ما فائدة التعبير في ﴿من الزاهدين﴾؟","answer":"أرادوا التخلص منه أو لم يعرفوا قدره، فباعوه بلا مساومة تليق به؛ والزهد فيه يزيد مفارقة ما سيبلغه من مكانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص376، تحت «فائدة التعبير في ﴿من الزاهدين﴾»","url":""}]},{"id":"s12-49","number":49,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما سرّ التعبير في قول عزيز مصر: ﴿أكرمي مثواه﴾؟","answer":"طلب حسن إقامته ورعايته، وفي إكرام المثوى كناية عن إكرام صاحبه ومبالغة فيه؛ إذ يشمل ما يحيط به من أسباب الراحة. وكان هذا الإكرام من أسباب ما هيّأه الله له من مكانة وتمكين في مصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص385، تحت «الكناية في ﴿أكرمي مثواه﴾»","url":""}]},{"id":"s12-50","number":50,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما دلالة الرجاء في قول العزيز: ﴿عسى أن ينفعنا﴾؟","answer":"رأى العزيز في يوسف مخايل النجابة، فرجا أن ينتفع به في شؤونه ويجد عنده الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص386، تحت «دلالة الرجاء الدال عليه ﴿عسى﴾»","url":""}]},{"id":"s12-222","number":222,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"لماذا قُدّم رجاء نفع يوسف على قوله: ﴿أو نتخذه ولدًا﴾؟","answer":"انتقل الكلام من النفع المعتاد إلى منزلة أخص وأشد تقريبًا؛ فاتخاذه ولدًا غاية ما رجاه العزيز له في بيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص387، تحت «سر تقديم رجاء نفعه على اتخاذه ولدًا»","url":""}]},{"id":"s12-51","number":51,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك مكنا ليوسف في الأرض﴾ وهو ما يزال مملوكًا؟","answer":"يذكر المصدر أن التمكين يشمل المكانة والرعاية التي هيأها الله له في مصر، وأن هذا الإكرام يمهّد لما سيبلغه من سلطان. وقيل إن الماضي يصوّر تحقق التمكين المستقبل؛ فظاهر المحنة لا يكشف وحده العاقبة التي يدبرها الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص389، تحت «إيثار فعل التمكين، وصيغة الماضي»","url":""}]},{"id":"s12-52","number":52,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما سرّ التذييل بقوله تعالى: ﴿والله غالب على أمره﴾ في قصة يوسف؟","answer":"يقرر أن تدبير الله نافذ لا ترده مقاصد البشر؛ أراد الإخوة بيوسف السوء فساقه الله إلى ما أراد له من الخير.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص397، تحت «سر التذييل، وعلاقته بالمعنى»","url":""}]},{"id":"s12-223","number":223,"surah":12,"verses":[21],"references":[{"surah":12,"verses":[21]}],"verseLabel":"يوسف: 21","question":"ما فائدة الاحتراس في قوله تعالى: ﴿ولكن أكثر الناس لا يعلمون﴾؟","answer":"يبين أن أكثر الناس يقفون عند ظاهر الأسباب وتخفى عليهم حكمة العاقبة، مع إثبات العلم لمن علّمه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص398، تحت «فائدة الاحتراس في خاتمة الآية»","url":""}]},{"id":"s12-53","number":53,"surah":12,"verses":[22],"references":[{"surah":12,"verses":[22]}],"verseLabel":"يوسف: 22","question":"ما معنى بلوغ يوسف أشده، ولماذا لم تحدد الآية سنه؟","answer":"بلوغ الأشد اكتمال قوته الجسدية والنفسية، والعدول عن تحديد سن بعينها يوجه النظر إلى تحقق النضج نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص404، تحت «معنى بلوغ الأشد، والعدول عن تحديد سن»","url":""}]},{"id":"s12-224","number":224,"surah":12,"verses":[22],"references":[{"surah":12,"verses":[22]}],"verseLabel":"يوسف: 22","question":"ما فائدة الجمع بين الحكم والعلم في قوله تعالى: ﴿آتيناه حكمًا وعلمًا﴾؟","answer":"جمع الله له نضج الحكم والبصيرة والعلم، ليواجه الفتنة بعقل راشد ومعرفة تهديه إلى الصواب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص406، تحت «فائدة الجمع بين الحكم والعلم، وعلة التقديم»","url":""}]},{"id":"s12-54","number":54,"surah":12,"verses":[22],"references":[{"surah":12,"verses":[22]}],"verseLabel":"يوسف: 22","question":"ما دلالة الانتقال من عطاء يوسف إلى قوله: ﴿وكذلك نجزي المحسنين﴾؟","answer":"نقل عطاء يوسف من حالة خاصة إلى سنة عامة: الإحسان سبب لعطاء العلم والحكمة، فيفتح القصة لكل مقتدٍ.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص408، تحت «التشبيه في ﴿وكذلك نجزي المحسنين﴾»","url":""}]},{"id":"s12-55","number":55,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما سرّ التعبير في قوله تعالى: ﴿وراودته التي هو في بيتها﴾ ولم يذكر اسمها؟","answer":"صلة الموصول تكشف عنصر الفتنة الأخطر: هو تحت سلطانها وفي بيتها، بينما إبهام الاسم يصرف النظر من الشخص إلى الموقف والعبرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص420، تحت «فائدة جمع الظرفية والإضافة في الآية»","url":""}]},{"id":"s12-56","number":56,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما دلالة فعل ﴿راودته﴾؟","answer":"يدل على طلب متكرر بلطف وحيلة، لا خاطر عابر؛ فالكلمة تختصر إلحاحًا ومقاومة امتدت ولم تستجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص415، تحت «سر انتخاب لفظة ﴿راودته﴾»","url":""}]},{"id":"s12-57","number":57,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما سرّ التعبير في قولها: ﴿هيت لك﴾ بعد إغلاق الأبواب؟","answer":"عبارة دعوة صريحة جاءت بعد إحكام المكان، فبلغت الفتنة ذروتها؛ وقابلها يوسف فورًا بـ﴿معاذ الله﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص424، تحت «سر الجمع بين المراودة القولية والعملية»","url":""}]},{"id":"s12-58","number":58,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما دلالة مبادرة يوسف إلى قوله: ﴿معاذ الله﴾؟","answer":"هي استعاذة واعتصام بالله، وفي تصدير جوابه بها حسم للمراودة وإظهار لقوة إيمانه. ثم علّل امتناعه بقبح الخيانة وكفر الإحسان؛ فجمع جوابه الالتجاء إلى الله وبيان سبب الرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص426، تحت «نكتة التعبير بالمصدر الميمي ﴿معاذ﴾»","url":""}]},{"id":"s12-59","number":59,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما المراد بـ﴿ربي﴾ في قول يوسف: ﴿إنه ربي﴾؟","answer":"ذكر المصدر وجهين: أن المراد الله المنعم المدبر، أو العزيز الذي أكرم إقامته؛ وعلى الوجهين يمنع الوفاءُ والشكرُ الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص427، تحت «معنى (الرب) في قوله: ﴿إنه ربي﴾»","url":""}]},{"id":"s12-225","number":225,"surah":12,"verses":[23],"references":[{"surah":12,"verses":[23]}],"verseLabel":"يوسف: 23","question":"ما بلاغة التعبير في قول يوسف: ﴿أحسن مثواي﴾؟","answer":"جعل إحسان الإقامة كناية عن مجمل الرعاية والإكرام، فاستحضر النعمة سببًا للوفاء لا للمعصية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص428، تحت «بلاغة المجاز في قوله: ﴿أحسن مثواي﴾»","url":""}]},{"id":"s12-60","number":60,"surah":12,"verses":[24],"references":[{"surah":12,"verses":[24]}],"verseLabel":"يوسف: 24","question":"ما دلالة تعليق همّ يوسف بقوله: ﴿لولا أن رأى برهان ربه﴾؟","answer":"على وجه تفسيري يختاره المصدر، يمتنع وقوع الهم لوجود البرهان؛ فالمعنى: لولا رؤيته البرهان لهمّ بها. ويذكر وجهًا آخر يحمل الهم على ميل الطبع العارض الذي لم يتحول إلى عزم أو فعل. وفي الوجهين يبرز حفظ الله ليوسف وصرف السوء عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص442، تحت «نكتة ذكر الهم وتعليقه بـ﴿لولا﴾»","url":""}]},{"id":"s12-61","number":61,"surah":12,"verses":[24],"references":[{"surah":12,"verses":[24]}],"verseLabel":"يوسف: 24","question":"ما علة التعبير بقوله: ﴿لنصرف عنه السوء﴾؟","answer":"لم يقل صرفناه عنهما فقط، بل صرفهما عنه؛ فالعناية الإلهية أبعدت أسباب الشر من طريق العبد المخلص.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص444–446، تحت «علة التعبير بقوله: ﴿لنصرف عنه السوء﴾»","url":""}]},{"id":"s12-62","number":62,"surah":12,"verses":[24],"references":[{"surah":12,"verses":[24]}],"verseLabel":"يوسف: 24","question":"ما دلالة وصف يوسف بأنه من ﴿عبادنا المخلصين﴾؟","answer":"الإخلاص سر نجاته من الفتنة؛ وعلى قراءة المخلَصين هو ممن اصطفاهم الله، وعلى المخلِصين هو صادق القصد، والمعنيان متلازمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص448، تحت «سر اختلاف القراءة في لفظ ﴿المخلصين﴾»","url":""}]},{"id":"s12-63","number":63,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"ما دلالة الإيجاز في قوله: ﴿واستبقا﴾؟","answer":"فعل واحد جمع مقصدين متضادين: يوسف يسابق إلى الهرب، وهي تسابق لمنعه؛ فاختصر حركة المشهد وصراعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص455، تحت «دلالة الإيجاز في قوله: ﴿واستبقا﴾»","url":""}]},{"id":"s12-64","number":64,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"ما دلالة كون القميص قدّ ﴿من دبر﴾ في إثبات براءة يوسف؟","answer":"لأنه دليل مادي على أنه كان هاربًا وهي خلفه تمسكه؛ فتحول القميص من أثر اعتداء إلى شاهد براءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص460، تحت «دلالة قوله تعالى: ﴿من دبر﴾»","url":""}]},{"id":"s12-65","number":65,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"ما دلالة ﴿ما﴾ في قول امرأة العزيز: ﴿ما جزاء من أراد بأهلك سوءًا﴾؟","answer":"يرجح المصدر أنها نافية، فيكون الكلام حصرًا للجزاء فيما ذكرته، ويجوز حملها على الاستفهام.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص461، تحت «دلالة لفظ ﴿ما﴾»","url":""}]},{"id":"s12-226","number":226,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"لماذا بادرت امرأة العزيز بالقول عند الباب؟","answer":"بادرت بالاتهام لتدفع التهمة عن نفسها وتسبق يوسف إلى توجيه فهم العزيز لما وقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص462، تحت «نكتة مبادرة المرأة بالقول»","url":""}]},{"id":"s12-227","number":227,"surah":12,"verses":[25],"references":[{"surah":12,"verses":[25]}],"verseLabel":"يوسف: 25","question":"لماذا صاغت اتهامها في قالب كلي: ﴿ما جزاء من أراد بأهلك سوءًا﴾؟","answer":"عرضت دعواها في صورة قاعدة عامة تستثير غيرة العزيز على أهله وتحمله على معاقبة يوسف قبل سماع دفاعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص462، تحت «دلالة تقديم الكلام في قالب كلي»","url":""}]},{"id":"s12-66","number":66,"surah":12,"verses":[26],"references":[{"surah":12,"verses":[26]}],"verseLabel":"يوسف: 26","question":"ما سرّ التعبير في قول يوسف باقتضاب: ﴿هي راودتني عن نفسي﴾؟","answer":"لم يتكلم حتى اتهمته، فاقتصر على دفع التهمة. وفي تقديم «هي» قصر للمراودة عليها وردّ لاتهامها؛ فالجملة الموجزة تبين الفاعل الحقيقي وتثبت براءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص469، تحت «بلاغة القصر في قوله: ﴿هي راودتني عن نفسي﴾»","url":""}]},{"id":"s12-67","number":67,"surah":12,"verses":[26],"references":[{"surah":12,"verses":[26]}],"verseLabel":"يوسف: 26","question":"ما دلالة كون الشاهد ﴿من أهلها﴾؟","answer":"شهادة القريب أبعد عن تهمة الانحياز ليوسف وأقوى حجة على المرأة؛ فجاء البرهان من الجهة التي يُنتظر أن تدافع عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص471، تحت «فائدة ذكر كون الشاهد من أهلها»","url":""}]},{"id":"s12-68","number":68,"surah":12,"verses":[27,28],"references":[{"surah":12,"verses":[27,28]}],"verseLabel":"يوسف: 27–28","question":"ما دلالة تعليق الشاهد الحكم على جهة شق القميص؟","answer":"حوّل النزاع من دعويين متعارضتين إلى أثر محسوس: شقه من الأمام يدل على إقبال، ومن الخلف يدل على هرب؛ فالبينة ناطقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص472، تحت «سر ذكر قد القميص من الشاهد»","url":""}]},{"id":"s12-69","number":69,"surah":12,"verses":[28],"references":[{"surah":12,"verses":[28]}],"verseLabel":"يوسف: 28","question":"ما أثر لفظ ﴿كيدكن﴾ في قول العزيز: ﴿إنه من كيدكن﴾؟","answer":"يكشف اللفظ التدبير الخفي الذي قلب البريء متهمًا وحاول صرف الأنظار عن الفاعل الحقيقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص481، تحت «أثر لفظ ﴿كيدكن﴾»","url":""}]},{"id":"s12-228","number":228,"surah":12,"verses":[28],"references":[{"surah":12,"verses":[28]}],"verseLabel":"يوسف: 28","question":"ما فائدة التذييل بقوله: ﴿إن كيدكن عظيم﴾؟","answer":"عمّم الحكم بعد الواقعة وبيّن عظم أثر ذلك الكيد في الموقف وما أحدثه من قلب للحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص483، تحت «فائدة التذييل في آخر الآية»","url":""}]},{"id":"s12-70","number":70,"surah":12,"verses":[29],"references":[{"surah":12,"verses":[29]}],"verseLabel":"يوسف: 29","question":"ما سرّ التعبير في قول العزيز: ﴿يوسف أعرض عن هذا﴾؟","answer":"أراد إغلاق الفضيحة وحفظ البيت، فطلب من يوسف الكتمان، ثم أمر المرأة بالاستغفار اعترافًا بخطئها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص487، تحت «دلالة فعل الأمر ﴿أعرض﴾»","url":""}]},{"id":"s12-71","number":71,"surah":12,"verses":[29],"references":[{"surah":12,"verses":[29]}],"verseLabel":"يوسف: 29","question":"ما سرّ التعبير في قوله لها: ﴿إنك كنت من الخاطئين﴾ بصيغة المذكر الجمع؟","answer":"﴿الخاطئين﴾ جمع يغلب فيه التذكير ويشمل جنس المذنبين، فيضع فعلها ضمن خطأ أخلاقي عام لا خصوص النساء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص489–490، تحت «نكتة التعبير بـ﴿الخاطئين﴾»","url":""}]},{"id":"s12-72","number":72,"surah":12,"verses":[30],"references":[{"surah":12,"verses":[30]}],"verseLabel":"يوسف: 30","question":"ما سرّ التعبير في قول نسوة المدينة: ﴿تراود فتاها عن نفسه﴾ بالمضارع؟","answer":"يستحضر المضارع صورة المراودة كأنها حاضرة، ويدل على استمرارها وتعلقها بيوسف وإصرارها؛ فزاد ذلك في لوم النسوة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص498، تحت «دلالة قولهن ﴿تراود﴾ بالمضارع»","url":""}]},{"id":"s12-73","number":73,"surah":12,"verses":[30],"references":[{"surah":12,"verses":[30]}],"verseLabel":"يوسف: 30","question":"ما دلالة قول النسوة: ﴿قد شغفها حبًا﴾؟","answer":"الشغاف غلاف القلب أو سويداؤه؛ فالصورة تجعل الحب قد نفذ إلى أعماقها واستولى عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص499، تحت «بلاغة الاستعارة في لفظ (الشغف)»","url":""}]},{"id":"s12-74","number":74,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما سرّ إعداد المتكأ للنسوة قبل خروج يوسف عليهن؟","answer":"هيأت لهن مجلس راحة وطعامًا يحتاج إلى القطع، لتجري المواجهة في حال اطمئنان وتكون دهشتهن عند ظهوره أبلغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص512، تحت «سر التعبير بـ﴿متكأ﴾»","url":""}]},{"id":"s12-229","number":229,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة إيتاء كل واحدة من النسوة سكينًا؟","answer":"جعلت السكين في يد كل واحدة ليظهر أثر المفاجأة عليهن جميعًا حين ينشغلن بجمال يوسف عن الإحساس بأيديهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص514، تحت «دلالة التعبير بـ﴿وآتت كل واحدة منهن سكينًا﴾»","url":""}]},{"id":"s12-230","number":230,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة أمر امرأة العزيز يوسف بقولها: ﴿اخرج عليهن﴾؟","answer":"يدل الأمر على أنها رتبت ظهوره المفاجئ في اللحظة التي أرادتها لتقيم الحجة على النسوة بما سيشاهدنه بأنفسهن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص516، تحت «دلالة الأمر في ﴿اخرج﴾»","url":""}]},{"id":"s12-75","number":75,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما نكتة تعليق إكبار النسوة ليوسف بمجرد رؤيته؟","answer":"يدل على أن رؤيته وحدها أحدثت في نفوسهن دهشة بالغة قبل كلام أو تعامل، تصويرًا لقوة أثر جماله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص518، تحت «نكتة تعليق الإكبار بالرؤية»","url":""}]},{"id":"s12-231","number":231,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة تضعيف الفعل في قوله: ﴿وقطعن أيديهن﴾؟","answer":"صيغة التفعيل تصور تكرر الجرح أو شدته في أيديهن من فرط الانبهار، والمراد الجرح لا إبانة الأيدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص519، تحت «دلالة تضعيف الفعل ﴿قطعن﴾»","url":""}]},{"id":"s12-76","number":76,"surah":12,"verses":[31],"references":[{"surah":12,"verses":[31]}],"verseLabel":"يوسف: 31","question":"ما دلالة قول النسوة: ﴿ما هذا بشرًا إن هذا إلا ملك كريم﴾؟","answer":"لم يجدن في معيارهن البشري جمالًا يفسر المشهد، فنفين عنه البشرية على سبيل المبالغة وشبهنه بملك متخيل الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص523، تحت «براعة التشبيه في ﴿ما هذا بشرًا إن هذا إلا ملك كريم﴾»","url":""}]},{"id":"s12-77","number":77,"surah":12,"verses":[32],"references":[{"surah":12,"verses":[32]}],"verseLabel":"يوسف: 32","question":"ما نكتة تعبير امرأة العزيز عن المراودة بصيغة الأمر؟","answer":"تحولت بعد تصريحها بالمراودة إلى طلب الطاعة والإلزام، كأن الاستجابة لها أمر يجب تنفيذه لا رغبة قابلة للرفض.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص534، تحت «نكتة التعبير عن المراودة بالأمر»","url":""}]},{"id":"s12-232","number":232,"surah":12,"verses":[32],"references":[{"surah":12,"verses":[32]}],"verseLabel":"يوسف: 32","question":"ما سرّ تهديد امرأة العزيز يوسف بالسجن بعد مراودته؟","answer":"لما عجز الترغيب استعانت بسلطانها وهددته بعقوبة تسلب حريته وتذله، لتكرهه على ما امتنع منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص535، تحت «سر التعبير بـ(السجن)»","url":""}]},{"id":"s12-78","number":78,"surah":12,"verses":[32],"references":[{"surah":12,"verses":[32]}],"verseLabel":"يوسف: 32","question":"ما دلالة اختلاف التوكيد في ﴿ليسجنن وليكونًا من الصاغرين﴾؟","answer":"أكدت تهديدها بالنونين. ومن الأوجه التي يذكرها المصدر تخصيص السجن بالنون الثقيلة لأنها أقدر عليه من إيقاع الصغار به؛ فجاءت الخفيفة مع الصغار. ووصفه بأنه من الصاغرين يصور إرادتها إلحاقه بجملة الأذلاء بعد عزته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص535، تحت «نكتة التأكيد بالنونين: الثقيلة والخفيفة»","url":""}]},{"id":"s12-79","number":79,"surah":12,"verses":[33],"references":[{"surah":12,"verses":[33]}],"verseLabel":"يوسف: 33","question":"ما سرّ التعبير في قول يوسف: ﴿السجن أحب إلي مما يدعونني إليه﴾؟","answer":"ليس السجن محبوبًا لذاته، وإنما هو أهون عليه من الوقوع في المعصية. فعبّر بالحب عن اختياره أخف الضررين، مبينًا قوة تمسكه بالعفة وإن أدى ذلك إلى السجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص544، تحت «نكتة التعبير عن المبغوض بشدة الحب»","url":""}]},{"id":"s12-80","number":80,"surah":12,"verses":[33],"references":[{"surah":12,"verses":[33]}],"verseLabel":"يوسف: 33","question":"ما وجه البلاغة في التعبير بالصرف وبالمضارع في قوله تعالى: ﴿وإلا تصرف عني كيدهن أصب إليهن﴾؟","answer":"مع طهارته لم يعتمد على نفسه، بل اعترف بضعف الطبيعة البشرية وطلب الصرف الإلهي؛ وهذا أبلغ في صدق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص549، تحت «بلاغة التعبير بالصرف وبالمضارع»","url":""}]},{"id":"s12-81","number":81,"surah":12,"verses":[34],"references":[{"surah":12,"verses":[34]}],"verseLabel":"يوسف: 34","question":"ما النكتة البلاغية في التعبير بـ﴿فاستجاب﴾؟","answer":"استجاب الله دعاءه فصرف عنه كيدهن، أي أبعد عنه أثر الإغراء وحماه من الميل إليهن؛ أما السجن فجاء بعد ذلك بقرار القوم، وليس هو عين الاستجابة المذكورة في الآية.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص554، تحت «نكتة التعبير بـ﴿فاستجاب﴾»","url":""}]},{"id":"s12-82","number":82,"surah":12,"verses":[34],"references":[{"surah":12,"verses":[34]}],"verseLabel":"يوسف: 34","question":"ما دلالة ختم الاستجابة بقوله: ﴿إنه هو السميع العليم﴾؟","answer":"هو السميع لدعاء يوسف، العليم بحاله وصدق التجائه إليه وما يحيط به من كيد؛ فجاء الاسمان تعليلًا مناسبًا لاستجابة دعائه وصرف السوء عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص558، تحت «سر ختم الآية بـ﴿السميع العليم﴾»","url":""}]},{"id":"s12-83","number":83,"surah":12,"verses":[35],"references":[{"surah":12,"verses":[35]}],"verseLabel":"يوسف: 35","question":"ما دلالة قوله: ﴿من بعد ما رأوا الآيات﴾ في سياق قرار سجن يوسف؟","answer":"الآيات دلائل براءته التي ظهرت لهم؛ فذكر رؤيتها يبين أنهم سجنوه مع علمهم ببراءته، لإخفاء الخبر وتهدئة الحديث عنه. وبذلك يكشف السياق ظلم القرار، لا خفاء الدليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص563، تحت «سر التعبير بالرؤية ﴿رأوا﴾»","url":""}]},{"id":"s12-84","number":84,"surah":12,"verses":[35],"references":[{"surah":12,"verses":[35]}],"verseLabel":"يوسف: 35","question":"ما سرّ التعبير في قوله تعالى: ﴿ليسجننه حتى حين﴾ دون تحديد؟","answer":"لأن غرضهم إبعاد القضية إلى أن تخمد، لا تنفيذ عقوبة ثابتة؛ فناسبه زمن مجهول يخضع لمصلحتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص564، تحت «دلالة تنكير ﴿حين﴾»","url":""}]},{"id":"s12-85","number":85,"surah":12,"verses":[36],"references":[{"surah":12,"verses":[36]}],"verseLabel":"يوسف: 36","question":"ما سرّ التعبير في قول أحد الفتيين: ﴿إني أراني أعصر خمرًا﴾ مع أنه يعصر عنبًا؟","answer":"سمّى الشيء بما سيؤول إليه؛ فالرؤيا تعرض النتيجة في مقدماتها، وهذا من المجاز باعتبار المآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص573، تحت «بلاغة المجاز في ﴿أعصر خمرًا﴾»","url":""}]},{"id":"s12-86","number":86,"surah":12,"verses":[36],"references":[{"surah":12,"verses":[36]}],"verseLabel":"يوسف: 36","question":"ما دلالة تعليل طلب تأويل الرؤيا بقول الفتيين: ﴿إنا نراك من المحسنين﴾؟","answer":"جاءت الجملة تعليلًا لطلبهما؛ فقد شاهدا من إحسانه ما بعث ثقتهما به ورجاءهما أن يحسن إليهما بالتأويل. وفي إدخاله في جماعة المحسنين ثناء عليه واستمالة له إلى إجابة سؤالهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص576، تحت «علة الفصل في ﴿إنا نراك من المحسنين﴾»","url":""}]},{"id":"s12-87","number":87,"surah":12,"verses":[37],"references":[{"surah":12,"verses":[37]}],"verseLabel":"يوسف: 37","question":"ما دلالة تقديم يوسف الدعوة إلى التوحيد على تأويل رؤيا الفتيين؟","answer":"اغتنم إقبالهما عليه وثقتهما بعلمه ليبين لهما ما هو أهم من تعبير الرؤيا: توحيد الله. وقدم ما يطمئنهما إلى علمه، ثم نسبه إلى تعليم ربه، فمهّد لقبول دعوته قبل بيان مصير الرؤيتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص582، تحت «نكتة تقديم الهداية على تقديم تأويل الرؤيا»","url":""}]},{"id":"s12-88","number":88,"surah":12,"verses":[37],"references":[{"surah":12,"verses":[37]}],"verseLabel":"يوسف: 37","question":"ما علة الفصل: ﴿ذلكما مما علمني ربي﴾؟","answer":"نسب علمه إلى تعليم ربه، فبيّن مصدر هذه المعرفة وأثار شوق السائلين إلى معرفة الرب الذي علّمه. و«مما» تفيد أن ما أظهره بعض ما وهبه الله من العلم، مع التواضع له وشكر إحسانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص588، تحت «علة الفصل: ﴿ذلكما مما علمني ربي﴾»","url":""}]},{"id":"s12-89","number":89,"surah":12,"verses":[38],"references":[{"surah":12,"verses":[38]}],"verseLabel":"يوسف: 38","question":"ما الغرض البلاغي من جملة: ﴿واتبعت ملة آبائي﴾؟","answer":"أثبت أن توحيده امتداد لرسالة راسخة لا فكرة نشأت في السجن، وجمع نسب النبوة مع شكر فضل الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص603، تحت «غرض جملة: ﴿واتبعت ملة آبائي﴾»","url":""}]},{"id":"s12-90","number":90,"surah":12,"verses":[38],"references":[{"surah":12,"verses":[38]}],"verseLabel":"يوسف: 38","question":"ما دلالة صيغة الجحود في قوله: ﴿ما كان لنا أن نشرك بالله﴾؟","answer":"تفيد شدة انتفاء الشرك عن يوسف وآبائه وعدم استقامته في حقهم، لما ثبتوا عليه من التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص606، تحت «دلالة التعبير بصيغة الجحود»","url":""}]},{"id":"s12-233","number":233,"surah":12,"verses":[38],"references":[{"surah":12,"verses":[38]}],"verseLabel":"يوسف: 38","question":"ما دلالة ﴿من﴾ في قوله: ﴿أن نشرك بالله من شيء﴾؟","answer":"جاءت لاستغراق النفي، فأغلقت باب استثناء أي شيء يمكن أن يتخذ شريكًا مع الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص608، تحت «دلالة دخول ﴿من﴾»","url":""}]},{"id":"s12-91","number":91,"surah":12,"verses":[39],"references":[{"surah":12,"verses":[39]}],"verseLabel":"يوسف: 39","question":"ما النكتة البلاغية في ندائهما بـ﴿يا صاحبي السجن﴾؟","answer":"جمعهما معه في وصف الصحبة بمكان يشتركون في شدته، فآنسهما وتحبب إليهما وقرّب نفوسهما إلى قبول النصيحة. فالنداء يمهّد لسماع الدعوة إلى التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص619، تحت «نكتة ندائهما بـ﴿يا صاحبي السجن﴾»","url":""}]},{"id":"s12-92","number":92,"surah":12,"verses":[39],"references":[{"surah":12,"verses":[39]}],"verseLabel":"يوسف: 39","question":"ما دلالة السؤال: ﴿أأرباب متفرقون خير أم الله الواحد القهار﴾؟","answer":"عرض المقارنة في صورة سؤال ليحمل المخاطبين على إعمال العقل: أرباب مختلفة عاجزة مقهورة، أم الله المتفرد بالألوهية والقاهر لكل شيء؟ والمفاضلة تنزّل في المحاورة لإبطال عبادتهم، وليست إثباتًا لخيرية الأصنام.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص620، تحت «معنى الاستفهام في ﴿أأرباب متفرقون﴾»","url":""}]},{"id":"s12-93","number":93,"surah":12,"verses":[40],"references":[{"surah":12,"verses":[40]}],"verseLabel":"يوسف: 40","question":"ما دلالة وصف المعبودات بأنها ﴿أسماء سميتموها﴾؟","answer":"نزع عنها كل حقيقة وسلطان؛ لم يبق من ألوهيتها إلا أسماء اخترعها البشر وورثوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص631، تحت «براعة التعبير بالأسماء في باب العبادة»","url":""}]},{"id":"s12-94","number":94,"surah":12,"verses":[40],"references":[{"surah":12,"verses":[40]}],"verseLabel":"يوسف: 40","question":"ما سرّ التعبير في قوله تعالى: ﴿إن الحكم إلا لله﴾ بعد نفي سلطان الأصنام؟","answer":"بعد أن نفى وجود حجة على ألوهية الأصنام، حصر الحكم في الله وحده؛ فهو الذي يأمر عباده، وقد أمر بإفراده بالعبادة. وبذلك جاء الأمر بالتوحيد نتيجة لما تقرر من اختصاصه بالحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص637، تحت «دلالة التعقيب بـ﴿أمر ألا تعبدوا إلا إياه﴾»","url":""}]},{"id":"s12-95","number":95,"surah":12,"verses":[40],"references":[{"surah":12,"verses":[40]}],"verseLabel":"يوسف: 40","question":"ما دلالة وصف التوحيد بأنه ﴿الدين القيم﴾؟","answer":"لأنه مستقيم في دليله، مقيم لحياة الإنسان، لا اعوجاج فيه كتعدد الآلهة؛ لكن أكثر الناس لا يدركون هذه الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص639، تحت «سر وصف الدين بالقيم»","url":""}]},{"id":"s12-96","number":96,"surah":12,"verses":[41],"references":[{"surah":12,"verses":[41]}],"verseLabel":"يوسف: 41","question":"ما دلالة تكرار نداء ﴿يا صاحبي السجن﴾ عند تأويل الرؤيا؟","answer":"بعد الاستطراد الدعوي أعاد رابط الصحبة لينقل إلى الجواب الشخصي برفق، حتى مع قسوة مصير أحدهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص646، تحت «دلالة التكرار في ﴿يا صاحبي السجن﴾»","url":""}]},{"id":"s12-97","number":97,"surah":12,"verses":[41],"references":[{"surah":12,"verses":[41]}],"verseLabel":"يوسف: 41","question":"ما سرّ التعبير بالماضي ﴿قضي﴾؟","answer":"التأويل وحي محقق لا ظن قابل للتغيير؛ فجاء الماضي ﴿قضي﴾ ليصور النتيجة كأنها انتهت.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص653، تحت «سر التعبير بالماضي ﴿قضي﴾»","url":""}]},{"id":"s12-98","number":98,"surah":12,"verses":[42],"references":[{"surah":12,"verses":[42]}],"verseLabel":"يوسف: 42","question":"ما سرّ التعبير في قوله للناجي: ﴿اذكرني عند ربك﴾؟","answer":"الأمر هنا التماس من صاحب عُرف بالمودة؛ طلب أن يذكر الناجي قضيته ومظلوميته عند الملك ليظهر أمره وتنظر قضيته. واكتفى بـ«اذكرني» عن تفصيل الحال التي كان مخاطبه يعرفها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص662، تحت «معنى الأمر في الفعل ﴿اذكرني﴾»","url":""}]},{"id":"s12-99","number":99,"surah":12,"verses":[42],"references":[{"surah":12,"verses":[42]}],"verseLabel":"يوسف: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿فأنساه الشيطان ذكر ربه﴾، ومن الذي أنساه؟","answer":"يذكر المصدر وجهين لمرجع الضمير: يوسف، فيكون النسيان متعلقًا بذكر ربه؛ أو الناجي، فيكون قد نسي ذكر يوسف عند سيده. ثم يبين السياق امتداد لبث يوسف في السجن، وتختلف صلة ذلك بالنسيان باختلاف الوجه التفسيري.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص663، تحت «وجه تعدد مرجع الضمير في ﴿فأنساه﴾»","url":""}]},{"id":"s12-100","number":100,"surah":12,"verses":[43],"references":[{"surah":12,"verses":[43]}],"verseLabel":"يوسف: 43","question":"ما دلالة تطابق العدد في البقرات والسنابل مع سنوات تأويل يوسف؟","answer":"تقابل البقرات السمان والسنابل الخضر سبع سنوات الخصب، وتقابل العجاف واليابسات سبع سنوات القحط. فالتطابق يربط صور الرؤيا بمددها التي بُني عليها إرشاد يوسف إلى الزراعة والادخار، دون أن يبيّن النص علة اختيار العدد سبعة في ذاته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص731، تحت «وجه تشبيه البقرات والسنبلات بالسنين»","url":""}]},{"id":"s12-101","number":101,"surah":12,"verses":[43],"references":[{"surah":12,"verses":[43]}],"verseLabel":"يوسف: 43","question":"ما نكتة طلب الملك تعبير الرؤيا بلفظ ﴿أفتوني﴾؟","answer":"يدل الإفتاء على طلب بيان قائم على علم واختصاص، لا مجرد حدس عابر، لأن الرؤيا أقلقت الملك وأراد جوابًا موثوقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص678، تحت «نكتة التعبير بالإفتاء في تعبير الرؤيا»","url":""}]},{"id":"s12-234","number":234,"surah":12,"verses":[43],"references":[{"surah":12,"verses":[43]}],"verseLabel":"يوسف: 43","question":"ما دلالة الشرط في قوله: ﴿إن كنتم للرؤيا تعبرون﴾؟","answer":"يختبر قدرتهم ويعلق طلب الجواب على تحقق خبرتهم في التعبير، وفيه تعريض بالشك في بلوغهم منزلته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص678، تحت «دلالة ﴿إن﴾»","url":""}]},{"id":"s12-102","number":102,"surah":12,"verses":[44],"references":[{"surah":12,"verses":[44]}],"verseLabel":"يوسف: 44","question":"ما دلالة وصف الرؤيا بأنها ﴿أضغاث أحلام﴾ بالجمع؟","answer":"شبّهوا ما رأوه أخلاطًا من الرؤى بحزم النبات المختلط، فزعموا أنها لا تنتظم في تأويل. ومن أوجه الجمع أن الرؤيا الواحدة تضمنت صورًا وأجزاء مختلفة؛ ويذكر المصدر أيضًا المبالغة في وصفها بالأباطيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص684، تحت «بلاغة الاستعارة في تركيب ﴿أضغاث أحلام﴾»","url":""}]},{"id":"s12-103","number":103,"surah":12,"verses":[44],"references":[{"surah":12,"verses":[44]}],"verseLabel":"يوسف: 44","question":"ما دلالة قول الملأ: ﴿وما نحن بتأويل الأحلام بعالمين﴾؟","answer":"من أوجه تفسيره أنهم نفوا علمهم بتأويل الأخلاط التي زعموا أنها ليست رؤيا صادقة، اعتذارًا عن الجواب مع الاحتفاظ بدعوى معرفة التعبير. ويذكر المصدر وجهًا آخر يحمل كلامهم على الاعتراف بالعجز عن التأويل عمومًا؛ فلا ينحصر معنى الجملة في الوجه الأول.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص688، تحت «دلالة النفي في ﴿وما نحن﴾»","url":""}]},{"id":"s12-104","number":104,"surah":12,"verses":[45],"references":[{"surah":12,"verses":[45]}],"verseLabel":"يوسف: 45","question":"ما سرّ التعبير في وصف الناجي بقوله تعالى: ﴿وادكر بعد أمة﴾؟","answer":"تذكر يوسف بعد مدة طويلة؛ والكلمة تصور غياب الذكر وسط زمن ممتد ثم عودته فجأة عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص703، تحت «بلاغة التعبير بلفظ ﴿أمة﴾»","url":""}]},{"id":"s12-105","number":105,"surah":12,"verses":[45],"references":[{"surah":12,"verses":[45]}],"verseLabel":"يوسف: 45","question":"ما بلاغة قول الناجي: ﴿أنا أنبئكم بتأويله﴾ مع أن يوسف هو الذي سيؤوله؟","answer":"أسند الإنباء إلى نفسه لأنه سبب الوصول إلى صاحب التأويل وناقل جوابه إلى الملك، وهذا من المجاز العقلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص703، تحت «بلاغة المجاز العقلي في ﴿أنا أنبئكم بتأويله﴾»","url":""}]},{"id":"s12-235","number":235,"surah":12,"verses":[45],"references":[{"surah":12,"verses":[45]}],"verseLabel":"يوسف: 45","question":"ما دلالة الفاء في قول الناجي: ﴿فأرسلون﴾؟","answer":"تفيد سرعة ترتيب طلب الإرسال على وعده بالإتيان بالتأويل؛ فطريق الحل عنده يتوقف على بلوغ يوسف في السجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص706، تحت «بلاغة العطف بالفاء في قوله: ﴿فأرسلون﴾»","url":""}]},{"id":"s12-106","number":106,"surah":12,"verses":[46],"references":[{"surah":12,"verses":[46]}],"verseLabel":"يوسف: 46","question":"ما دلالة نداء يوسف بوصف ﴿أيها الصديق﴾؟","answer":"خاطبه بالوصف الذي عرفه به من صدق القول والتأويل وحسن السيرة في السجن؛ فـ﴿الصديق﴾ صيغة مبالغة في الصدق.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص711، تحت «بلاغة اصطفاء جملة النداء ﴿أيها الصديق﴾»","url":""}]},{"id":"s12-107","number":107,"surah":12,"verses":[46],"references":[{"surah":12,"verses":[46]}],"verseLabel":"يوسف: 46","question":"ما دلالة إعادة وصف البقرات والسنابل بالتفصيل عند سؤال يوسف؟","answer":"إعادة الرؤيا بلفظها تدفع توهم أن الساقي تصرف فيها أو حكاها بالمعنى؛ فتؤكد أمانته في النقل. كما أن اختلاف اللفظ قد يؤثر في التأويل، فاقتضى المقام الحفاظ على تفاصيلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص713، تحت «دلالة الإطناب بتكرار نص الرؤيا وإعادتها بلفظها»","url":""}]},{"id":"s12-108","number":108,"surah":12,"verses":[47],"references":[{"surah":12,"verses":[47]}],"verseLabel":"يوسف: 47","question":"ما دلالة اقتران تأويل الرؤيا بإرشادهم إلى الزراعة والادخار؟","answer":"لم يقتصر على تأويل الرؤيا، بل ضم إليه إرشادهم إلى ما يفعلونه في سنوات الخصب؛ فدلهم على الزراعة المتتابعة وحفظ أكثر الحصاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص723، تحت «دلالة العدول من الخبر إلى الأمر»","url":""}]},{"id":"s12-109","number":109,"surah":12,"verses":[47],"references":[{"surah":12,"verses":[47]}],"verseLabel":"يوسف: 47","question":"ما دلالة الأمر في قوله: ﴿فما حصدتم فذروه في سنبله﴾؟","answer":"هو إرشاد عملي إلى إبقاء أكثر المحصول في سنبله ليحفظ مدة أطول استعدادًا لسنوات القحط.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص723، تحت «دلالة الخطاب بالأمر في قوله: ﴿فذروه﴾»","url":""}]},{"id":"s12-236","number":236,"surah":12,"verses":[47],"references":[{"surah":12,"verses":[47]}],"verseLabel":"يوسف: 47","question":"ما دلالة الاستثناء في قوله: ﴿إلا قليلًا مما تأكلون﴾؟","answer":"يحصر المستهلك في قدر قليل للحاجة، ويوجه إلى ادخار معظم الحصاد بدل استهلاكه في سنوات الخصب.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص724، تحت «دلالة الاستثناء في قوله: ﴿إلا قليلًا﴾»","url":""}]},{"id":"s12-110","number":110,"surah":12,"verses":[48],"references":[{"surah":12,"verses":[48]}],"verseLabel":"يوسف: 48","question":"ما دلالة وصف السنوات بـ﴿سبع شداد﴾؟","answer":"نقل الشدة من الناس إلى السنين نفسها، كأن الزمن كله اشتد عليهم؛ وهي صورة لشمول القحط وطوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص730، تحت «بلاغة المجاز في وصف السني بالشداد»","url":""}]},{"id":"s12-111","number":111,"surah":12,"verses":[48],"references":[{"surah":12,"verses":[48]}],"verseLabel":"يوسف: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿يأكلن ما قدمتم لهن﴾ عن السنين؟","answer":"شخص سنوات القحط ككائنات جائعة تلتهم المخزون؛ فالصورة توقظ الخوف وتدفع إلى الادخار المنظم.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص730، تحت «بلاغة الاستعارة في إسناد فعل الأكل إلى السنين»","url":""}]},{"id":"s12-112","number":112,"surah":12,"verses":[49],"references":[{"surah":12,"verses":[49]}],"verseLabel":"يوسف: 49","question":"ما دلالة قوله تعالى بعد سنوات الشدة: ﴿فيه يغاث الناس﴾؟","answer":"يبشر بانكشاف القحط؛ فاللفظ يحتمل نزول الغيث وإغاثة الناس من الشدة، وصيغته تصور الفرج واقعًا عليهم من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص737، تحت «دلالة التعبير بلفظ ﴿يغاث﴾ مادة وصيغة»","url":""}]},{"id":"s12-237","number":237,"surah":12,"verses":[49],"references":[{"surah":12,"verses":[49]}],"verseLabel":"يوسف: 49","question":"ما براعة ختام التأويل بقوله: ﴿وفيه يعصرون﴾؟","answer":"العصر دليل وفرة الثمار بعد الجدب وعودة الانتفاع بها؛ فختم التأويل بصورة محسوسة لتجدد الخصب والنماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص739، تحت «براعة الختام بلفظ ﴿يعصرون﴾»","url":""}]},{"id":"s12-113","number":113,"surah":12,"verses":[50],"references":[{"surah":12,"verses":[50]}],"verseLabel":"يوسف: 50","question":"ما دلالة تقديم يوسف طلب التحقيق على الخروج من السجن؟","answer":"أراد براءة علنية قبل الحرية، حتى لا يخرج بعفو يوهم بقاء التهمة؛ فقدم صفاء السمعة على عجلة الخلاص.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص746، تحت «بلاغة صوغ مضمون السؤال ﴿ما بال النسوة﴾»","url":""}]},{"id":"s12-114","number":114,"surah":12,"verses":[50],"references":[{"surah":12,"verses":[50]}],"verseLabel":"يوسف: 50","question":"ما دلالة السؤال عن النسوة دون التصريح بامرأة العزيز؟","answer":"يذكر المصدر أوجهًا منها أن النسوة شاهدات على أصل القصة، فالسؤال عنهن يؤسس لإظهار البراءة بالحجة؛ ومنها التلطف وعدم مواجهة العزيز بإفراد زوجته بالاتهام، مع إمكان وصول التحقيق إلى الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص747، تحت «نكتة تعيين ﴿النسوة﴾ موضوعًا لسؤاله دون (امرأة العزيز)»","url":""}]},{"id":"s12-115","number":115,"surah":12,"verses":[50],"references":[{"surah":12,"verses":[50]}],"verseLabel":"يوسف: 50","question":"ما دلالة ختم كلام يوسف بقوله: ﴿إن ربي بكيدهن عليم﴾؟","answer":"على تفسير «ربي» بالله، يتضمن الكلام تفويض الأمر إلى من أحاط علمه بحقيقة الكيد، والثقة بظهور البراءة، مع عدم سرد تفاصيل القصة للرسول. واسم الرب المضاف إليه يستحضر لطف الله به وإحسانه، وصفة العلم تلائم خفاء الكيد على الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص751، تحت «علة ختم الآية بصفة العلم»","url":""}]},{"id":"s12-116","number":116,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قول الملك: ﴿ما خطبكن إذ راودتن يوسف﴾ فنسب المراودة إليهن جميعًا؟","answer":"يعرض المصدر أوجهًا: أنهن شاركن في المراودة أو التحريض عليها؛ أو أن تعميم السؤال كان طريقًا إلى استنطاق الحقيقة من غير تعيين المرأة ابتداء. ففي توجيه الخطاب إليهن جميعًا استقصاء للقضية وتمهيد لظهور الاعتراف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص755، تحت «نكتة إسناد المراودة إلى ضمير النسوة»","url":""}]},{"id":"s12-117","number":117,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما براعة استهلال النسوة جوابهن بقولهن: ﴿حاش لله﴾؟","answer":"بدأن بالتنزيه والتعجب من نسبة السوء إلى يوسف، فمهد الاستهلال لشهادة قاطعة ببراءته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص758، تحت «براعة الاستهلال في جملة ﴿حاش لله﴾»","url":""}]},{"id":"s12-238","number":238,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما فائدة ﴿من﴾ في قول النسوة: ﴿ما علمنا عليه من سوء﴾؟","answer":"تفيد استغراق النفي، فتشمل شهادتهن نفي أدنى سوء يمكن أن ينسب إلى يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص761، تحت «فائدة ﴿من﴾ في قوله: ﴿من سوء﴾»","url":""}]},{"id":"s12-118","number":118,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما سرّ التعبير في قول امرأة العزيز: ﴿الآن حصحص الحق﴾؟","answer":"حصحص أي ظهر وتمكن بعد خفاء؛ و﴿الآن﴾ تعلن انتهاء زمن المواربة أمام تحقيق أعاد القضية من جديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص763، تحت «إيثار لفظ ﴿حصحص﴾ على (ظهر)»","url":""}]},{"id":"s12-119","number":119,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما بلاغة قول امرأة العزيز: ﴿أنا راودته عن نفسه﴾؟","answer":"قدمت ضميرها لتخص نفسها بالفعل وتتحمل مسؤوليته صراحة، فصدر الاعتراف من مصدر الاتهام نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص766، تحت «بلاغة تقديم المسند إليه على المسند الفعلي»","url":""}]},{"id":"s12-239","number":239,"surah":12,"verses":[51],"references":[{"surah":12,"verses":[51]}],"verseLabel":"يوسف: 51","question":"ما دلالة إتباع اعتراف امرأة العزيز بقولها: ﴿وإنه لمن الصادقين﴾؟","answer":"جاءت الجملة توكيدًا لبراءة يوسف؛ فجمعت اعترافها بفعلها وشهادتها بصدقه، فأبطلت التهمة من أصلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص767، تحت «موقع جملة ﴿وإنه لمن الصادقين﴾ مما قبله»","url":""}]},{"id":"s12-120","number":120,"surah":12,"verses":[52],"references":[{"surah":12,"verses":[52]}],"verseLabel":"يوسف: 52","question":"ما دلالة اختلاف المفسرين في قائل: ﴿ذلك ليعلم أني لم أخنه بالغيب﴾؟","answer":"إذا كان من كلام يوسف، فهو يبين أن التحقيق لإثبات أمانته وعدم خيانته العزيز. وإذا كان من كلام امرأة العزيز، فهي تبين أن اعترافها يبرئ يوسف في غيبته من الكذب عليه. ويرجح المصدر اتصال الكلام باعترافها؛ لأن حمله على كلام يوسف يستلزم انتقالًا وحذفًا في سياق الحوار.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص786، تحت «دلالة آراء المفسرين في تحديد القائل في السياق»","url":""}]},{"id":"s12-121","number":121,"surah":12,"verses":[52],"references":[{"surah":12,"verses":[52]}],"verseLabel":"يوسف: 52","question":"ما وجه البلاغة في المجاز في إسناد الهدي إلى الكيد في قوله تعالى: ﴿وأن الله لا يهدي كيد الخائنين﴾؟","answer":"لا يوصله إلى غايته المحمودة؛ فقد طال الكيد لكنه انتهى إلى ظهور البراءة ورفعة من أريد إسقاطه.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص776، تحت «بلاغة المجاز في إسناد الهدي إلى الكيد»","url":""}]},{"id":"s12-122","number":122,"surah":12,"verses":[53],"references":[{"surah":12,"verses":[53]}],"verseLabel":"يوسف: 53","question":"ما نكتة توالي المؤكدات في قوله: ﴿إن النفس لأمارة بالسوء﴾؟","answer":"تقرر المؤكدات تمكن هذا الميل في النفس إذا تركت لهواها، وأنها كثيرة الأمر بالسوء.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص788، تحت «نكتة توالي المؤكدات»","url":""}]},{"id":"s12-240","number":240,"surah":12,"verses":[53],"references":[{"surah":12,"verses":[53]}],"verseLabel":"يوسف: 53","question":"ما دلالة الاستثناء في قوله: ﴿إلا ما رحم ربي﴾؟","answer":"يبين أن العصمة من اندفاع النفس إلى السوء ليست بقوة الإنسان وحده، وإنما برحمة الله وتوفيقه وتزكيته.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص789، تحت «دلالة الاستثناء في ﴿إلا ما رحم ربي﴾»","url":""}]},{"id":"s12-123","number":123,"surah":12,"verses":[53],"references":[{"surah":12,"verses":[53]}],"verseLabel":"يوسف: 53","question":"ما دلالة ختم الكلام عن النفس بقوله: ﴿إن ربي غفور رحيم﴾؟","answer":"يحث الختام على الرجوع إلى الله والطمع في مغفرته ورحمته بعد الاعتراف بالتقصير. وقدم «غفور» لأن المغفرة رفع للمؤاخذة بالذنب، ثم ذكر الرحمة التي تتضمن الإحسان إلى من غفر له.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص792، تحت «فائدة تذييل الآية بـ﴿غفور رحيم﴾»","url":""}]},{"id":"s12-124","number":124,"surah":12,"verses":[54],"references":[{"surah":12,"verses":[54]}],"verseLabel":"يوسف: 54","question":"ما سرّ التعبير في قول الملك أولًا: ﴿ائتوني به﴾ ثم قال بعد كلامه: ﴿إنك اليوم لدينا مكين أمين﴾؟","answer":"طلبه أولًا إعجابًا بعلمه وبراءته، فلما كلمه اختبر شخصيته فزاده قربًا وثقة؛ انتقل من الاستدعاء إلى التمكين.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص801، تحت «دلالة ذكر جملة ﴿كلمه﴾»","url":""}]},{"id":"s12-125","number":125,"surah":12,"verses":[54],"references":[{"surah":12,"verses":[54]}],"verseLabel":"يوسف: 54","question":"ما دلالة الجمع بين ﴿مكين﴾ و﴿أمين﴾ في وصف يوسف؟","answer":"جمع له المكانة التي يتمكن بها من التصرف والأمانة التي تحفظ ما يوكل إليه. فالصفتان أساس لصلاح من يتولى مصالح الدولة؛ ويذكر المصدر تقديم المكانة لأنها عنوان القدرة على الولاية وتنفيذ شؤونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص804، تحت «علة تقديم ﴿مكين﴾ على ﴿أمين﴾ في السياق»","url":""}]},{"id":"s12-126","number":126,"surah":12,"verses":[55],"references":[{"surah":12,"verses":[55]}],"verseLabel":"يوسف: 55","question":"ما دلالة طلب يوسف تولّي ﴿خزائن الأرض﴾؟","answer":"رأى أزمة قادمة وعلم قدرته على إدارتها، فطلب الولاية للمصلحة العامة لا لمجرد الجاه؛ ويجوز للخبير أن يعرف بكفايته عند الحاجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص805، تحت «دلالة التعبير في ﴿اجعلني﴾»","url":""}]},{"id":"s12-127","number":127,"surah":12,"verses":[55],"references":[{"surah":12,"verses":[55]}],"verseLabel":"يوسف: 55","question":"ما النكتة البلاغية في اختيار هذين الوصفين: ﴿حفيظ عليم﴾؟","answer":"الحفظ أمانة الموارد، والعلم حسن التدبير؛ فجمع الصفتين اللتين تحتاجهما خزائن دولة تستقبل مجاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج22، ص807، تحت «نكتة اختيار هذين الوصفين: ﴿حفيظ عليم﴾»","url":""}]},{"id":"s12-128","number":128,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما نكتة اسم الإشارة للبعيد في قوله: ﴿وكذلك مكنا ليوسف في الأرض﴾؟","answer":"يشير إلى التمكين العظيم الذي دبره الله ليوسف على نحو بعيد المنزلة، بعد انتقاله من السجن إلى الولاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص13، تحت «نكتة التعبير باسم الإشارة للبعيد ﴿وكذلك﴾»","url":""}]},{"id":"s12-241","number":241,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما وجه البلاغة في الكناية في ﴿يتبوأ منها حيث يشاء﴾؟","answer":"هو كناية عن سعة تصرف يوسف واستقراره وتمكنه في أرض مصر بعد أن كان مقيدًا في السجن.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص18، تحت «بلاغة الكناية في ﴿يتبوأ منها حيث يشاء﴾»","url":""}]},{"id":"s12-129","number":129,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما دلالة قوله بعد تمكين يوسف: ﴿نصيب برحمتنا من نشاء﴾؟","answer":"جاءت الجملة مستأنفة لتقرر أن التمكين أثر من رحمة الله يخص بها من يشاء بحكمته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص18، تحت «نكتة الفصل: ﴿نصيب برحمتنا من نشاء﴾»","url":""}]},{"id":"s12-242","number":242,"surah":12,"verses":[56],"references":[{"surah":12,"verses":[56]}],"verseLabel":"يوسف: 56","question":"ما فائدة عطف قوله: ﴿ولا نضيع أجر المحسنين﴾ على ذكر الرحمة؟","answer":"جمع بين الفضل الإلهي وحفظ جزاء الإحسان؛ فتمكين يوسف رحمة من الله، وهو أيضًا ثمرة إحسان محفوظ لا يضيع.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص20، تحت «فائدة العطف في ﴿ولا نضيع﴾»","url":""}]},{"id":"s12-130","number":130,"surah":12,"verses":[57],"references":[{"surah":12,"verses":[57]}],"verseLabel":"يوسف: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿ولأجر الآخرة خير للذين آمنوا وكانوا يتقون﴾ بعد تمكين يوسف؟","answer":"حتى لا تنتهي القصة عند نجاح دنيوي؛ فما عند الله خير وأبقى، والتمكين لا يعوض عن أجر الإيمان والتقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص23، تحت «نكتة إضافة الأجر إلى ﴿الآخرة﴾»","url":""}]},{"id":"s12-131","number":131,"surah":12,"verses":[58],"references":[{"surah":12,"verses":[58]}],"verseLabel":"يوسف: 58","question":"ما دلالة مقابلة ﴿فعرفهم﴾ بقوله: ﴿وهم له منكرون﴾؟","answer":"عرفهم يوسف بمجرد النظر لأن ملامحهم لم تتغير كثيرًا، أما هم فلم يتوقعوا لقاءه في هذه المكانة بعد طول العهد وتغير سنه وهيئته. والجملة الاسمية تصور تمكن عدم معرفتهم به، في مقابل سرعة معرفته لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص33، تحت «نكتة العدول من الجملة الفعلية إلى الاسمية»","url":""}]},{"id":"s12-132","number":132,"surah":12,"verses":[59],"references":[{"surah":12,"verses":[59]}],"verseLabel":"يوسف: 59","question":"ما سرّ التعبير في قول يوسف: ﴿ائتوني بأخ لكم من أبيكم﴾؟","answer":"طلب إحضار أخيهم من أبيهم من غير أن يكشف لهم معرفته بهم، وجعل مجيئه شرطًا لاستمرار الكيل لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص36، تحت «معنى الباء، ودلالة تنكير ﴿بأخ﴾»","url":""}]},{"id":"s12-133","number":133,"surah":12,"verses":[59],"references":[{"surah":12,"verses":[59]}],"verseLabel":"يوسف: 59","question":"ما دلالة ترغيبهم بقوله: ﴿ألا ترون أني أوفي الكيل وأنا خير المنزلين﴾؟","answer":"جمع الترغيب المادي وحسن الضيافة ليطمئنوا إلى العودة، ثم أتبع ذلك بالتهديد إن لم يأتوا بأخيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص38، تحت «بلاغة الاستفهام، ونوعه، وغرضه»","url":""}]},{"id":"s12-134","number":134,"surah":12,"verses":[60],"references":[{"surah":12,"verses":[60]}],"verseLabel":"يوسف: 60","question":"ما نكتة قوله: ﴿فلا كيل لكم عندي﴾؟","answer":"نفت ﴿لا﴾ حصول أي كيل لهم نفيًا شاملًا، فجعل إحضار أخيهم شرطًا لا يقبل نقصًا أو تحايلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص44، تحت «نكتة التعبير بـ(لا) النافية للجنس»","url":""}]},{"id":"s12-243","number":243,"surah":12,"verses":[60],"references":[{"surah":12,"verses":[60]}],"verseLabel":"يوسف: 60","question":"ما بلاغة قوله: ﴿ولا تقربون﴾ بعد منع الكيل؟","answer":"هو كناية عن الطرد وقطع المعاملة والضيافة، فزاد التهديد على منع الطعام بمنع القرب كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص47، تحت «بلاغة الكناية في النهي عن القرب»","url":""}]},{"id":"s12-135","number":135,"surah":12,"verses":[61],"references":[{"surah":12,"verses":[61]}],"verseLabel":"يوسف: 61","question":"ما دلالة اختيار فعل المراودة في ﴿سنراود عنه أباه﴾؟","answer":"المراودة طلب متكرر برفق واستمالة، فاختيارها يدل على أنهم يتوقعون شدة تمسك الأب بابنه، وسيبذلون جهدًا لإقناعه. وفي إضافته إلى ضمير أخيهم «أباه» استحضار لخصوص تعلقه به.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص50، تحت «نكتة التعبير بالمراودة من حيث المادة والصيغة»","url":""}]},{"id":"s12-136","number":136,"surah":12,"verses":[62],"references":[{"surah":12,"verses":[62]}],"verseLabel":"يوسف: 62","question":"ما دلالة رد يوسف بضاعتهم خفية في رحالهم؟","answer":"أراد أن يجدوا ثمن الطعام عند رجوعهم فيعرفوا إكرامه لهم، ويكون ذلك أدعى إلى عودتهم مع أخيهم ويعينهم على شراء الطعام مرة أخرى. ويذكر المصدر أيضًا أنهم قد يتحرجون من المال فيرجعون لرده؛ ولفظ «لعل» يدل على رجاء الرجوع، لا ضمانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص59، تحت «معنى (لعل) في السياق»","url":""}]},{"id":"s12-137","number":137,"surah":12,"verses":[63],"references":[{"surah":12,"verses":[63]}],"verseLabel":"يوسف: 63","question":"ما دلالة بدء خطاب أبيهم بقولهم: ﴿منع منا الكيل﴾؟","answer":"قدموا خبر المنع ليربطوا طلب إرسال أخيهم بالحاجة إلى الطعام. والمراد قرار منع الكيل في الرحلة القادمة إن لم يأتوا به، لا أنهم عادوا هذه المرة بلا طعام؛ ثم جاءت الفاء في «فأرسل» لترتب طلبهم على هذا الخبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص68، تحت «نكتة تقديم شبه الجملة ﴿منا﴾»","url":""}]},{"id":"s12-138","number":138,"surah":12,"verses":[63],"references":[{"surah":12,"verses":[63]}],"verseLabel":"يوسف: 63","question":"ما دلالة تكرار ضمانهم: ﴿وإنا له لحافظون﴾؟","answer":"كرروا الضمان نفسه الذي قالوه في يوسف، فاستدعى كلامهم ذاكرة الجرح القديم بدل أن يطمئن الأب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص71، تحت «بلاغة تتابع المؤكدات في ﴿وإنا له لحافظون﴾»","url":""}]},{"id":"s12-139","number":139,"surah":12,"verses":[64],"references":[{"surah":12,"verses":[64]}],"verseLabel":"يوسف: 64","question":"ما سرّ التعبير في قول يعقوب: ﴿هل آمنكم عليه إلا كما أمنتكم على أخيه من قبل﴾؟","answer":"واجه التكرار بذاكرة التجربة: الضمان البشري فشل من قبل، ولذلك نقل الحفظ إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص79، تحت «الغرض من التشبيه في ﴿إلا كما أمنتكم﴾»","url":""}]},{"id":"s12-140","number":140,"surah":12,"verses":[64],"references":[{"surah":12,"verses":[64]}],"verseLabel":"يوسف: 64","question":"ما دلالة قول يعقوب: ﴿فالله خير حافظًا﴾؟","answer":"يقابل ضمان أبنائه بتفويض الحفظ إلى الله، فحفظه أكمل وأوثق من حفظ المخلوقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص82، تحت «دلالة التعبير بالمسند أفعل تفضيل ﴿خير﴾»","url":""}]},{"id":"s12-244","number":244,"surah":12,"verses":[64],"references":[{"surah":12,"verses":[64]}],"verseLabel":"يوسف: 64","question":"ما بلاغة تذييل قول يعقوب بقوله: ﴿وهو أرحم الراحمين﴾؟","answer":"تذييل ثابت المعنى يستجلب رحمة الله ويرجو أن يحفظ ابنه ويرده، وألا يجمع على يعقوب مصيبتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص84، تحت «بلاغة التذييل بالجملة الاسمية»","url":""}]},{"id":"s12-141","number":141,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما دلالة ﴿ما﴾ في قولهم: ﴿ما نبغي﴾؟","answer":"تحتمل الاستفهام: أي شيء نطلب بعد هذا الإحسان؟ وتحتمل النفي: لا نطلب فوق ما وجدنا؛ وفي الوجهين يظهر تعجبهم من رد بضاعتهم واستعطافهم أباهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص96، تحت «دلالة ﴿ما﴾ في قوله ﴿ما نبغي﴾»","url":""}]},{"id":"s12-245","number":245,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما موقع قولهم ﴿هذه بضاعتنا ردت إلينا﴾ من حجتهم؟","answer":"جاءت الجملة بيانًا عمليًا لما قبلها؛ فرد البضاعة برهان على إكرام العزيز لهم، وحجة يقنعون بها أباهم بإرسال أخيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص98، تحت «موقع ﴿هذه بضاعتنا﴾ مما قبلها ودلالته»","url":""}]},{"id":"s12-142","number":142,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما سر التعبير بـ﴿كيل بعير﴾ في قولهم: ﴿ونزداد كيل بعير﴾؟","answer":"حددت الإضافة مقدار الزيادة تحديدًا محسوسًا: حمل بعير كامل يخص أخاهم إذا صحبهم، فقرّبت المنفعة التي يرجونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص106، تحت «سر التعبير بالمفعول به مضافًا ﴿كيل بعير﴾»","url":""}]},{"id":"s12-246","number":246,"surah":12,"verses":[65],"references":[{"surah":12,"verses":[65]}],"verseLabel":"يوسف: 65","question":"ما موقع قوله: ﴿ذلك كيل يسير﴾ ودلالته؟","answer":"طمأنوا أباهم بأن زيادة حمل بعير أمر يسير على العزيز، ويحتمل أيضًا أن الموجود عندهم يسير لا يكفيهم؛ وكلا الوجهين يقوي طلب الرجوع بأخيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص107، تحت «موقع قوله: ﴿ذلك كيل يسير﴾ ودلالته»","url":""}]},{"id":"s12-143","number":143,"surah":12,"verses":[66],"references":[{"surah":12,"verses":[66]}],"verseLabel":"يوسف: 66","question":"ما دلالة طلب يعقوب ﴿موثقًا من الله﴾؟","answer":"أراد عهدًا عظيمًا مؤكدًا بالله، يجعل الوفاء به مسؤولية دينية لا مجرد وعد عائلي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص118، تحت «الغرض من تنكير المفعول به ﴿موثقًا﴾»","url":""}]},{"id":"s12-247","number":247,"surah":12,"verses":[66],"references":[{"surah":12,"verses":[66]}],"verseLabel":"يوسف: 66","question":"لماذا استثنى يعقوب قوله: ﴿إلا أن يحاط بكم﴾؟","answer":"استثنى ما يغلب طاقتهم من هلاك أو عجز يسد سبل الخلاص؛ لأن العهد إنما يلزمهم فيما يملكون فعله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص119، تحت «دلالة الاستثناء في ﴿إلا أن يحاط بكم﴾»","url":""}]},{"id":"s12-144","number":144,"surah":12,"verses":[66],"references":[{"surah":12,"verses":[66]}],"verseLabel":"يوسف: 66","question":"ما سر قول يعقوب: ﴿الله على ما نقول وكيل﴾ في جملة اسمية؟","answer":"تفيد الجملة ثبوت رقابة الله وحفظه للعهد؛ فانتقل التوثق من اتفاق بينهم إلى مسؤولية دائمة أمام الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص124، تحت «سر التعبير بمقول قوله جملة اسمية»","url":""}]},{"id":"s12-145","number":145,"surah":12,"verses":[67],"references":[{"surah":12,"verses":[67]}],"verseLabel":"يوسف: 67","question":"لماذا أمر يعقوب أبناءه أن يدخلوا من أبواب ﴿متفرقة﴾؟","answer":"أخذ بسبب الحذر من لفت الأنظار أو إصابة العين وهم جماعة ذوو هيئة، من غير اعتقاد أن السبب يرد قدر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص136، تحت «سر وصف أبواب بـ﴿متفرقة﴾»","url":""}]},{"id":"s12-146","number":146,"surah":12,"verses":[67],"references":[{"surah":12,"verses":[67]}],"verseLabel":"يوسف: 67","question":"ما دلالة النفي في قول يعقوب: ﴿وما أغني عنكم من الله من شيء﴾؟","answer":"ينفي أن تكون نصيحته ضامنة للسلامة؛ فهي سبب يؤخذ به، أما دفع قضاء الله فليس في قدرة بشر.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص137، تحت «دلالة ﴿ما﴾ النافية في قوله: ﴿وما أغني﴾»","url":""}]},{"id":"s12-248","number":248,"surah":12,"verses":[67],"references":[{"surah":12,"verses":[67]}],"verseLabel":"يوسف: 67","question":"ما دلالة القصر في قوله: ﴿إن الحكم إلا لله﴾؟","answer":"قصر الحكم على الله يقرر أن التدبير كله خاضع لقضائه، ولذلك صح أن يعقبه بتخصيصه بالتوكل.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص140، تحت «غرض التعبير بالقصر في السياق»","url":""}]},{"id":"s12-147","number":147,"surah":12,"verses":[68],"references":[{"surah":12,"verses":[68]}],"verseLabel":"يوسف: 68","question":"ما دلالة الاستثناء في قوله: ﴿إلا حاجة في نفس يعقوب قضاها﴾؟","answer":"يبين أن الدخول المتفرق لم يغير قدرًا مقدرًا، وإنما حقق حاجة يعقوب إلى الاحتياط والأخذ بالسبب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص152، تحت «دلالة الاستثناء في قوله: ﴿إلا حاجة﴾»","url":""}]},{"id":"s12-148","number":148,"surah":12,"verses":[69],"references":[{"surah":12,"verses":[69]}],"verseLabel":"يوسف: 69","question":"ما الغرض البلاغي من التعبير بالمجاز في قوله ﴿آوى﴾؟","answer":"صور ضم يوسف أخاه وتقريبه إليه بالإيواء؛ فانتقل به من الوحشة والخوف إلى الأنس والأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص168، تحت «غرض التعبير بالمجاز في قوله ﴿آوى﴾»","url":""}]},{"id":"s12-249","number":249,"surah":12,"verses":[69],"references":[{"surah":12,"verses":[69]}],"verseLabel":"يوسف: 69","question":"لماذا أكد يوسف قوله لأخيه: ﴿إني أنا أخوك﴾؟","answer":"تتابع التوكيد ليزيل استغراب الأخ بعد طول الغياب، ويثبت له حقيقة الأخوة بما يبدد خوفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص170، تحت «سر التعبير بالجملة الاسمية المؤكدة ثلاثًا»","url":""}]},{"id":"s12-250","number":250,"surah":12,"verses":[69],"references":[{"surah":12,"verses":[69]}],"verseLabel":"يوسف: 69","question":"ما غرض قوله لأخيه: ﴿فلا تبتئس بما كانوا يعملون﴾؟","answer":"نهى عن الحزن تسليةً له عما لقيه من إخوته، وطمأنه إلى أن الاجتماع بعد الفرقة قد أبدل الوحشة أمنًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص172، تحت «الغرض من التعبير بأسلوب النهي»","url":""}]},{"id":"s12-149","number":149,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"ما مناسبة جعل السقاية في رحل أخي يوسف لما سبق من تدبيره؟","answer":"كان جعل السقاية سببًا ظاهرًا يفتح طريق التفتيش ثم استبقاء أخيه وفق الحكم الذي سيقرره الإخوة أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص178، تحت «مناسبة الآية لما قبلها»","url":""}]},{"id":"s12-251","number":251,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"ما دلالة التعبير بالكيد على التعليم في قوله تعالى: ﴿كذلك كدنا ليوسف﴾؟","answer":"ينسب السياق تعليم هذا التدبير المحكم إلى الله؛ فالكيد هنا تدبير خفي لتحقيق غاية مشروعة، لا سرقة حقيقية ولا ظلمًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص227، تحت «دلالة التعبير بالكيد على التعليم»","url":""}]},{"id":"s12-150","number":150,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"ما أثر التوكيد في النداء: ﴿أيتها العير إنكم لسارقون﴾؟","answer":"جاء النداء والاسمية و«إن» واللام لتوقيف القافلة واستدعاء جوابها، وتصوير الاتهام في صورة جازمة بحسب ظاهر الحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص186، تحت «بلاغة جمع المؤكدات في جملة الفاصلة»","url":""}]},{"id":"s12-252","number":252,"surah":12,"verses":[70],"references":[{"surah":12,"verses":[70]}],"verseLabel":"يوسف: 70","question":"كيف يوجه إطلاق السرقة على إخوة يوسف؟","answer":"من أوجهه أن المنادي تكلم بحسب ظنه، أو أن الوصف عرّض بفعلهم القديم حين أخذوا يوسف من أبيه؛ فلا يلزم منه إثبات سرقة السقاية عليهم حقيقةً.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص187، تحت «وجه إطلاق السرقة عليهم»","url":""}]},{"id":"s12-151","number":151,"surah":12,"verses":[71],"references":[{"surah":12,"verses":[71]}],"verseLabel":"يوسف: 71","question":"ما دلالة إقبال الإخوة وسؤالهم: ﴿ماذا تفقدون﴾؟","answer":"إقبالهم على المنادي، بدل الهرب أو التجنب، يدل على ثقتهم ببراءتهم واستعدادهم للمواجهة. وقد سمعوا اتهام السرقة، لكنهم لم يعرفوا الشيء المفقود؛ فسألوا عنه بلفظ الفقد، مترفعين عن نسبة السرقة إلى أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص191–193، تحت «إيثار لفظ «وأقبلوا»؛ دلالة شبه الجملة؛ دلالة الاستفهام؛ إيثار التعبير بـ«تفقدون»»","url":""}]},{"id":"s12-152","number":152,"surah":12,"verses":[72],"references":[{"surah":12,"verses":[72]}],"verseLabel":"يوسف: 72","question":"ما دلالة الجمع بين ﴿حمل بعير﴾ و﴿وأنا به زعيم﴾؟","answer":"حمل البعير مكافأة وافرة من الطعام في وقت المجاعة، تحث على إحضار الصواع أو الدلالة عليه. ثم أكد المنادي ضمانه لها بقوله ﴿وأنا به زعيم﴾، أي كفيل ملتزم بأدائها؛ فاجتمع الترغيب بالمكافأة والتطمين إلى الوفاء بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص198–201، تحت «نكتة تخصيص المكافأة بـ«حمل بعير»؛ سر إيثار التعبير بـ«زعيم»؛ نكتة التعبير بصيغة فعيل»","url":""}]},{"id":"s12-153","number":153,"surah":12,"verses":[73],"references":[{"surah":12,"verses":[73]}],"verseLabel":"يوسف: 73","question":"ما أثر القسم بالتاء في قولهم: ﴿تالله لقد علمتم﴾؟","answer":"يفيد التعجب من اتهامهم مع تقوية احتجاجهم، إذ استشهدوا بما عرفه المخاطبون من سيرتهم وأمانتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص204، تحت «وجه القسم بالتاء وأثره»","url":""}]},{"id":"s12-253","number":253,"surah":12,"verses":[73],"references":[{"surah":12,"verses":[73]}],"verseLabel":"يوسف: 73","question":"لماذا قالوا: ﴿ما جئنا لنفسد﴾ ثم ﴿وما كنا سارقين﴾؟","answer":"نفوا أولًا قصد الإفساد وهو أعم، ثم نفوا أن تكون السرقة وصفًا ثابتًا فيهم؛ فجمعوا بين نفي القصد السيئ ونفي رسوخ الجريمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص209، تحت «براعة تباين الأسلوب في نفي السرقة، ونفي الإفساد»","url":""}]},{"id":"s12-154","number":154,"surah":12,"verses":[74,75],"references":[{"surah":12,"verses":[74,75]}],"verseLabel":"يوسف: 74–75","question":"ما دلالة سؤالهم: ﴿فما جزاؤه إن كنتم كاذبين﴾؟","answer":"أرادوا أن يقر الإخوة بأنفسهم جزاء من توجد السقاية في رحله، ليجري استبقاء أخي يوسف وفق الحكم الذي اختاروه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص213، تحت «بلاغة الاستفهام ودلالته»","url":""}]},{"id":"s12-155","number":155,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"ما سر البدء بأوعية الإخوة ثم وعاء أخي يوسف؟","answer":"أفادت ﴿ثم﴾ الترتيب المقصود؛ فأخر وعاء أخيه ليجري التفتيش في صورة طبيعية بعيدة عن التهمة، ثم يظهر المطلوب في النهاية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص225، تحت «سر إيثار العطف بـ«ثم»»","url":""}]},{"id":"s12-156","number":156,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"كيف يُوجَّه بلاغيًا الإشارة في «كذلك»، وما سرّ التعبير بلفظ الكيد مضافًا إلى ضمير التعظيم، وما دلالة التعبير بالكيد على التعليم؟","answer":"المقصود تدبير الله ليوسف وتعليمه الحيلة التي أبقى بها أخاه، بأن أجرى الأخذ وفق الحكم الذي قرره الإخوة أنفسهم. وإسناد الكيد إلى الله هنا يدل على تدبير نافذ خفي عنهم، والإشارة في ﴿كذلك﴾ تعظم شأن هذا التدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص226–228، تحت «توجيه الإشارة في «كذلك»؛ سر التعبير بلفظ الكيد مضافًا إلى ضمير التعظيم؛ دلالة التعبير بالكيد على التعليم»","url":""}]},{"id":"s12-157","number":157,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"ما دلالة النفي في «ما كان ليأخذ»، وما دلالة اللام في حيز النفي، وما دلالة تعليق فعل الأخذ، بالجار والمجرور، وما وجه البلاغة في جملة الاستثناء؟","answer":"قانون الملك لا يجيز استبقاء السارق بهذه الصورة، فجعل الله الإخوة ينطقون بالحكم الذي يسمح ليوسف بأخذ أخيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص228–230، تحت «دلالة النفي في «ما كان ليأخذ»؛ دلالة اللام في حيز النفي؛ دلالة تعليق فعل الأخذ، بالجار والمجرور؛ بلاغة جملة الاستثناء»","url":""}]},{"id":"s12-158","number":158,"surah":12,"verses":[76],"references":[{"surah":12,"verses":[76]}],"verseLabel":"يوسف: 76","question":"ما وجه البلاغة في التعبير بـ«ذي علم»؟","answer":"يجعل العلم درجات لا يحيط صاحب درجة بما فوقها، وينتهي كمال العلم إلى الله؛ فمهما بلغ العالم بقي فوقه من هو أعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص234، تحت «بلاغة التعبير بـ«ذي علم»»","url":""}]},{"id":"s12-159","number":159,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة قولهم: ﴿إن يسرق فقد سرق أخ له من قبل﴾ في جملة شرطية؟","answer":"علقوا اتهامهم القديم على فرض سرقته الحاضرة، ليوهموا أن الفعل متكرر في الأخوين ويبعدوا التهمة عن أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص239، تحت «دلالة التعبير بالجملة الشرطية»","url":""}]},{"id":"s12-254","number":254,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"لماذا قالوا: ﴿أخ له﴾ ولم يصرحوا بأخوتهم جميعًا؟","answer":"أضافوا الأخ إليه وحده تنصلًا منهما وإشعارًا بأنهما منفصلان عن بقية الإخوة في هذا الوصف المزعوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص240، تحت «علة التعبير بشبه الجملة «له»»","url":""}]},{"id":"s12-160","number":160,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة الجمع بين ﴿فأسرها يوسف في نفسه﴾ و﴿ولم يبدها لهم﴾؟","answer":"أكد الجمع بين الإسرار ونفي الإبداء شدة كظمه وتحمله للأذى؛ فلم يظهر لهم غضبه ولا ما يدور في نفسه بقول أو فعل. ويبين السياق ما قاله في نفسه: ﴿أنتم شر مكانًا والله أعلم بما تصفون﴾؛ فالمقام ثناء على ضبط النفس مع شدة الإساءة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص240–244، تحت «نكتة تضعيف فعل الإسرار «فأسرها»؛ بلاغة الإطناب؛ إيثار لفظ يبدي على يظهر؛ بلاغة الاستئناف»","url":""}]},{"id":"s12-161","number":161,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة اسم التفضيل في قول يوسف: ﴿أنتم شر مكانًا﴾؟","answer":"رد الاتهام عن أخيه بأن مكانهم في الشر أشد، لأنهم جمعوا الإساءة القديمة إلى يوسف مع الافتراء الجديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص245، تحت «دلالة التعبير باسم التفضيل»","url":""}]},{"id":"s12-255","number":255,"surah":12,"verses":[77],"references":[{"surah":12,"verses":[77]}],"verseLabel":"يوسف: 77","question":"ما دلالة الفعل «تصفون»؟","answer":"سمى كلامهم وصفًا لا حقيقة مقررة، وفوض علم باطنه إلى الله؛ فجمع الرد المهذب مع تكذيب افترائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص246، تحت «دلالة الفعل «تصفون»»","url":""}]},{"id":"s12-162","number":162,"surah":12,"verses":[78],"references":[{"surah":12,"verses":[78]}],"verseLabel":"يوسف: 78","question":"لماذا نادوا يوسف بقولهم: ﴿يا أيها العزيز﴾؟","answer":"توسلوا إليه بلقب سلطانه واستعطفوا صاحب القدرة على تنفيذ طلبهم، وفيه تعظيم يهيئ لقبول الرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص249، تحت «وجه نداء يوسف بصفة العزيز»","url":""}]},{"id":"s12-256","number":256,"surah":12,"verses":[78],"references":[{"surah":12,"verses":[78]}],"verseLabel":"يوسف: 78","question":"ما أثر جمعهم صفات أبيهم عند التماسهم أخذ أحدهم مكان أخيهم؟","answer":"جمعوا كبره وضعفه وشدة تعلقه بابنه في أوصاف منكرة تفخم الحال، ليستدروا عطف يوسف ويقووا طلب المبادلة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص251، تحت «سر جمع ثلاث صفات منكرة»","url":""}]},{"id":"s12-163","number":163,"surah":12,"verses":[78],"references":[{"surah":12,"verses":[78]}],"verseLabel":"يوسف: 78","question":"ما دلالة قول إخوة يوسف: ﴿إنا نراك من المحسنين﴾ في مقام استعطافه؟","answer":"جعلوا ما عرفوه من إحسانه علةً لرجاء استجابته وأخذ أحدهم مكان أخيهم؛ فالوصف مبني على أثر رأوه منه، لا على مدح مجرد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص255، تحت «وجه التعليل في جملة الفاصلة»","url":""}]},{"id":"s12-164","number":164,"surah":12,"verses":[79],"references":[{"surah":12,"verses":[79]}],"verseLabel":"يوسف: 79","question":"ما سر قول يوسف: ﴿معاذ الله﴾ عند طلب أخذ بريء مكان أخيه؟","answer":"المصدر الميمي يصور استعاذة راسخة والتجاءً إلى الله من فعل الظلم، فجاء رفضه مبدئيًا لا مجرد تعذر إداري.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص257، تحت «نكتة التعبير بالمصدر الميمي»","url":""}]},{"id":"s12-257","number":257,"surah":12,"verses":[79],"references":[{"surah":12,"verses":[79]}],"verseLabel":"يوسف: 79","question":"لماذا قال يوسف: ﴿إلا من وجدنا متاعنا عنده﴾ ولم يقل: من سرق؟","answer":"التزم بالحقيقة التي ثبتت في المشهد وهي وجود المتاع عنده، ولم ينسب إليه سرقة لم تقع؛ وفي ذلك دقة وعدل في العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص261، تحت «نكتة العدول عن الفعل سرق إلى الفعل «وجدنا»»","url":""}]},{"id":"s12-165","number":165,"surah":12,"verses":[80],"references":[{"surah":12,"verses":[80]}],"verseLabel":"يوسف: 80","question":"ما سرّ التعبير عن جماعة الإخوة بالمفرد ﴿نجيًا﴾؟","answer":"انفردوا عن الناس يتناجون سرًا بعد يأسهم من إطلاق أخيهم. و«نجي» يصح إطلاقه على الواحد والجماعة، ومن توجيهاته أنه مصدر وصف به الجمع للمبالغة، فكأنهم في تلك الساعة صاروا مناجاة خالصة؛ فجمعت العبارة القصيرة اعتزال الناس والتشاور المكتوم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص267–270، تحت «نكتة التعبير بلفظ «نجيًا»، في هذه الآية القرآنية؛ دلالة مجيء الحال «نجيًا»، مصدرًا في السياق؛ بلاغة الإيجاز في قولهم «خلصوا نجيًا»»","url":""}]},{"id":"s12-166","number":166,"surah":12,"verses":[80],"references":[{"surah":12,"verses":[80]}],"verseLabel":"يوسف: 80","question":"ما سرّ التعبير في قول كبيرهم: ﴿ومن قبل ما فرطتم في يوسف﴾؟","answer":"ذكّرهم كبيرهم بتقصيرهم السابق في حق يوسف ليزيد تأكيد مسؤوليتهم عن الميثاق الجديد. ولفظ التفريط يصور تضييع الحق وإهمال حفظه؛ فاجتمع في عتابه العهد الذي قطعوه الآن والسابقة التي تجعل رجوعهم دون أخيهم أشد على أبيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص274–276، تحت «موقع جملة «ومن قبل ما فرطتم»؛ دلالة التعبير بالتفريط في «فرطتم»؛ دلالة الظرفية في قوله «في يوسف»»","url":""}]},{"id":"s12-167","number":167,"surah":12,"verses":[80],"references":[{"surah":12,"verses":[80]}],"verseLabel":"يوسف: 80","question":"ما دلالة قرار كبيرهم: ﴿فلن أبرح الأرض حتى يأذن لي أبي أو يحكم الله لي﴾؟","answer":"فرع قراره بالبقاء في مصر على الميثاق الذي أخذه أبوهم وعلى تفريطهم السابق في يوسف؛ فلا يرجع من تلقاء نفسه، بل ينتظر إذن أبيه أو ما يقضي الله به في أمره. وتقديم إذن الأب يراعي حقه المباشر في العهد، ثم تفويض الأمر إلى الله يدل على الرضا بحكمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص271–272، 275–277، 279–282، تحت «نوع الاستفهام وغرضه، في «ألم تعلموا»؛ معنى الفاء في قوله تعالى «فلن أبرح»؛ وجه تقديم إذن الأب، على إذن الله تعالى؛ سر حذف متعلق «يحكم»، في السياق المحكم»","url":""}]},{"id":"s12-168","number":168,"surah":12,"verses":[81],"references":[{"surah":12,"verses":[81]}],"verseLabel":"يوسف: 81","question":"لماذا قال كبيرهم: ﴿ارجعوا إلى أبيكم﴾ ولم يقل: أبينا؟","answer":"واجههم بمسؤوليتهم في الرجوع والخبر، وأضاف الأب إليهم ليحملهم تبعة الموقف، مع ما يشعر به من انفرادٍ عن تصرفهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص273، تحت «سر إضافة الأب إلى ضمير المخاطب، دون التكلم»","url":""}]},{"id":"s12-169","number":169,"surah":12,"verses":[81],"references":[{"surah":12,"verses":[81]}],"verseLabel":"يوسف: 81","question":"ما وجه قولهم: ﴿وما شهدنا إلا بما علمنا وما كنا للغيب حافظين﴾؟","answer":"قصروا شهادتهم على ما ظهر لهم من استخراج الصواع من وعاء أخيهم، ثم احترسوا بقولهم ﴿وما كنا للغيب حافظين﴾: فهم لم يشاهدوا فعل السرقة نفسه، ولا يعلمون خفايا الواقعة. فالمقصود بيان مستند خبرهم وحدوده، لا الجزم بأن ظاهر الأمر يكشف حقيقته كلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص288–291، تحت «بلاغة القصر في قوله «وما شهدنا إلا بما علمنا»؛ لفظ العلم بين المجاز والاستعارة؛ بلاغة الاحتراس، في السياق»","url":""}]},{"id":"s12-170","number":170,"surah":12,"verses":[82],"references":[{"surah":12,"verses":[82]}],"verseLabel":"يوسف: 82","question":"ما وجه البلاغة في المجاز العقلي، في إسناد السؤال للقرية في قوله تعالى: ﴿واسأل القرية التي كنا فيها﴾؟","answer":"أسند السؤال إلى المكان والمراد أهله، ليبلغ الكلام غاية الاختصار ويؤكد أن الخبر مشهور يمكن التثبت منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص292، تحت «بلاغة المجاز العقلي، في إسناد السؤال للقرية»","url":""}]},{"id":"s12-258","number":258,"surah":12,"verses":[82],"references":[{"surah":12,"verses":[82]}],"verseLabel":"يوسف: 82","question":"ما وجه البلاغة في المجاز في سؤال العير في قوله تعالى: ﴿والعير التي أقبلنا فيها﴾؟","answer":"أطلقوا العير وأرادوا أصحاب القافلة، فوسعوا دائرة الشهادة وأظهروا أن الواقعة معلومة لمن صحبهم أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص294، تحت «بلاغة المجاز في سؤال العير»","url":""}]},{"id":"s12-171","number":171,"surah":12,"verses":[83],"references":[{"surah":12,"verses":[83]}],"verseLabel":"يوسف: 83","question":"ما دلالة تكرر ﴿بل سولت لكم أنفسكم أمرًا فصبر جميل﴾ في محنتي يوسف وأخيه؟","answer":"يعيد اللفظ تذكيرهم بما وقع في يوسف، ويصل المحنة الجديدة بأثر تلك السابقة، مع تعدد توجيهات التسويل في الموضع الثاني. وفي الحالين يلجأ يعقوب إلى الصبر الجميل، ثم يصرح هنا برجاء اجتماع أبنائه بقوله ﴿عسى الله أن يأتيني بهم جميعًا﴾؛ فتجدد المصاب لم يقطع رجاءه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص300–305، تحت «دلالة وصف الصبر بلفظ «جميل»؛ المتشابه اللفظي في «بل سولت»»","url":""}]},{"id":"s12-172","number":172,"surah":12,"verses":[83],"references":[{"surah":12,"verses":[83]}],"verseLabel":"يوسف: 83","question":"ما سرّ التعبير في قوله تعالى: ﴿أن يأتيني بهم جميعًا﴾ مع أن الخبر عن بنيامين؟","answer":"يرجو يعقوب اجتماع يوسف وأخيه والكبير الذي بقي في مصر؛ فجاء ضمير الجمع و﴿جميعًا﴾ ليتسع الرجاء لكل الغائبين. وهذا رجاء مؤسس على علم الله وحكمته، كما دل ختام الآية، لا مجرد انشغال بالمفقود الأخير وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص303–304، 308، تحت «معنى لفظ «عسى» في سياق الآية الكريمة؛ دلالة الموقع النحوي للفظ «جميعًا»؛ نكتة التذييل بالاسمين «العليم الحكيم»»","url":""}]},{"id":"s12-173","number":173,"surah":12,"verses":[84],"references":[{"surah":12,"verses":[84]}],"verseLabel":"يوسف: 84","question":"ما دلالة نداء يعقوب: ﴿يا أسفى على يوسف﴾؟","answer":"صور الأسف كأنه حاضر ينادى، مبالغةً في استحضار الحزن وتجدد الألم حين أعاد فقد الابن ذكرى يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص309، تحت «مجازات النداء وغرضه، في قوله «يا أسفى»»","url":""}]},{"id":"s12-259","number":259,"surah":12,"verses":[84],"references":[{"surah":12,"verses":[84]}],"verseLabel":"يوسف: 84","question":"لماذا خص يعقوب يوسف بالأسف مع تجدد فقد أخيه؟","answer":"لأن حزن يوسف كان الأصل الأقدم والأعمق، فجددت المصيبة الجديدة ذلك الجرح الكامن فغلب اسمه على التعبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص310، تحت «نكتة الاقتصار على التأسف على يوسف دون غيره»","url":""}]},{"id":"s12-174","number":174,"surah":12,"verses":[84],"references":[{"surah":12,"verses":[84]}],"verseLabel":"يوسف: 84","question":"ما دلالة الجمع بين ﴿وابيضت عيناه من الحزن﴾ و﴿فهو كظيم﴾؟","answer":"يصور ابيضاض العينين شدة أثر الحزن والبكاء في الجسد، بينما يدل ﴿كظيم﴾ على حبس الحزن وكتمه؛ وأصله إغلاق السقاء على ما فيه. فاجتمع ظهور أثر الألم مع إمساك النفس عن بث الشكوى للناس، دون أن ينافي ذلك شكواه إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص312–315، تحت «بلاغة الكناية في «وابيضت عيناه»؛ نكتة إيثار التعبير بـ«كظيم»، مادة وصيغة؛ بلاغة الاستعارة في لفظ كظيم»","url":""}]},{"id":"s12-175","number":175,"surah":12,"verses":[85],"references":[{"surah":12,"verses":[85]}],"verseLabel":"يوسف: 85","question":"ما وجه قولهم: ﴿تالله تفتأ تذكر يوسف حتى تكون حرضًا أو تكون من الهالكين﴾؟","answer":"تعجبوا من استمرار ذكره يوسف، وحذروه من أن ينتهي به الحزن إلى شدة المرض أو الهلاك؛ فـ﴿تفتأ﴾ هنا بمعنى لا تزال، وقد حذف النفي لدلالة القسم والسياق عليه. ثم أوضح يعقوب في جوابه أن شكواه إلى الله، فلا يصح أن يفهم حزنه على أنه انقطاع للرجاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص319–323، 328–329، تحت «نكتة القسم بـ«تالله» دون غيرها؛ نكتة التعبير بـ«تفتأ»، مادة وصيغة؛ نكتة التعبير بلفظ «حرضًا»؛ بلاغة تقديم الحرض على الهلاك؛ بلاغة القصر بالأداة «إنما»»","url":""}]},{"id":"s12-176","number":176,"surah":12,"verses":[86],"references":[{"surah":12,"verses":[86]}],"verseLabel":"يوسف: 86","question":"ما وجه البلاغة في القصر بالأداة «إنما»، وما دلالة تسمية الهم الثقيل بالبث، وما النكتة البلاغية في الجمع بين البث والحزن؟","answer":"حصر شكواه في الله؛ والبث حزن لا يستطيع صاحبه كتمانه، أما الصبر الجميل فلا يمنع إظهار الافتقار للخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص328–332، تحت «بلاغة القصر بالأداة «إنما»؛ دلالة تسمية الهم الثقيل بالبث؛ نكتة الجمع بين البث والحزن»","url":""}]},{"id":"s12-177","number":177,"surah":12,"verses":[86],"references":[{"surah":12,"verses":[86]}],"verseLabel":"يوسف: 86","question":"ما النكتة البلاغية في العطف في جملة «وأعلم»، وما معنى الحرف «من» في سياق الآية، وما معنى الحرف «ما» في السياق الكريم، وأين تتجلى براعة توطئة الأمر بالنداء؟","answer":"يبين يعقوب أن رجاءه يستند إلى علم من الله لا يحيط به أبناؤه. ومن توجيهات ذلك علمه بلطف الله ورحمته، أو بما أعلمه من حياة يوسف؛ وتذكر الموسوعة ثقته بأن رؤيا يوسف لم يتم تأويلها بعد. لذلك لم يحكم على الأمر بظاهره، ولم ينقطع أمله في الفرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص332–334، 340، تحت «نكتة العطف في جملة «وأعلم»؛ معنى الحرف «من» في سياق الآية؛ معنى الحرف «ما» في السياق الكريم؛ براعة توطئة الأمر بالنداء»","url":""}]},{"id":"s12-178","number":178,"surah":12,"verses":[87],"references":[{"surah":12,"verses":[87]}],"verseLabel":"يوسف: 87","question":"ما دلالة الأمر ﴿اذهبوا فتحسسوا من يوسف وأخيه﴾؟","answer":"التحسس طلب أخبارهما والتعرف إلى موضعهما بالحواس، سماعًا أو مشاهدة. وقد قدم الأمر بالذهاب ليربط البحث بالحركة والوصول إلى موضع السؤال؛ فرجاؤه في الله دفعه إلى توجيههم للتحري والعمل، ولم يبق رجاءً بلا سعي.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص340–342، تحت «نكتة انتقاء مفردة «اذهبوا»؛ بلاغة تفريع الأمر بالتحسس على الذهاب؛ معنى حرف «من»»","url":""}]},{"id":"s12-179","number":179,"surah":12,"verses":[87],"references":[{"surah":12,"verses":[87]}],"verseLabel":"يوسف: 87","question":"أين تتجلى براعة التعبير بمفردة «روح»، وما دلالة الإضافة، وما وجه البلاغة في القصر، وكيف يُوجَّه بلاغيًا تخصيص الكفر بالذكر؟","answer":"روح الله فرجه ورحمته التي تحيي القلب بعد الاختناق؛ واليأس منها سوء معرفة بسعة قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص343–347، تحت «براعة التعبير بمفردة «روح»؛ دلالة الإضافة؛ بلاغة القصر؛ توجيه تخصيص الكفر بالذكر»","url":""}]},{"id":"s12-180","number":180,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما غرض قولهم: ﴿مسنا وأهلنا الضر﴾؟","answer":"قدموا وصف حاجتهم لاستدرار الرحمة، وذكر الأهل يزيد الاستعطاف لأن وراءهم من ينتظر القوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص355، تحت «غرض الإخبار بالاحتياج والعوز»","url":""}]},{"id":"s12-260","number":260,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما دلالة وصف بضاعتهم بأنها ﴿مزجاة﴾؟","answer":"تصف بضاعة قليلة أو رديئة تُدفع ولا يرغب فيها عادة، فبينت ضعف ما يملكونه من ثمن وشدة حاجتهم إلى المسامحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص358، تحت «نكتة وصف البضاعة بلفظ «مزجاة»»","url":""}]},{"id":"s12-181","number":181,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما غرض قولهم: ﴿فأوف لنا الكيل﴾؟","answer":"طلبوا إتمام الكيل وألا ينقص بسبب قلة بضاعتهم أو رداءتها، بعد أن مهدوا بذكر حاجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص358، تحت «غرض الأمر»","url":""}]},{"id":"s12-261","number":261,"surah":12,"verses":[88],"references":[{"surah":12,"verses":[88]}],"verseLabel":"يوسف: 88","question":"ما دلالة إطلاق قولهم: ﴿وتصدق علينا﴾ من غير تعيين؟","answer":"حذف متعلق التصدق ليتسع لكل إحسان ممكن؛ من المسامحة في الثمن أو الزيادة في الكيل أو تفريج كربهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص360، تحت «بلاغة إطلاق الفعل بحذف متعلقه»","url":""}]},{"id":"s12-182","number":182,"surah":12,"verses":[89],"references":[{"surah":12,"verses":[89]}],"verseLabel":"يوسف: 89","question":"ما دلالة تمهيد يوسف للتعريف بنفسه بسؤال ﴿هل علمتم ما فعلتم بيوسف وأخيه إذ أنتم جاهلون﴾؟","answer":"ذكّرهم بسوء ما فعلوه ليوقظ إدراكهم لقبحه، وفي السؤال توبيخ على أمر يعلمونه. ثم لطف بهم بإرجاع ذلك إلى زمن جهلهم، إيماءً إلى إمكان الرجوع عن تلك الحال؛ فجمع بين تذكيرهم بالذنب وفتح باب الاعتذار، دون تعيير جارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص368–372، تحت «نكتة إيثار أداة «هل» على الهمزة؛ معنى «ما» ودلالتها؛ براعة الإيماء دون التصريح»","url":""}]},{"id":"s12-183","number":183,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما أثر التوكيد في قولهم: ﴿أإنك لأنت يوسف﴾؟","answer":"تراكم الاستفهام و«إن» واللام وضمير الفصل يصور صدمة التعرف: فالعزيز الذي أمامهم هو أخوهم الذي ألقوه في الجب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص373، تحت «براعة التأكيد وأثره في تصوير المشهد النفسي»","url":""}]},{"id":"s12-184","number":184,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"لماذا أجاب يوسف: ﴿أنا يوسف﴾ ولم يكتف بنعم؟","answer":"صرح باسمه ليحقق التعرف ويستحضر القصة الماضية، فجاء الجواب أوقع في نفوسهم من مجرد التصديق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص374، تحت «بلاغة العدول عن الجواب الموجز إلى التكرار»","url":""}]},{"id":"s12-262","number":262,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما دلالة التعبير باسم الإشارة للقريب في قوله تعالى: ﴿وهذا أخي﴾؟","answer":"أشار إلى أخيه الحاضر تشريفًا له وإظهارًا لاجتماعهما بعد الفرقة، وفي القرب الحسي ما يجسد تمام النعمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص374، تحت «دلالة التعبير باسم الإشارة للقريب»","url":""}]},{"id":"s12-263","number":263,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"لماذا قال يوسف: ﴿قد من الله علينا﴾؟","answer":"اختار المن ليجعل ما حصلا عليه من حفظ وتمكين واجتماع فضلًا عظيمًا خالصًا من الله، لا ثمرة قدرة ذاتية.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص375، تحت «نكتة اختيار لفظ المن»","url":""}]},{"id":"s12-185","number":185,"surah":12,"verses":[90],"references":[{"surah":12,"verses":[90]}],"verseLabel":"يوسف: 90","question":"ما معنى «من» ودلالتها الشرطية؟","answer":"جعلها قاعدة عامة بالشرط: كل من يجمع التقوى والصبر فهو من المحسنين الذين لا يضيع الله أجرهم، فلا تختص العبرة بقصة يوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص377، تحت «معنى «من» ودلالتها الشرطية»","url":""}]},{"id":"s12-186","number":186,"surah":12,"verses":[91],"references":[{"surah":12,"verses":[91]}],"verseLabel":"يوسف: 91","question":"ما دلالة اعترافهم: ﴿لقد آثرك الله علينا﴾؟","answer":"أقروا بأن رفعة يوسف اختيار وتفضيل من الله، فظهر بطلان حسدهم القديم وأن الفضل ليس مما يدفعه تدبيرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص383، تحت «براعة إيثار لفظ الإيثار»","url":""}]},{"id":"s12-264","number":264,"surah":12,"verses":[91],"references":[{"surah":12,"verses":[91]}],"verseLabel":"يوسف: 91","question":"أين تتجلى براعة استعمال فعل الكون في قوله تعالى: ﴿وإن كنا لخاطئين﴾؟","answer":"استعمال «كان» مع المؤكدات يصور اعترافًا صريحًا بثبوت الخطأ في ماضيهم، لا زلة عارضة يدفعون مسؤوليتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص385، تحت «براعة استعمال فعل الكون»","url":""}]},{"id":"s12-187","number":187,"surah":12,"verses":[92],"references":[{"surah":12,"verses":[92]}],"verseLabel":"يوسف: 92","question":"ما دلالة قول يوسف: ﴿لا تثريب عليكم﴾؟","answer":"التثريب هو اللوم والتقريع على الذنب؛ فنفاه يوسف نفيًا كاملًا إعلانًا للعفو والصفح عند القدرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص386، تحت «بلاغة استعمال لفظ التثريب»","url":""}]},{"id":"s12-265","number":265,"surah":12,"verses":[92],"references":[{"surah":12,"verses":[92]}],"verseLabel":"يوسف: 92","question":"بم يتعلق لفظ ﴿اليوم﴾ في قوله: ﴿لا تثريب عليكم اليوم يغفر الله لكم﴾؟","answer":"يجوز تعليقه بنفي التثريب، أي يعفو يوم قدرته عليهم وهو أحرى باللوم، ويجوز وصله بدعاء المغفرة؛ فلا ينحصر توجيهه في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص386، تحت «توجيه الوقف على لفظ «اليوم»»","url":""}]},{"id":"s12-188","number":188,"surah":12,"verses":[92],"references":[{"surah":12,"verses":[92]}],"verseLabel":"يوسف: 92","question":"ما دلالة التعبير بالمضارع «يغفر» دون الماضي، وما فائدة بناء فعل المغفرة للفاعل، وما فائدة العطف بين الجمل، وما النكتة البلاغية في استعمال صيغة التفضيل؟","answer":"بعد أن عفا عن حقه دعا لهم بالمغفرة من الله، مالك المغفرة وقابل التوبة. ويحتمل التعبير أيضًا البشارة بالمغفرة مع توبتهم وندمهم. وختمه بـ﴿وهو أرحم الراحمين﴾ تعليل للرجاء في عفو الله؛ فرحمته أوسع من رحمة كل راحم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص387–389، تحت «دلالة التعبير بالمضارع «يغفر» دون الماضي؛ فائدة بناء فعل المغفرة للفاعل؛ فائدة العطف بين الجمل؛ نكتة استعمال صيغة التفضيل»","url":""}]},{"id":"s12-189","number":189,"surah":12,"verses":[93],"references":[{"surah":12,"verses":[93]}],"verseLabel":"يوسف: 93","question":"ما دلالة عودة القميص في ختام قصة يوسف؟","answer":"حمل أولًا الدم الكاذب، ثم كان قدّه دليل البراءة، ثم عاد بالبشرى ورد البصر؛ فتحول من أداة حزن إلى علامة فرج واجتماع.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص395، تحت «رمزية القميص في القصة كلها»","url":""}]},{"id":"s12-266","number":266,"surah":12,"verses":[93],"references":[{"surah":12,"verses":[93]}],"verseLabel":"يوسف: 93","question":"ما دلالة علم يوسف بأن قميصه سيرد بصر أبيه؟","answer":"يعده المصدر من دلائل ما أطلع الله عليه نبيه يوسف؛ فتحقق الأثر بإذن الله شاهدًا على النبوة وصدق البشارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص399، تحت «دلالات غيب ودلائل إعجاز»","url":""}]},{"id":"s12-190","number":190,"surah":12,"verses":[94],"references":[{"surah":12,"verses":[94]}],"verseLabel":"يوسف: 94","question":"ما سرّ التعبير في قول يعقوب قبل وصول البشير: ﴿إني لأجد ريح يوسف﴾؟","answer":"وجد ريح يوسف قبل وصول البشير على بُعد، وهو إدراك أكرمه الله به؛ ولذلك استبعد الحاضرون قوله وظنوه من تعلقه القديم بيوسف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص405–408، 410–412، تحت «دلالة جواب «لما»؛ سر التعبير بالريح المضافة إلى يوسف؛ دلالة الوصف بالقديم»","url":""}]},{"id":"s12-191","number":191,"surah":12,"verses":[95],"references":[{"surah":12,"verses":[95]}],"verseLabel":"يوسف: 95","question":"ما أثر المؤكدات في قولهم: ﴿تالله إنك لفي ضلالك القديم﴾؟","answer":"كشف القسم و«إن» واللام رسوخ حكمهم الخاطئ على يعقوب، وشدة جزمهم بأن رجاءه لقاء يوسف بعيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص411، تحت «غرض اجتماع المؤكدات»","url":""}]},{"id":"s12-267","number":267,"surah":12,"verses":[95],"references":[{"surah":12,"verses":[95]}],"verseLabel":"يوسف: 95","question":"ما الصورة في قولهم: ﴿لفي ضلالك﴾؟","answer":"صور حرف الظرفية الضلال كأنه وعاء يحيط بيعقوب ويتمكن منه، بحسب زعمهم؛ ثم كشفت البشرى خطأ تقديرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص411، تحت «بلاغة الاستعارة باستعمال حرف الظرفية»","url":""}]},{"id":"s12-268","number":268,"surah":12,"verses":[95],"references":[{"surah":12,"verses":[95]}],"verseLabel":"يوسف: 95","question":"ما دلالة وصفهم ضلاله المزعوم بأنه ﴿القديم﴾؟","answer":"أرادوا أنه ما زال منذ زمن طويل متعلقًا بيوسف ويرجو لقاءه، فدل الوصف على استمرار ما أنكروه عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص412، تحت «دلالة الوصف بالقديم»","url":""}]},{"id":"s12-192","number":192,"surah":12,"verses":[96],"references":[{"surah":12,"verses":[96]}],"verseLabel":"يوسف: 96","question":"ما غرض الاستفهام في قول يعقوب: ﴿ألم أقل لكم إني أعلم من الله ما لا تعلمون﴾؟","answer":"استفهام تقريري يذكرهم بقوله السابق، وقد صار تحقق البشرى شاهدًا على صدق رجائه وعلمه من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص423، تحت «غرض الاستفهام «ألم أقل لكم»»","url":""}]},{"id":"s12-269","number":269,"surah":12,"verses":[96],"references":[{"surah":12,"verses":[96]}],"verseLabel":"يوسف: 96","question":"لماذا قال: ﴿ما لا تعلمون﴾ ولم يقل: إنكم جاهلون؟","answer":"نفى عنهم العلم الخاص الذي آتاه الله إياه من غير أن يواجههم بالتجهيل، فجمع تثبيت الحقيقة مع لطف الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص425، تحت «نكتة نفي العلم لا التجهيل»","url":""}]},{"id":"s12-193","number":193,"surah":12,"verses":[97],"references":[{"surah":12,"verses":[97]}],"verseLabel":"يوسف: 97","question":"ما أثر قول الأبناء: ﴿يا أبانا﴾ قبل طلب المغفرة؟","answer":"استعطفوا أباهم بنداء الأبوة، وأظهروا الرجوع إلى قربه بعد ما سببوه له من ألم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص427، تحت «غرض ذكر جملة النداء»","url":""}]},{"id":"s12-270","number":270,"surah":12,"verses":[97],"references":[{"surah":12,"verses":[97]}],"verseLabel":"يوسف: 97","question":"ما دلالة طلبهم: ﴿استغفر لنا ذنوبنا﴾؟","answer":"أقروا بحاجتهم إلى مغفرة الله وطلبوا من أبيهم أن يدعو لهم، فحل الندم محل الدفاع عن فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص428، تحت «غرض الأمر ودلالته»","url":""}]},{"id":"s12-271","number":271,"surah":12,"verses":[97],"references":[{"surah":12,"verses":[97]}],"verseLabel":"يوسف: 97","question":"لماذا جمعوا الذنوب في قولهم: ﴿استغفر لنا ذنوبنا﴾؟","answer":"يتسع الجمع لما ارتكبوه من ظلم يوسف وإيذاء أبيهم والكذب عليه، فكان اعترافهم شاملًا لا محصورًا في فعل واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص430، تحت «نكتة الجمع في قولهم «ذنوبنا»»","url":""}]},{"id":"s12-194","number":194,"surah":12,"verses":[98],"references":[{"surah":12,"verses":[98]}],"verseLabel":"يوسف: 98","question":"ما دلالة ﴿سوف﴾ في قول يعقوب ﴿سوف أستغفر لكم ربي﴾؟","answer":"هي وعد بالاستغفار في الاستقبال، لا رفض لطلبهم. وتذكر الموسوعة توجيهات، منها تحري وقت أنسب للإجابة كالسحر، وزيادة إخلاص الدعاء ودوامه، وتأديبهم حتى يزداد تضرعهم. ولا يلزم من اللفظ تعيين سبب واحد للتأخير؛ وخاتمة الآية ﴿إنه هو الغفور الرحيم﴾ تقوي رجاءهم في المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص432–435، تحت «فائدة إيثار «سوف» على حرف السين؛ دلالة السين والتاء؛ براعة اقتران اسمي «الغفور الرحيم»»","url":""}]},{"id":"s12-195","number":195,"surah":12,"verses":[99],"references":[{"surah":12,"verses":[99]}],"verseLabel":"يوسف: 99","question":"ما دلالة إيواء يوسف أبويه إليه في مشهد الدخول إلى مصر؟","answer":"الإيواء يدل على الضم والرعاية الخاصة والحنان؛ فجاء جوابًا للدخول ليصور مبادرته إلى إكرام أبويه بعد الفراق. ثم دعاهم إلى دخول مصر دخول استقرار وأمن. وتذكر الموسوعة في ترتيب المشهد احتمال استقبالهم خارجها، واحتمال أن يكون المراد الانتقال من دخول الضيوف إلى الإقامة فيها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص442–445، تحت «فائدة جعل «آوى» جواب «لما»؛ بلاغة استعمال الفعل «آوى»؛ دلالة عطف «وقال ادخلوا»؛ معنى الأمر في «ادخلوا مصر»»","url":""}]},{"id":"s12-196","number":196,"surah":12,"verses":[99],"references":[{"surah":12,"verses":[99]}],"verseLabel":"يوسف: 99","question":"ما سرّ التعبير في قوله تعالى: ﴿إن شاء الله آمنين﴾ وهو صاحب سلطة؟","answer":"في تعليق الأمن بمشيئة الله تفويض له، وإقرار بأن تحقق المطلوب لا يستقل به تدبير البشر. فهو أدب يصحب وعد يوسف لهم بالأمن مع ما أعطي من تمكين، ولفظ ﴿آمنين﴾ يشمل طمأنينة النفس وانتفاء الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص445–446، تحت «بلاغة الاحتراس في «إن شاء الله»؛ سر إيثار لفظ «آمنين» على سالمين»","url":""}]},{"id":"s12-197","number":197,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"لماذا قال: ﴿ورفع أبويه على العرش﴾ ولم يقل: أقعدهما؟","answer":"دل الرفع على التشريف وعلو المنزلة مع الارتفاع الحسي إلى سرير الملك، فجمع الإكرام المعنوي والمكاني.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص446، تحت «سر التعبير بالرفع لا بالإقعاد»","url":""}]},{"id":"s12-272","number":272,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما أثر إظهار لفظ ﴿أبويه﴾ بدل الضمير؟","answer":"يعيد استحضار منزلتهما في نفس يوسف ويبرز كمال بره وإكرامه لهما بعد طول الفراق.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص447، تحت «نكتة إظهار ما حقه الإضمار»","url":""}]},{"id":"s12-198","number":198,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما دلالة التعبير بالخرور في قوله: ﴿وخروا له سجدًا﴾؟","answer":"صور سرعة هويهم إلى السجود وتمام خضوعهم في المشهد الذي تحقق فيه تأويل رؤيا يوسف القديمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص448، تحت «بلاغة الاستعارة بالخرور»","url":""}]},{"id":"s12-273","number":273,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"هل تدل اللام في ﴿وخروا له سجدًا﴾ على عبادة يوسف؟","answer":"تعلق السجود بيوسف من جهة التحية والتعظيم أو لكونه سبب النعمة، مع كون الشكر والعبادة لله؛ فلا تحمل الآية على عبادته.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص449، تحت «دلالة اللام في «له»»","url":""}]},{"id":"s12-199","number":199,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما سرّ التعبير في قول يوسف: ﴿هذا تأويل رؤياي من قبل قد جعلها ربي حقًا﴾؟","answer":"التأويل ما آلت إليه الرؤيا وظهر مصداقه في الواقع؛ فالمشهد الحاضر حقق ما رآه من قبل. ونسب يوسف ذلك إلى ربه اعترافًا برعايته وتدبيره، ووصفه بالحق لأنه صار واقعًا ثابتًا بعد أن كان رؤيا رمزية تنتظر تحققها.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص449–452، تحت «سر إيثار «تأويل» على تعبير؛ غرض التأكيد بحرف «قد»؛ نكتة إيثار «ربي» على اسم الجلالة؛ بلاغة استعمال الحق دون الصدق»","url":""}]},{"id":"s12-200","number":200,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما سرّ ذكر نعمة الخروج من السجن دون الخروج من الجب؟","answer":"سترًا لإخوته في مقام الصفح والاجتماع، ولأن السجن أقرب النعم إلى التمكين؛ فلم يجدّد ذكر جريمتهم بعد العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص453–455، تحت «براعة تقييد الإحسان بالإخراج من السجن»","url":""}]},{"id":"s12-201","number":201,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"لماذا قال يوسف: ﴿نزغ الشيطان﴾ ولم يقل: وسوس؟","answer":"النزغ أدل على الإفساد والإغراء الذي أوقع العداوة والفعل، فهو أبلغ من مجرد حديث خفي في النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص457، تحت «بلاغة التعبير بالنزغ دون الوسوسة»","url":""}]},{"id":"s12-274","number":274,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما دلالة استعمال البينية في قوله تعالى: ﴿نزغ الشيطان بيني وبين إخوتي﴾؟","answer":"جعل الإفساد واقعًا بين الطرفين ترفقًا بإخوته، فلم يواجههم بإسناد الجناية إليهم وحدهم في مقام الصفح.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص458، تحت «دلالة استعمال البينية»","url":""}]},{"id":"s12-275","number":275,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"لماذا قال يوسف: ﴿وبين إخوتي﴾ ولم يقل: وبينكم؟","answer":"آثر الغيبة ووصف الأخوة ليلطف الخطاب ويطوي أثر المواجهة بالذنب، مؤكدًا بقاء رابطة الأخوة بعد العفو.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص459، تحت «فائدة إيثار الغيبة على الخطاب»","url":""}]},{"id":"s12-202","number":202,"surah":12,"verses":[100],"references":[{"surah":12,"verses":[100]}],"verseLabel":"يوسف: 100","question":"ما دلالة وصف الله بـ﴿لطيف لما يشاء﴾ بعد اجتماع الأسرة؟","answer":"اللطيف يعلم خفايا الأمور ويدبر مصالح عباده ويوصل الإحسان إليهم برفق ومن طرق تخفى عليهم. وهذا يلائم قصة يوسف؛ إذ تتابع لطف الله به حتى خرج من الجب والسجن واجتمع بأهله. وتعقيب الوصف بالعلم والحكمة يبين أن هذا التدبير قائم على إحاطة وحكمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص459–462، تحت «بلاغة المناسبة في صفة «لطيف»؛ سر التعدية باللام؛ سر اقتران صفتي «العليم الحكيم»»","url":""}]},{"id":"s12-203","number":203,"surah":12,"verses":[101],"references":[{"surah":12,"verses":[101]}],"verseLabel":"يوسف: 101","question":"ما دلالة دعاء يوسف ﴿توفني مسلمًا وألحقني بالصالحين﴾ بعد نعمة الملك والعلم؟","answer":"المقصود، وفق التوجيه الذي تعرضه الموسوعة، سؤال الثبات على الإسلام حتى الوفاة، لا استعجال الموت. وبعد ذكر نعم الله عليه سأل تمامها بحسن الخاتمة واللحاق بالصالحين؛ وفي طلب الإلحاق تواضع ورغبة في صحبتهم والاقتداء بمن سبقوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص467–469، 473–475، تحت «بلاغة اختيار فعل «توفني» دون أمتني؛ فائدة التعبير بـ«مسلمًا» دون مؤمنًا؛ بلاغة الكناية في استعمال «ألحقني»»","url":""}]},{"id":"s12-204","number":204,"surah":12,"verses":[101],"references":[{"surah":12,"verses":[101]}],"verseLabel":"يوسف: 101","question":"ما النكتة البلاغية في استعمال «فاطر»، وكيف يتجلى بديع فن الطباق «السماوات والأرض»، وما فائدة تقديم المسند إليه، وما وجه البلاغة في إيراد الخبر وإرادة الإنشاء، وكيف يتجلى فن الطباق «الدنيا والآخرة»؟","answer":"وصفه بفاطر السماوات والأرض يستحضر كمال قدرته وخلقه، ثم يقر بولايته ورعايته في الدنيا والآخرة جميعًا. وجملة ﴿أنت وليي﴾ تجمع الاعتراف بهذه الولاية والدعاء بدوامها؛ فالمعنى: كن وليي بالرعاية والنصرة والنجاة، لا أن نعمة الملك تغنيه عن ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج23، ص470–473، تحت «نكتة استعمال «فاطر»؛ بديع فن الطباق «السماوات والأرض»؛ فائدة تقديم المسند إليه؛ بلاغة إيراد الخبر وإرادة الإنشاء؛ فن الطباق «الدنيا والآخرة»»","url":""}]}]);
